// 公式2025年ルールブックの固定盤面に描かれた9つの入り江を、GEOの海岸辺へ対応付けたもの。
// 上側左の港から時計回り。港の種類だけを可変盤ルールどおりシャッフルする。
const OFFICIAL_PORT_EDGES=[34, 52, 68, 69, 60, 28, 13, 2, 18];
function officialPorts(){
  ports={};
  const types=shuffle(PORT_TYPES.slice());
  OFFICIAL_PORT_EDGES.forEach((eid,i)=>{ ports[eid]=types[i]; });
}

// 海岸線(境界)の辺: 両端の頂点が共有するヘクスが1つだけ
const BOUNDARY = new Set();
(function(){
  const vh={}; for(const k in GEO.vertex_hexes) vh[k]=new Set(GEO.vertex_hexes[k]);
  for(const e of GEO.edges){ const inter=[...vh[e.a]].filter(h=>vh[e.b].has(h)); if(inter.length===1) BOUNDARY.add(e.id); }
})();

// --- 状態 ----------------------------------------------------------------
let numPlayers = 4;
let active = 1;
let sim = null;                 // 初期配置シミュ: {order:[...], step, history:[{vid,p}]}
let composerOn = false;         // 手動配置モード（game/sim無しでエディタ配置を使う）
let composerOrder = [];         // 開拓地を置いた順（棋譜書き出し用）: [{p,vid},...]
let game = null;                // 対局モード（厳密ルール）の状態

// ===================== 対局モード：厳密ルールエンジン =====================
const RES5=["wood","brick","sheep","wheat","ore"];
const COST={road:{wood:1,brick:1}, settlement:{wood:1,brick:1,sheep:1,wheat:1}, city:{wheat:2,ore:3}, dev:{sheep:1,wheat:1,ore:1}};
const DEV_JP={knight:"騎士",vp:"勝利点",roads:"街道建設",plenty:"収穫",mono:"独占"};

function newDevDeck(){
  const d=[]; for(let i=0;i<14;i++)d.push("knight"); for(let i=0;i<5;i++)d.push("vp");
  for(let i=0;i<2;i++){d.push("roads");d.push("plenty");d.push("mono");}
  for(let i=d.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[d[i],d[j]]=[d[j],d[i]];}
  return d;
}
function occupantOf(vid){
  for(let p=1;p<=numPlayers;p++){
    const pl=placements[p]; if(!pl) continue;
    if(pl.settlements.has(vid)) return {p,type:"settlement"};
    if(pl.cities && pl.cities.has(vid)) return {p,type:"city"};
  }
  return null;
}
function bankOf(res){ let used=0; for(let p=1;p<=numPlayers;p++) used+=game.hands[p][res]; return 19-used; }
function handTotal(p){ return RES5.reduce((s,r)=>s+game.hands[p][r],0); }
function canPay(p,cost){ return Object.entries(cost).every(([r,n])=>game.hands[p][r]>=n); }
function pay(p,cost){ for(const [r,n] of Object.entries(cost)) game.hands[p][r]-=n; }
function gain(p,res,n){ game.hands[p][res]+=n; }
function cur(){ return game.order[game.idx]; }

// 最長交易路（敵の建物で分断。長さ5以上・単独首位で保持）
function longestRoadOf(p){
  const adj={};
  for(const id of placements[p].roads){ const e=GEO.edges[id];
    (adj[e.a]=adj[e.a]||[]).push({id,o:e.b}); (adj[e.b]=adj[e.b]||[]).push({id,o:e.a}); }
  let best=0;
  const dfs=(v,used,len)=>{
    best=Math.max(best,len);
    const oc=occupantOf(v); if(oc && oc.p!==p && len>0) return;
    for(const {id,o} of (adj[v]||[])){ if(used.has(id)) continue; used.add(id); dfs(o,used,len+1); used.delete(id); }
  };
  for(const v in adj) dfs(Number(v), new Set(), 0);
  return best;
}
function updateLongestRoad(){
  const lens={}; for(let p=1;p<=numPlayers;p++) lens[p]=longestRoadOf(p);
  let h=game.lr.holder;
  if(h && lens[h]<5) h=null;
  if(h==null){
    const mx=Math.max(0,...Object.values(lens));
    if(mx>=5){ const tops=Object.keys(lens).filter(k=>lens[k]===mx); if(tops.length===1) h=Number(tops[0]); }
  }else{
    for(let p=1;p<=numPlayers;p++) if(p!==h && lens[p]>lens[h] && lens[p]>=5) h=p;
  }
  game.lr={holder:h, len:h?lens[h]:0};
}
function updateLargestArmy(){
  let h=game.la.holder;
  for(let p=1;p<=numPlayers;p++){
    const k=game.army[p];
    if(k>=3 && (h==null || (p!==h && k>game.army[h]))) h=p;
  }
  game.la={holder:h, count:h?game.army[h]:0};
}
function vpOf(p){
  let vp=placements[p].settlements.size + 2*(placements[p].cities?placements[p].cities.size:0);
  if(game.lr.holder===p) vp+=2;
  if(game.la.holder===p) vp+=2;
  vp+=game.dev.hands[p].vp;
  return vp;
}
// 建物だけのVP（開拓地1点＋都市2点、ボーナス・カードを除く）。WIN_RACEのフェーズ判定用。
function buildingVpOf(p){
  return placements[p].settlements.size + 2*(placements[p].cities?placements[p].cities.size:0);
}
function checkWin(){
  if(game.phase==="over") return;
  const p=cur();
  if(vpOf(p)>=game.vpToWin){
    // 勝利ターンを棋譜に残す。勝利は建設途中に確定しendTurnGameが走らないため、
    // ここで snapshotTurn しないと「勝者が10点に到達した決定的な最終ターン」が丸ごと欠落する。
    game.phase="over";   // 最終コマの勝率を勝者100%として保存してから棋譜化
    glog(`🏆 P${p} が ${vpOf(p)}点で勝利！`, p);
    _recAct({a:"win", p, vp:vpOf(p)});
    game._winLogged=true;
    try{ snapshotTurn(); }catch(e){}
    toast(`🏆 P${p} が ${vpOf(p)}点で勝利！`);
  }
}

function startGame(fromReplayTurn){
  endSim(); showBest=false;
  document.getElementById("bestToggle").textContent="最善手を表示";
  document.getElementById("bestHint").style.display="none";
  const N=+document.getElementById("gamePlayers").value;
  numPlayers=N;
  const hands={},dev={deck:newDevDeck(),hands:{},bought:{},played:{}},army={};
  for(let p=1;p<=N;p++){ hands[p]={wood:0,brick:0,sheep:0,wheat:0,ore:0};
    dev.hands[p]={knight:0,vp:0,roads:0,plenty:0,mono:0}; dev.bought[p]={knight:0,vp:0,roads:0,plenty:0,mono:0};
    dev.played[p]={knight:0,vp:0,roads:0,plenty:0,mono:0}; army[p]=0; }
  const desert=GEO.hexes.find(h=>board[h.id].resource==="desert");
  game={order:Array.from({length:N},(_,i)=>i+1), idx:0, vpToWin:10,
        hands, dev, army, lr:{holder:null,len:0}, la:{holder:null,count:0},
        robber: desert?desert.id:0, dice:null, rolled:false, devPlayed:false,
        freeRoads:0, resume:null, discardQueue:[], stealCands:[], ask:null, ai:null,
        log:[], turns:[], diceCount:0, _acts:[], _actionFrames:[], _actionLogMark:0};
  if(fromReplayTurn){
    resetPlacements();
    for(const [vid,pp] of Object.entries(fromReplayTurn.sett)){ if(placements[pp]) placements[pp].settlements.add(Number(vid)); }
    for(const [vid,pp] of Object.entries(fromReplayTurn.city||{})){ if(placements[pp]){ placements[pp].cities=placements[pp].cities||new Set(); placements[pp].cities.add(Number(vid)); placements[pp].settlements.delete(Number(vid)); } }
    for(const [eid,pp] of Object.entries(fromReplayTurn.road)){ if(placements[pp]) placements[pp].roads.add(Number(eid)); }
    if(fromReplayTurn.robber!=null) game.robber=fromReplayTurn.robber;
    exitReplay();
    for(let p=1;p<=N;p++) placements[p].cities=placements[p].cities||new Set();
    game.phase="roll";
    updateLongestRoad();
    toast("局面を引き継ぎました。手札は0なので「手札を編集」で合わせてください");
  }else{
    resetPlacements();
    for(let p=1;p<=N;p++) placements[p].cities=new Set();
    const o=game.order;
    game.setup={queue:[...o, ...o.slice().reverse()], step:0, phase:"settle", lastSettle:null};
    game.phase="setup";
  }
  document.getElementById("gameStart").style.display="none";
  document.getElementById("gameBox").style.display="";
  const lb=document.getElementById("gameLog"); if(lb) lb.innerHTML="";
  buildTradeSelects();
  render(); updateGamePanel();
}
function endGameMode(){
  game=null;
  document.getElementById("gameStart").style.display="";
  document.getElementById("gameBox").style.display="none";
  render();
}
// 対戦ログ（誰が何をしたか）。表示と棋譜の両方に使う。
function glog(msg, player){
  if(!game) return;
  const p=player!=null ? Number(player) : cur();
  game.log.push({t:game.log.length, p, dice:game.dice, msg});
  if(typeof document==="undefined" || !document.getElementById) return;
  const box=document.getElementById("gameLog");
  if(box && box.appendChild && typeof document.createElement==="function"){
    const color=PCOLORS[(p||1)-1]||"#ccc";
    const line=document.createElement("div");
    line.innerHTML=`<span style="color:${color};font-weight:700">P${p}</span> ${msg}`;
    box.appendChild(line);
    box.scrollTop=box.scrollHeight;
  }
}
// このターンで起きた「棋譜のスナップショットからは復元できない行動」を構造化して記録する。
// 交易 / 発展カード購入・使用（収穫・独占・騎士の対象）/ 捨て札 / 盗賊移動・強奪。
// snapshotTurn 時に turn.actions として書き出し、humanagree等が機械的に読めるようにする。

/* ============================================================
   [2026-08-18] 棋譜に「その手を打った瞬間の評価値」を残す
   computeAdvice() を**状態を変える前**に呼び、指した手が候補リストの何番目で
   何点だったか、最善手は何だったかをログに刻む。ログはそのまま棋譜のイベントに
   入るので「棋譜確認」で後から見返せる。
   EVAL_LOG=false で無効（ログは従来どおり）。
   ============================================================ */
let EVAL_LOG = true;
let _inPlayout = false;   // 探索プレイアウト中は評価ログを止める（内部の建設ごとにcomputeAdviceが走ると致命的に遅い）
let _allowForcedWinInPlayout = false; // 終局まで回す勝率計測だけ、実戦と同じ確定10点手順を使う
function _evalActorIsAI(p){
  // 表示用computeAdviceは「単発候補の比較」。実戦AIはその上に確定10点探索、
  // 複数交換・連続建設、賞レース等を重ねるため、AIが実際に採用した手を最終判断とする。
  try{ if(typeof isAI==="function") return !!isAI(p); }catch(e){}
  try{ if(typeof seatAI!=="undefined"&&seatAI&&seatAI[p]!=null) return seatAI[p]!=="human"; }catch(e){}
  try{ return !!(game&&game.ai&&game.human!==p); }catch(e){}
  return false;
}
function _evalTag(kind, targetId){
  if(!EVAL_LOG || _inPlayout) return "";
  try{
    if(!game || game.phase!=="main") return "";
    const adv = computeAdvice();
    if(!adv || !adv.length) return "";
    const match = a => {
      if(kind==="city")   return a.label.indexOf("都市化")===0   && a.target && a.target.id===targetId;
      if(kind==="settle") return a.label.indexOf("開拓地")===0   && a.target && a.target.id===targetId;
      if(kind==="road")   return a.label.indexOf("道")===0       && a.target && a.target.id===targetId;
      if(kind==="dev")    return a.label.indexOf("発展カード")===0;
      return false;
    };
    let idx = adv.findIndex(match);
    const exactIdx=idx;
    // 同種の手を指したが位置が候補と違う場合は「同種の最上位」を代用して位置ズレを明示する
    let noted = "";
    if(idx<0){
      const same = a => {
        if(kind==="city")   return a.label.indexOf("都市化")===0;
        if(kind==="settle") return a.label.indexOf("開拓地")===0;
        if(kind==="road")   return a.label.indexOf("道")===0;
        if(kind==="dev")    return a.label.indexOf("発展カード")===0;
        return false;
      };
      idx = adv.findIndex(same);
      if(idx>=0) noted = "・AI推奨とは別の場所";
    }
    const top = adv[0];
    const fmt = x => (x<=-40 ? "対象外" : (x>=0?"+":"")+(Math.round(x*10)/10));
    // AI自身の行動では、実際に全ルールを通して選ばれた手が権威ある「おすすめ」。
    // computeAdviceの順位でそれを誤り扱いせず、完全一致した単発候補点だけ参考表示する。
    if(_evalActorIsAI(cur())){
      const ref=exactIdx>=0?`・単発候補評価 ${fmt(adv[exactIdx].score)}`:"";
      return `〔AI最終判断・おすすめ${ref}〕`;
    }
    if(idx<0) return "";
    const me = adv[idx];
    const sc = fmt(me.score);
    const topShort = String(top.label).replace(/（.*$/,"").trim();
    return (idx===0)
      ? `〔評価 ${sc}・AI最善手${noted}〕`
      : `〔評価 ${sc}・${idx+1}位（AI最善は「${topShort}」${fmt(top.score)}）${noted}〕`;
  }catch(e){ return ""; }
}

function _actionFrame(actor, events, action){
  const sett={}, city={}, road={};
  for(let p=1;p<=numPlayers;p++){
    for(const v of placements[p].settlements) sett[v]=p;
    if(placements[p].cities) for(const v of placements[p].cities) city[v]=p;
    for(const e of placements[p].roads) road[e]=p;
  }
  let winProb=null; try{ winProb=estimateWinProbabilities(); }catch(e){}
  const tn=game.turns.filter(t=>!t.setup).length+1;
  const sn=(game._actionFrames||[]).length+1;
  return {sett, city, road, robber:game.robber, dice:game.dice, player:actor,
          title:`ターン ${tn}・行動 ${sn}`, hands:_snapHands(), events, actions:[action],
          ...(winProb?{winProb}: {})};
}
function _publicActionText(o){
  if(!o) return "行動";
  if(o.a==="roll") return o.total===7 ? `🎲 ${o.total}（盗賊！）` : `🎲 ${o.total}`;
  if(o.a==="discard") return `手札を${Object.values(o.res||{}).reduce((a,b)=>a+b,0)}枚捨てた`;
  if(o.a==="endTurn") return "ターン終了";
  return "行動";
}
function _recAct(o){
  if(!game) return;
  if(Array.isArray(game._researchCapture)) game._researchCapture.push(JSON.parse(JSON.stringify(o)));
  if(!game._acts) game._acts=[];
  if(!game._actionFrames) game._actionFrames=[];
  game._acts.push(o);
  const actor=Number(o&&((o.p!=null&&o.p)||(o.to!=null&&o.to)))||cur();
  const mark=game._actionLogMark!=null ? game._actionLogMark : (game._logMark||0);
  let events=game.log.slice(mark).map(l=>`P${l.p} ${l.msg}`);
  game._actionLogMark=game.log.length;
  if(!events.length) events=[`P${actor} ${_publicActionText(o)}`];
  game._actionFrames.push(_actionFrame(actor,events,o));
}
// 現在の盤面状態を棋譜1コマとして記録（都市も含める）
function snapshotTurn(){
  if(!game) return;
  const sett={}, city={}, road={};
  for(let p=1;p<=numPlayers;p++){
    for(const v of placements[p].settlements) sett[v]=p;
    if(placements[p].cities) for(const v of placements[p].cities) city[v]=p;
    for(const e of placements[p].roads) road[e]=p;
  }
  // 直近のこのターンのログをイベントとして添える
  const lastMsgs = game.log.slice(game._logMark||0).map(l=>`P${l.p} ${l.msg}`);
  game._logMark = game.log.length;
  const tn = game.turns.filter(t=>!t.setup).length + 1;   // 初期配置のコマは番号に数えない
  const title = `ターン ${tn}`;
  const note = String(game._liveNote||"").trim();
  let winProb=null; try{ winProb=estimateWinProbabilities(); }catch(e){}
  game.turns.push({sett, city, road, robber:game.robber, dice:game.dice, player:cur(),
                   title, hands:_snapHands(), events: lastMsgs.length?lastMsgs:["（このターンの動きなし）"],
                   actions:(game._acts||[]), steps:(game._actionFrames||[]),
                   ...(note?{note}: {}), ...(winProb?{winProb}: {})});
  game._liveNote="";
  game._acts=[];   // 次ターン用にリセット
  game._actionFrames=[];
  game._actionLogMark=game.log.length;
}
// 各プレイヤーの手札・発展カード・VPを棋譜に残す（棋譜で手札を確認できるように）
function _snapHands(){
  const out={};
  for(let p=1;p<=numPlayers;p++){
    if(!game.hands[p]) continue;
    out[p]={ res:Object.assign({},game.hands[p]),
             dev:Object.values(game.dev.hands[p]).reduce((a,b)=>a+b,0),
             vp:vpOf(p) };
  }
  return out;
}
// 初期配置を1手ずつ棋譜に残す（まっさらな盤面から一人ずつ置いていくのが見える）
function _snapSetupStep(sp, what){
  if(!game) return;
  const sett={}, city={}, road={};
  for(let p=1;p<=numPlayers;p++){
    for(const v of placements[p].settlements) sett[v]=p;
    if(placements[p].cities) for(const v of placements[p].cities) city[v]=p;
    for(const e of placements[p].roads) road[e]=p;
  }
  const n = game.turns.filter(t=>t.setup).length + 1;
  let winProb=null; try{ winProb=estimateWinProbabilities(); }catch(e){}
  game.turns.push({setup:true, sett, city, road, robber:game.robber, dice:null, player:sp,
                   title:`初期配置 ${n}／${numPlayers*4}　P${sp} が${what}`,
                   hands:_snapHands(),
                   events:[`P${sp} が${what}を置いた`], actions:(game._acts||[]), ...(winProb?{winProb}: {})});
  game._logMark = game.log.length; game._actionLogMark=game.log.length;
  game._acts=[]; game._actionFrames=[];
}

// --- サイコロと分配 ---
function doRoll(total){
  if(game.phase!=="roll"){ toast("いまは振れません"); return; }
  if(total==null){ total=(1+Math.floor(Math.random()*6))+(1+Math.floor(Math.random()*6)); }
  game.dice=total; game.rolled=true;
  game.rollCount=(game.rollCount||0)+1;   // 通算投数（足切り判定用）
  game.diceCount=(game.diceCount||0)+1;   // 試合を通したダイス消化数（残りダイス計算用）
  glog(total===7 ? `🎲 ${total}（盗賊！）` : `🎲 ${total}`);
  if(total===7){
    game.discardQueue=[];
    for(const p of game.order){ const t=handTotal(p); if(t>7) game.discardQueue.push({p, need:Math.floor(t/2)}); }
    game.phase = game.discardQueue.length ? "discard" : "robber";
    toast(game.discardQueue.length ? "7! 手札8枚以上は半分捨てます" : "7! 盗賊を動かすタイルをクリック");
    _recAct({a:"roll", total, by:{}});
  }else{
    distribute(total);
    game.phase="main";
  }
  render(); updateGamePanel();
}
function hexVertsG(hid){
  const out=[]; for(const [v,hs] of Object.entries(GEO.vertex_hexes)){ if(hs.includes(Number(hid))) out.push(Number(v)); }
  return out;
}
function distribute(total){
  const want={};
  for(const h of GEO.hexes){
    const b=board[h.id];
    if(!b || b.number!==total || h.id===game.robber || !b.resource || b.resource==="desert") continue;
    for(const vid of hexVertsG(h.id)){
      const oc=occupantOf(vid); if(!oc) continue;
      const n= oc.type==="city" ? 2 : 1;
      (want[b.resource]=want[b.resource]||{}); want[b.resource][oc.p]=(want[b.resource][oc.p]||0)+n;
    }
  }
  const gains=[]; const by={};   // by[player][res]=枚数（銀行切れも反映した実配分）
  const _add=(pp,res,n)=>{ (by[pp]=by[pp]||{}); by[pp][res]=(by[pp][res]||0)+n; };
  for(const [res,m] of Object.entries(want)){
    const need=Object.values(m).reduce((a,b)=>a+b,0), bank=bankOf(res);
    const players=Object.keys(m);
    if(bank>=need){ for(const [pp,n] of Object.entries(m)){ gain(Number(pp),res,n); gains.push(`P${pp}+${n}${RES_JP[res]}`); _add(pp,res,n);} }
    else if(players.length===1){ const pp=Number(players[0]); const n=Math.min(bank,m[players[0]]); if(n>0){gain(pp,res,n); gains.push(`P${pp}+${n}${RES_JP[res]}(銀行切れ)`); _add(pp,res,n);} }
  }
  toast(gains.length ? `出目${total}: `+gains.join(" ") : `出目${total}: 資源なし`);
  if(gains.length) glog(`資源: ${gains.join(" ")}`);
  else glog("資源の獲得なし");
  _recAct({a:"roll", total, by});
}

// --- 盗賊 ---
function robberMoved(hid){
  const from=game.robber;
  game.robber=hid;
  glog(`盗賊を移動`);
  _recAct({a:"robber", p:cur(), from, hex:hid});
  const cands=new Set();
  for(const vid of hexVertsG(hid)){ const oc=occupantOf(vid); if(oc && oc.p!==cur() && handTotal(oc.p)>0) cands.add(oc.p); }
  game.stealCands=[...cands];
  if(game.stealCands.length===0){ finishRobber(); }
  else if(game.stealCands.length===1){ stealFrom(bestStealTarget(game.stealCands)); }
  else { game.phase="steal"; render(); updateGamePanel(); }
}
function stealFrom(victim){
  const pool=[]; for(const r of RES5) for(let i=0;i<game.hands[victim][r];i++) pool.push(r);
  if(pool.length){ const r=pool[Math.floor(Math.random()*pool.length)];
    game.hands[victim][r]--; gain(cur(),r,1); toast(`P${cur()} が P${victim} から1枚奪った`); glog(`P${victim} から1枚奪った`);
    _recAct({a:"steal", from:victim, to:cur(), res:r}); }
  finishRobber();
}
function finishRobber(){
  game.stealCands=[];
  game.phase = game.resume || (game.rolled ? "main" : "roll");
  game.resume=null;
  render(); updateGamePanel();
}

// --- 発展カード ---
function buyDev(){
  const p=cur();
  if(game.phase!=="main"){ toast("建設フェーズで買えます"); return; }
  if(!game.dev.deck.length){ toast("発展カードは売り切れ"); return; }
  if(!canPay(p,COST.dev)){ toast("資源が足りません(羊+小麦+鉱石)"); return; }
  pay(p,COST.dev);
  const c=game.dev.deck.pop();
  game.dev.hands[p][c]++; game.dev.bought[p][c]++;
  toast(`発展カードを購入（${DEV_JP[c]}）`);
  // カード種別やAIの購入目的は非公開情報。共有ログには購入事実だけを残す。
  glog(`発展カードを購入`);
  _recAct({a:"devBuy", p, card:c});
  checkWin(); render(); updateGamePanel();
}
function canPlay(card){
  const p=cur();
  if(game.devPlayed) return false;
  return game.dev.hands[p][card] - game.dev.bought[p][card] > 0;
}
function playDev(card){
  const p=cur();
  if(game.phase!=="main" && !(card==="knight" && game.phase==="roll")){ toast("いまは使えません"); return; }
  if(game.devPlayed){ toast("発展カードは1ターンに1枚"); return; }
  if(!canPlay(card)){ toast("使えるカードがありません（買ったターンは使えません）"); return; }
  game.dev.hands[p][card]--; game.devPlayed=true;
  if(game.dev.played[p]) game.dev.played[p][card]++;
  glog(`発展カード「${DEV_JP[card]}」を使用`);
  _recAct({a:"devPlay", p, card});
  if(card==="knight"){
    game.army[p]++; updateLargestArmy();
    game.resume = game.rolled ? "main" : "roll";
    game.phase="robber";
    toast("騎士！ 盗賊を動かすタイルをクリック");
    checkWin();
  }else if(card==="roads"){
    game.freeRoads=2; toast("街道建設！ 道を2本無料で置けます");
  }else if(card==="plenty"){
    game.ask={type:"plenty", picks:2}; toast("収穫！ もらう資源を2つ選んでください");
  }else if(card==="mono"){
    game.ask={type:"mono"}; toast("独占！ 奪う資源を選んでください");
  }
  render(); updateGamePanel();
}
function resolvePlenty(res){
  if(bankOf(res)<=0){ toast("銀行にありません"); return; }
  gain(cur(),res,1); game.ask.picks--;
  glog(`収穫で ${RES_JP[res]} を1枚獲得`);
  _recAct({a:"plenty", p:cur(), res});
  if(game.ask.picks<=0) game.ask=null;
  render(); updateGamePanel();
}
function resolveMono(res){
  let got=0;
  for(const p of game.order){ if(p===cur()) continue; got+=game.hands[p][res]; game.hands[p][res]=0; }
  gain(cur(),res,got); game.ask=null;
  toast(`独占: ${RES_JP[res]}を${got}枚集めた`);
  glog(`独占で ${RES_JP[res]} を${got}枚回収`);
  _recAct({a:"mono", p:cur(), res, got});
  render(); updateGamePanel();
}

// --- 交易（銀行/港） ---
function rateFor(p,res){
  let rate=4;
  for(const [eid,type] of Object.entries(ports)){
    const e=GEO.edges[eid]; if(!e) continue;
    const own=[e.a,e.b].some(v=>{const oc=occupantOf(v); return oc&&oc.p===p;});
    if(!own) continue;
    if(type==="3:1") rate=Math.min(rate,3);
    if(type===res) rate=Math.min(rate,2);
  }
  return rate;
}
function doTrade(){
  const p=cur();
  if(game.phase!=="main"){ toast("建設フェーズで交換できます"); return; }
  const give=document.getElementById("tradeGive").value, get=document.getElementById("tradeGet").value;
  if(give===get){ toast("同じ資源です"); return; }
  const rate=rateFor(p,give);
  if(game.hands[p][give]<rate){ toast(`${RES_JP[give]}が${rate}枚必要です`); return; }
  if(bankOf(get)<=0){ toast("銀行にありません"); return; }
  game.hands[p][give]-=rate; gain(p,get,1);
  toast(`${RES_JP[give]}×${rate} → ${RES_JP[get]}×1`);
  glog(`交換 ${RES_JP[give]}×${rate}→${RES_JP[get]}`);
  _recAct({a:"trade", p, give, get, rate});
  render(); updateGamePanel();
}
function buildTradeSelects(){
  for(const id of ["tradeGive","tradeGet"]){
    const s=document.getElementById(id); s.innerHTML="";
    for(const r of RES5) s.appendChild(new Option(RES_JP[r], r));
  }
}

function endTurnGame(){
  if(game.phase==="setup"){ toast("初期配置中です"); return; }
  if(game.phase==="over"){ toast("対局は終了しています"); return; }
  if(game){ game._bestCache=null; game._bestCacheKey=null; }   // ターンが変わるのでキャッシュ無効化
  if(game.phase!=="main"){ toast("処理を先に終えてください"); return; }
  if(game.ask || game.freeRoads>0){ toast("カードの処理を先に終えてください"); return; }
  const p=cur();
  glog("ターン終了", p);
  _recAct({a:"endTurn", p});
  snapshotTurn();                       // このターン終了時点の盤面を棋譜に記録
  for(const c in game.dev.bought[p]) game.dev.bought[p][c]=0;
  game.idx=(game.idx+1)%game.order.length;
  game.dice=null; game.rolled=false; game.devPlayed=false; game.phase="roll";
  render(); updateGamePanel();
}

// --- 対局モードのクリック処理 ---
function gameClickVertex(vid){
  if(vid==null || !GEO.vertex_neighbors[vid]) return;   // 不正な頂点idへの防御
  const p=cur();
  if(game.phase==="setup"){
    const su=game.setup;
    if(su.phase!=="settle"){ toast("いまは道を置く番です"); return; }
    if(occupantOf(vid)){ toast("そこは使用中です"); return; }
    for(const n of GEO.vertex_neighbors[vid]) if(occupantOf(n)){ toast("隣に建物があるため置けません"); return; }
    const sp=su.queue[su.step];
    placements[sp].settlements.add(vid);
    su.lastSettle=vid;
    if(su.step>=game.order.length){
      for(const hid of GEO.vertex_hexes[String(vid)]){
        const b=board[hid]; if(b&&b.resource&&b.resource!=="desert"&&bankOf(b.resource)>0) gain(sp,b.resource,1);
      }
    }
    su.phase="road";
    _snapSetupStep(sp, "開拓地");
    render(); updateGamePanel(); return;
  }
  if(game.phase!=="main"){ toast("いまは建設できません"); return; }
  const oc=occupantOf(vid);
  if(oc && oc.p===p && oc.type==="settlement"){
    if(placements[p].cities.size>=4){ toast("都市は4つまでです"); return; }
    if(!canPay(p,COST.city)){ toast("都市化には 小麦2+鉱石3"); return; }
    const _tagC=_evalTag("city", vid);
    pay(p,COST.city);
    placements[p].settlements.delete(vid);
    placements[p].cities.add(vid);
    toast("都市化！"); glog("🏛 都市化"+(_tagC?" "+_tagC:""));
    _recAct({a:"build", p, kind:"city", id:vid});
    updateLongestRoad(); checkWin(); render(); updateGamePanel(); return;
  }
  if(oc){ toast("そこは使用中です"); return; }
  if(placements[p].settlements.size>=5){ toast("開拓地は5つまで（都市化すると空きます）"); return; }
  for(const n of GEO.vertex_neighbors[vid]) if(occupantOf(n)){ toast("隣に建物があるため置けません"); return; }
  const touchMyRoad=GEO.edges.some(e=>(e.a===vid||e.b===vid)&&placements[p].roads.has(e.id));
  if(!touchMyRoad){ toast("自分の道に接した場所にだけ建てられます"); return; }
  if(!canPay(p,COST.settlement)){ toast("開拓地には 木+レンガ+羊+小麦"); return; }
  const _tagS=_evalTag("settle", vid);
  pay(p,COST.settlement);
  placements[p].settlements.add(vid);
  toast("開拓地を建設！"); glog("🏠 開拓地を建設"+(_tagS?" "+_tagS:""));
  _recAct({a:"build", p, kind:"settle", id:vid});
  updateLongestRoad(); checkWin(); render(); updateGamePanel();
}
function gameClickEdge(eid){
  const p=cur();
  if(game.phase==="setup"){
    const su=game.setup;
    if(su.phase!=="road"){ toast("先に開拓地を置いてください"); return; }
    const e=GEO.edges[eid];
    if(ownerOf("roads",eid)){ toast("その道は使用中です"); return; }
    if(e.a!==su.lastSettle && e.b!==su.lastSettle){ toast("いま置いた開拓地に接する道を選んでください"); return; }
    const sp=su.queue[su.step];
    placements[sp].roads.add(eid);
    su.step++;
    _snapSetupStep(sp, "道");
    if(su.step>=su.queue.length){ game.setup=null; game.phase="roll"; game.idx=0; toast("初期配置 完了！ P1からサイコロ"); }
    else su.phase="settle";
    render(); updateGamePanel(); return;
  }
  if(game.phase!=="main"){ toast("いまは建設できません"); return; }
  if(ownerOf("roads",eid)){ toast("その道は使用中です"); return; }
  const e=GEO.edges[eid];
  const connects=[e.a,e.b].some(v=>{
    const oc=occupantOf(v);
    if(oc && oc.p===p) return true;
    if(oc && oc.p!==p) return false;
    return GEO.edges.some(e2=>e2.id!==eid&&(e2.a===v||e2.b===v)&&placements[p].roads.has(e2.id));
  });
  if(!connects){ toast("自分の道か建物につながる場所にだけ置けます"); return; }
  if(placements[p].roads.size>=15){ toast("道は15本までです"); return; }
  let _freeRoad=false;
  const _tagR=_evalTag("road", eid);
  if(game.freeRoads>0){
    game.freeRoads--; placements[p].roads.add(eid); _freeRoad=true;
    toast(`道を建設（無料 残り${game.freeRoads}）`); glog("🛤 道を建設（無料）"+(_tagR?" "+_tagR:""));
  }else{
    if(!canPay(p,COST.road)){ toast("道には 木+レンガ"); return; }
    pay(p,COST.road); placements[p].roads.add(eid);
    toast("道を建設！"); glog("🛤 道を建設"+(_tagR?" "+_tagR:""));
  }
  _recAct({a:"build", p, kind:"road", id:eid, free:_freeRoad?1:0});
  updateLongestRoad(); checkWin(); render(); updateGamePanel();
}
function gameClickHex(hid){
  if(game.phase!=="robber"){ return; }
  if(hid===game.robber){ toast("別のタイルを選んでください"); return; }
  robberMoved(hid);
}


// ===================== 自己対戦（データ生成） =====================
// 戦略ヒューリスティック(computeAdvice等)をボットの頭脳にして、厳密ルールで高速対戦する。
// 初期配置は上位候補からランダムに選ぶ（質のバラつきを作る＝学習の信号になる）。
// 2軒目の補完ボーナス: プレイヤーpがまだ触れていない資源に触れる頂点を加点
// ユーザーの配置序列（ティア）: 2軒合計の資源プロファイルから、配置の質を階層で返す。
// 上位ティアほど強い。同ティア内は既存スコアで比較する想定。
// tier1(最強): 鉄か麦の一方がpip6以上 & 鉄麦両方に触れる
// tier2: 鉄麦両方pip5以上 & 4種以上
// tier3: 5種
// tier4: 鉄麦両方pip5以上 & 3種
// tier5: 木土両方pip6以上 & 麦pip4以上 & 4種
// tier0: その他
function _placementTier(resPipCombined){
  const rp=resPipCombined;
  const ore=rp.ore||0, wheat=rp.wheat||0, wood=rp.wood||0, brick=rp.brick||0;
  const kinds=["wood","brick","sheep","wheat","ore"].filter(r=>(rp[r]||0)>0).length;
  const hasOreWheat = ore>0 && wheat>0;
  // tier1: 鉄か麦の一方がpip6以上 かつ 鉄麦両方に触れる
  if(hasOreWheat && (ore>=6 || wheat>=6)) return 1;
  // tier2: 鉄麦両方pip5以上 かつ 4種以上
  if(ore>=5 && wheat>=5 && kinds>=4) return 2;
  // tier3: 5種
  if(kinds>=5) return 3;
  // tier4: 鉄麦両方pip5以上 かつ 3種
  if(ore>=5 && wheat>=5 && kinds>=3) return 4;
  // tier5: 木土両方pip6以上 かつ 麦pip4以上 かつ 4種
  if(wood>=6 && brick>=6 && wheat>=4 && kinds>=4) return 5;
  return 0;
}
// 席pの既存開拓地＋候補頂点vid の2軒合計resPipを返す
function _combinedResPip(p, vid){
  const rp={wood:0,brick:0,sheep:0,wheat:0,ore:0};
  const verts=[];
  if(placements[p] && placements[p].settlements) for(const sv of placements[p].settlements) verts.push(sv);
  verts.push(vid);
  for(const v of verts) for(const hid of (GEO.vertex_hexes[String(v)]||[])){
    const b=board[hid]; if(b&&b.resource&&b.resource!=="desert"&&b.number) rp[b.resource]+=pipOf(b.number);
  }
  return rp;
}
// 候補をティア優先でソート（USE_TIER時）。同ティア内は既存スコア降順。
function _tierSort(cands, sp){
  if(!(typeof USE_TIER!=="undefined" && USE_TIER)){ cands.sort((a,b)=>b.score-a.score); return cands; }
  for(const c of cands){ c._tier=_placementTier(_combinedResPip(sp, c.id)); }
  cands.sort((a,b)=> (b._tier-a._tier) || (b.score-a.score));
  return cands;
}
function _complementBonus(p, vid){
  if(!placements[p] || placements[p].settlements.size===0) return 0;
  const have=new Set();
  for(const sv of placements[p].settlements)
    for(const hid of GEO.vertex_hexes[String(sv)]){ const b=board[hid]; if(b&&b.resource&&b.resource!=="desert"&&b.number) have.add(b.resource); }
  let bonus=0;
  for(const hid of GEO.vertex_hexes[String(vid)]){
    const b=board[hid]; if(!b||!b.resource||b.resource==="desert"||!b.number) continue;
    if(!have.has(b.resource)) bonus+=pipOf(b.number)*COMPLEMENT_W;   // 未所持資源のpipを加点（強者データ: 資源多様性を重視）
  }
  return bonus;
}
// ペア読み初期配置（ユーザーの洞察）:
// 今のAIは「1軒目=最高スコア → 2軒目=補完」と逐次的に選ぶ。
// だが強者は「1軒目を置いたら、2巡目までに相手が場所を潰す。その後で自分の2軒目に
// 何が残るか」まで読んで1軒目を決める。4番手が強いのは、この読みが要らない
// （1・2軒目を連続で置けるので相手の割り込みが無い）から、というのが仮説。
//
// _pairScore(sp, v1): 席spが1軒目にv1を置いた場合の「1軒目 + 見込める最良の2軒目」の合計スコア。
//   相手の割り込みを、computeBestの上位を greedy に取っていくと仮定して予測する。
function _futureOccupied(sp, v1){
  // v1を置いた後、自分の2巡目の番までに相手が取るであろう頂点を予測
  const su=game.setup;
  if(!su) return new Set();
  const occ=new Set();
  for(let p=1;p<=numPlayers;p++){
    for(const v of placements[p].settlements) occ.add(v);
    if(placements[p].cities) for(const v of placements[p].cities) occ.add(v);
  }
  occ.add(v1);
  const B=_pairBase || computeBest();
  const illegal=v=>{ if(occ.has(v)) return true; for(const n of (GEO.vertex_neighbors[String(v)]||[])) if(occ.has(n)) return true; return false; };
  // queue の現在位置から、自分が次に置くまでの相手の手番数を数える
  const step=su.step;
  let myNext=-1;
  for(let i=step+1;i<su.queue.length;i++){ if(su.queue[i]===sp){ myNext=i; break; } }
  if(myNext<0) return occ;   // 2軒目が無い（ありえないが安全策）
  for(let i=step+1;i<myNext;i++){
    // その相手が、空いている中で最良の頂点を取ると仮定
    let best=null,bs=-Infinity;
    for(const vid in B.scores){ const v=+vid; if(illegal(v)) continue; const s=B.scores[vid].score; if(s>bs){bs=s;best=v;} }
    if(best!=null) occ.add(best);
  }
  return occ;
}
let _pairBase=null;
function _pairScore(sp, v1){
  const B=_pairBase || computeBest();
  const s1=B.scores[v1] ? B.scores[v1].score : 0;
  // v1と、その後に相手が取った後で残る最良の2軒目
  const occ=_futureOccupied(sp, v1);
  const illegal=v=>{ if(v===v1||occ.has(v)) return true; for(const n of (GEO.vertex_neighbors[String(v)]||[])) if(occ.has(n)) return true; return false; };
  let best2=0;
  for(const vid in B.scores){ const v=+vid; if(illegal(v)) continue;
    // 2軒目は補完込みで評価（v1を持っている前提の未所持資源ボーナス）
    let comp=0;
    const have=new Set();
    for(const hid of (GEO.vertex_hexes[String(v1)]||[])){ const b=board[hid]; if(b&&b.resource!=="desert"&&b.number) have.add(b.resource); }
    for(const hid of (GEO.vertex_hexes[String(v)]||[])){ const b=board[hid]; if(!b||b.resource==="desert"||!b.number) continue; if(!have.has(b.resource)) comp+=pipOf(b.number)*COMPLEMENT_W; }
    const s=B.scores[v].score + comp*COMPLEMENT_MULT;
    if(s>best2) best2=s;
  }
  return s1 + best2;   // 1軒目単体ではなく「2軒セットの見込み合計」
}

// 学習済み初期配置評価器（フルゲーム勝率を教師に学習・R²0.382）
// 既存スコアが捉えられない「展開力(木レンガ)・多様性・カード材料」を勝率で重み付け。
const PLACEMENT_MODEL={"feats": ["total_pip", "n_kinds", "n_neighbors", "wood_brick", "dev_res"], "mean": [6.208445642407907, 1.6999101527403415, 2.6037735849056602, 2.243486073674753, 3.964959568733154], "std": [2.785800313752836, 0.7462213834469325, 0.489112505540215, 2.551361927591876, 2.8574445923840757], "weights": [0.16172506738544473, 0.03074092961741756, 0.010755593293985304, 0.002444480938032895, 0.015273601064502975, 0.016332637645693697]};
function placementWinScore(v){
  const b=board;
  const resPip={wood:0,brick:0,sheep:0,wheat:0,ore:0};
  let totalPip=0;
  for(const hid of (GEO.vertex_hexes[String(v)]||[])){
    const bb=b[hid]; if(!bb||bb.resource==="desert"||!bb.number) continue;
    const pip=pipOf(bb.number); resPip[bb.resource]+=pip; totalPip+=pip;
  }
  const nKinds=["wood","brick","sheep","wheat","ore"].filter(r=>resPip[r]>0).length;
  const nNeighbors=(GEO.vertex_neighbors[String(v)]||[]).length;
  const woodBrick=resPip.wood+resPip.brick;
  const devRes=resPip.ore+resPip.wheat+resPip.sheep;
  const raw={total_pip:totalPip, n_kinds:nKinds, n_neighbors:nNeighbors, wood_brick:woodBrick, dev_res:devRes};
  const M=PLACEMENT_MODEL;
  let s=M.weights[0];
  for(let i=0;i<M.feats.length;i++){
    const f=M.feats[i];
    s+=M.weights[i+1]*((raw[f]-M.mean[i])/M.std[i]);
  }
  return s;   // 予測勝率（0〜1程度）
}

function _wPick(items, temp){ // スコア重み付きランダム（tempが小さいほど貪欲）
  if(!items.length) return null;
  const mx=Math.max(...items.map(x=>x.score));
  const ws=items.map(x=>Math.exp((x.score-mx)/(temp||2)));
  let r=Math.random()*ws.reduce((a,b)=>a+b,0);
  for(let i=0;i<items.length;i++){ r-=ws[i]; if(r<=0) return items[i]; }
  return items[items.length-1];
}
function _tradeBank(p,give,get){ // DOM無しの銀行/港交易
  const rate=rateFor(p,give);
  if(give===get||game.hands[p][give]<rate||bankOf(get)<=0) return false;
  game.hands[p][give]-=rate; gain(p,get,1);
  glog(`交換 ${RES_JP[give]}×${rate}→${RES_JP[get]}`, p);
  _recAct({a:"trade", p, give, get, rate});
  return true;
}
// 目標コストに向けて、余剰資源を銀行/港交換でかき集める。都市化不能(母体なし)からの脱出用。

// 交換を駆使すればcostObjを今すぐ払えるか（手札を壊さずシミュレート）
function _canCompleteByTrade(p, costObj){
  const hand=Object.assign({},game.hands[p]);
  const bank=Object.fromEntries(RES5.map(r=>[r,Math.max(0,bankOf(r))]));
  let guard=0;
  while(guard++<12){
    let need=null;
    for(const [r,n] of Object.entries(costObj)){ if((hand[r]||0)<n){ need=r; break; } }
    if(!need) return true;
    if((bank[need]||0)<=0) return false;
    let best=null;
    for(const r of RES5){
      const reserve=costObj[r]||0;
      const spare=hand[r]-reserve;
      if(spare>=rateFor(p,r)){ if(!best||rateFor(p,r)<rateFor(p,best)) best=r; }
    }
    if(!best) return false;
    const rate=rateFor(p,best);
    hand[best]-=rate; bank[best]+=rate;
    hand[need]=(hand[need]||0)+1; bank[need]--;
  }
  return false;
}
// 積極ビルド（資源を寝かせずバーストで失う前に使う）のオン/オフ
let AGGRO_TRADE=true;
let STEAL_PRIZE=true;    // リーダー(VP9以上)の道賞/騎士賞を届く範囲で奪い返す（A/B検証済み: 20盤面で約51%と有意）
let PRIZE_THREAT_SEATS=null;       // 最大脅威の賞保持者だけを防衛する席
let PRIZE_EXACT_SEATS=null;        // 実際に賞を移せる辺だけを使う席
let PRIZE_THREAT_MIN_VP_CFG=null;  // 席別の公開VP発火点
let PRIZE_TRADE_DEV_SEATS=null;    // 賞レース時の交換→発展を通常候補へ足す席
// 各行動後に上位の10点経路を再計算し、道賞・騎士賞だけ相手との競争込みで評価する。
// app.js が最強AI/無敵AIの手番席だけ設定する。nullなら従来挙動。
let DYNAMIC_ROUTE_CFG=null;
const DYNAMIC_ROUTE_CACHE=new WeakMap(); // game JSONやオンライン同期へ混ぜない
let PROTECT_CITY_RESERVE=false;   // 実験済み: 全10盤面で悪化(48.0%)のため不採用
let DEV_BUY_THRESH=5;   // カード購入(あふれ防止)を発動する手札枚数の閾値
let SETTLE_FLOOR=2;   // 家を2軒維持（A/B検証済み: 20盤面で約52.65%・ダイスも81-84に短縮）
// 1番手はスネークドラフトの構造上、2軒目が最後(8番目)に回るため拡張が遅れがち。
// 家の維持数を3に上げて補うと、1番手勝率が21.7%→23.2%に改善（3回・計11500試合で確認）。
function settleFloorFor(p){ return p===1 ? 3 : 2; }
let MONO_OW_WEIGHT=1.4;   // 独占カードで鉄麦を優先する重み
let COMPRESS_THRESH=5, COMPRESS_ITERS=10;
let UNIFORM_TEMP=0;   // >0 にすると自己対戦の全席が同じ配置腕前になる（試合長の計測用）
let W_CITY=1.0, W_SETTLE=1.0, W_ROAD=1.0, W_DEV=1.0;   // 行動の重み（1.0=現行のまま）
// ユーザー調整: 開拓地が即開く道／道賞プランの時だけ道を建て、それ以外（余剰資源の消化・投機的な2手先）は温存
let CONSERVE_ROADS=false;   // [2026-08-18] 40盤面6000試合の対応比較で -2.2pt [-4.1〜-0.3]＝有意に有害と判明したため無効化
                            //  （「即建設地が開く道／道賞プラン以外は評価-50」「序盤は初期道+1本以外-50」の2つの足切り）
// ユーザー調整: 相手を「危険」とみなすVP閾値（9→8）。妨害・賞の奪い返しをVP8から発動
let DANGER_VP=8;
// ユーザー調整: 序盤は「初期配置の道＋1本(その1本で建て地が相当良くなる場合)」以外、道賞狙いでも道は-評価
let EARLY_ROAD_BVP=5;        // 建物VP(開拓地1+都市2)がこの値未満なら「序盤」とみなす
let EARLY_ROAD_QUALITY=0.6;  // 「相当良い建て地」= 開く頂点の配置スコアが盤面レンジの上位このぶん以上
let CARD_ENGINE=false;   // 検証済み: 騎士賞は14%→19%に増えるが、人間型ボット相手だと逆に相手の勝率が上がる(20.1%→23.7%)。不採用。
function _ce(p){ return (CARD_ENGINE instanceof Set) ? CARD_ENGINE.has(p) : !!CARD_ENGINE; }
function _ka(p){ return (KNIGHT_AGGRO instanceof Set) ? KNIGHT_AGGRO.has(p) : !!KNIGHT_AGGRO; }
