function _shouldPlayKnight(p){
  if(!canPlay("knight")) return false;
  if(typeof SMART_ROBBER==="undefined" || !SMART_ROBBER){
    // 従来ロジック（SMART_ROBBER OFF時）: 自分の産出が止められている or army===2 or KNIGHT_AGGRO
    const mine=hexVertsG(game.robber).some(v=>{const oc=occupantOf(v);return oc&&oc.p===p;});
    return mine || game.army[p]===2 || (_ka(p)&&game.la.holder!==p);
  }
  // SMART_ROBBER ON:
  // 1) 良い狙い先があるか
  const adv=robberAdvice();
  const hasGoodTarget = adv && adv.top!=null && adv.hid!=null && adv.hid!==game.robber;
  if(hasGoodTarget) return true;
  // 2) 騎士賞まであと少し（army>=2）
  if(game.army[p]>=2) return true;
  // 3) 例外: 自分の「鉄」タイルが盗賊で止められているなら剥がす
  const myOreBlocked=hexVertsG(game.robber).some(v=>{
    const oc=occupantOf(v); if(!(oc&&oc.p===p)) return false;
    return (GEO.vertex_hexes[String(v)]||[]).some(hid=>{
      const b=board[hid]; return hid===game.robber && b && b.resource==="ore";
    });
  });
  return myOreBlocked;
}
