function _tradeToward(p, costObj){
  let guard=0;
  while(!canPay(p,costObj) && guard++<10){
    let need=null;
    for(const [r,n] of Object.entries(costObj)){ if((game.hands[p][r]||0)<n){ need=r; break; } }
    if(!need) break;
    let best=null;
    for(const r of RES5){
      const reserve=costObj[r]||0;
      const spare=game.hands[p][r]-reserve;
      if(spare>=rateFor(p,r)){ if(!best||rateFor(p,r)<rateFor(p,best)) best=r; }
    }
    if(!best) return canPay(p,costObj);
    if(!_tradeBank(p,best,need)) return canPay(p,costObj);
  }
  return canPay(p,costObj);
}
function _tryTradeForCity(p){ return _tryTradeForCost(p, COST.city); }
let SMART_BURST=false;   // 検証済み: 中立(50.5%/49.6%)。圧縮自体が1試合1回程度しか発動せず影響が小さい。
let BURST_ROAD_OFF=false;   // 実験済み: 全部止めると悪化(48.1%・バースト6.27→8.03枚)。受け皿としては機能していた。
