let SMART_BURST_AGGRESSIVE=false;   // 実験(強): 建物に届く見込みがあれば無条件で温存
// SMART_BURST: 「今この手札を圧縮せず持ち続ける価値があるか」を先読みで判定する。
// 発想（ユーザー提案）: バーストを機械的に避けるのではなく、
//   ①次の数ダイスで入る資源を出目確率から見積もり、
//   ②仮に7が出て半分捨てられても建物が建つなら、そのバーストは大した損ではない。
// そういう手札は圧縮（4:1で3枚焼く）せずステイした方が得なはず。
function _expectedGainNextRolls(p, nRolls){
  // 自分の建物が接する各タイルについて、nRolls回のダイスで入る資源の期待枚数
  const exp={wood:0, brick:0, sheep:0, wheat:0, ore:0};
  for(const hx of GEO.hexes){
    if(hx.id===game.robber) continue;
    const b=board[hx.id];
    if(!b||!b.number||!b.resource||b.resource==="desert") continue;
    let mult=0;
    for(const v of hexVertsG(hx.id)){
      const oc=occupantOf(v);
      if(oc&&oc.p===p) mult += (oc.type==="city")?2:1;
    }
    if(mult===0) continue;
    const prob = pipOf(b.number)/36;   // その数字が1回のダイスで出る確率
    exp[b.resource] += prob * mult * nRolls;
  }
  return exp;
}
function _worthHoldingThroughBurst(p){
  const h=game.hands[p];
  const total=handTotal(p);
  // 期待流入（次4ダイス＝自分の番が回ってくるまでの目安）
  const exp=_expectedGainNextRolls(p, 4);
  const proj={};
  for(const r of RES5) proj[r]=h[r]+exp[r];
  // ①そもそも今すぐ建てられる目標に届いているなら、圧縮せず建てるべき（この後のロジックが建てる）
  const canCityNow = RES5.every(r=>(h[r]||0)>=(COST.city[r]||0));
  const canSetNow  = RES5.every(r=>(h[r]||0)>=(COST.settlement[r]||0));
  if(canCityNow||canSetNow) return true;
  // ②見込み込みで、次の自分の番までに都市or開拓地に届きそうか
  const willCity = RES5.every(r=>proj[r]>=(COST.city[r]||0));
  const willSet  = RES5.every(r=>proj[r]>=(COST.settlement[r]||0));
  if(!willCity && !willSet) return false;   // 届かないなら温存の意味は薄い→圧縮してよい
  // ③届く見込みがあるなら温存する。
  //    根拠: 圧縮は4:1で確実に3枚を失う。一方バーストは「7が出たら」半分（確率的、しかも半分は残る）。
  //    建物に届く手札なら、確実な損より確率的な損を受け入れた方が期待値が高い。
  if(SMART_BURST_AGGRESSIVE) return true;
  // 保守版: 半分失っても建物コストを賄えるか、あと1枚で建つ場合のみ温存
  const keep = total - Math.floor(total/2);
  const target = willCity ? COST.city : COST.settlement;
  const needTotal = RES5.reduce((a,r)=>a+(target[r]||0),0);
  if(keep >= needTotal) return true;
  const lack = RES5.reduce((a,r)=>a+Math.max(0,(target[r]||0)-(h[r]||0)),0);
  return lack<=1;
}
function _tryTradeForCost(p, costObj){ // 余り資源を交換してcostObjを目指す（都市化・開拓地どちらでも使える）
  let guard=0;
  while(!canPay(p,costObj) && guard++<10){
    let need=null;
    for(const [r,n] of Object.entries(costObj)){ if((game.hands[p][r]||0)<n){ need=r; break; } }
    if(!need) break;
    let done=false;
    for(const r of RES5){
      if(r===need) continue;
      const keep = costObj[r]||0;
      if(game.hands[p][r]-rateFor(p,r) >= keep && _tradeBank(p,r,need)){ done=true; break; }
    }
    if(!done) break;
  }
  return canPay(p,costObj);
}
function _botDiscard(){ // 捨て: 次の建設の予約分を守り、余剰から捨てる
  const d=game.discardQueue[0];
  const p=d.p;
  // 次の目標: 都市化できる母体があれば都市、無ければ開拓地
  const reserve = (placements[p].settlements.size>0 && placements[p].cities.size<4) ? COST.city : COST.settlement;
  // 余剰が多い資源から捨てる
  let guard=0; const disc={};
  while(d.need>0 && guard++<30){
    let pick=null, best=-1e9;
    for(const r of RES5){
      if(game.hands[p][r]<=0) continue;
      const surplus=game.hands[p][r]-(reserve[r]||0);
      if(surplus>best){ best=surplus; pick=r; }
    }
    if(!pick) break;
    game.hands[p][pick]--; d.need--; disc[pick]=(disc[pick]||0)+1;
  }
  if(Object.keys(disc).length){
    const n=Object.values(disc).reduce((a,b)=>a+b,0);
    glog(`手札を${n}枚捨てた`, p);   // 資源の種類は非公開のまま
    _recAct({a:"discard", p, res:disc});
  }
  game.discardQueue.shift();
  if(!game.discardQueue.length) game.phase="robber";
}
