let CITY_HOLD_ROLLS=4;
let TURN_CFG=null;
function _dbtOf(p){   return (TURN_CFG&&TURN_CFG[p]&&TURN_CFG[p].dbt  !=null)?TURN_CFG[p].dbt  :DEV_BUY_THRESH; }
function _cmpOf(p){   return (TURN_CFG&&TURN_CFG[p]&&TURN_CFG[p].cmp  !=null)?TURN_CFG[p].cmp  :COMPRESS_THRESH; }
function _holdPOf(p){ return (TURN_CFG&&TURN_CFG[p]&&TURN_CFG[p].holdP!=null)?TURN_CFG[p].holdP:0; }
function _pCityByNextTurn(p){
  try{
    if(!(placements[p].settlements.size>0 && (placements[p].cities?placements[p].cities.size:0)<4)) return 0;
    const h=game.hands[p];
    const needW=Math.max(0, COST.city.wheat-(h.wheat||0)), needO=Math.max(0, COST.city.ore-(h.ore||0));
    if(needW===0 && needO===0) return 1;
    // 出目ごとの自分の麦・鉄の入手量
    const gain={};
    for(let d=2; d<=12; d++) gain[d]={w:0,o:0};
    for(const hx of GEO.hexes){
      const b=board[hx.id];
      if(!b||!b.number||!b.resource||b.resource==="desert") continue;
      if(hx.id===game.robber) continue;
      if(b.resource!=="wheat" && b.resource!=="ore") continue;
      for(const v of hexVertsG(hx.id)){
        const oc=occupantOf(v);
        if(!oc||oc.p!==p) continue;
        const mult=(oc.type==="city")?2:1;
        if(b.resource==="wheat") gain[b.number].w+=mult; else gain[b.number].o+=mult;
      }
    }
    // 7も「資源が増えない遷移」として6/36を残す。0にすると各投ごとに確率質量が
    // 30/36へ減り、4投以内の都市到達率を大幅に過小評価してしまう。
    const W=[[2,1],[3,2],[4,3],[5,4],[6,5],[7,6],[8,5],[9,4],[10,3],[11,2],[12,1]];
    // 状態: [残り必要麦][残り必要鉄] の確率
    let cur=[]; for(let a=0;a<=needW;a++){ cur.push(new Array(needO+1).fill(0)); }
    cur[needW][needO]=1;
    for(let r=0;r<CITY_HOLD_ROLLS;r++){
      const nxt=[]; for(let a=0;a<=needW;a++) nxt.push(new Array(needO+1).fill(0));
      for(let a=0;a<=needW;a++) for(let b2=0;b2<=needO;b2++){
        const pr=cur[a][b2]; if(pr<=0) continue;
        if(a===0&&b2===0){ nxt[0][0]+=pr; continue; }             // 既に到達＝吸収状態
        for(const [d,wt] of W){
          const na=Math.max(0, a-gain[d].w), nb=Math.max(0, b2-gain[d].o);
          nxt[na][nb]+= pr*(wt/36);
        }
      }
      cur=nxt;
    }
    return cur[0][0];
  }catch(e){ return 0; }
}
function _rwLegalEdges(p){
  const out=[];
  for(const e of GEO.edges){
    if(ownerOf("roads",e.id)) continue;
    const connects=[e.a,e.b].some(v=>{
      const oc=occupantOf(v);
      if(oc && oc.p===p) return true;
      if(oc && oc.p!==p) return false;
      return GEO.edges.some(e2=>e2.id!==e.id&&(e2.a===v||e2.b===v)&&placements[p].roads.has(e2.id));
    });
    if(connects) out.push(e.id);
  }
  return out;
}
function _rwBestExtension(p, k, target){
  if(k<=0) return null;
  const base=longestRoadOf(p);
  if(base>=target) return {edges:[], len:base};
  const roads=placements[p].roads;
  if(roads.size+k<target) return null;       // 道の総本数自体が足りない
  let best=null;
  // 以前は探索開始時点で合法な辺だけを固定候補にしていたため、
  // 「1本目で接続が開き、その先へ2・3本目を伸ばす」一筆書きを見落としていた。
  // 各深さで合法辺を再計算し、同じ追加辺集合は一度だけ調べる。
  for(let limit=1;limit<=k && !best;limit++){
    const seen=new Set();
    const chosen=[];
    const rec=()=>{
      const len=longestRoadOf(p);
      if(len>=target){ best={edges:chosen.slice(),len}; return; }
      if(chosen.length>=limit || roads.size+(limit-chosen.length)<target) return;
      const key=chosen.slice().sort((a,b)=>a-b).join(",");
      if(seen.has(key)) return;
      seen.add(key);
      // 最長路を大きく伸ばす辺から試す。結果は全候補を調べるので順序は速度にだけ影響する。
      const ranked=[];
      for(const eid of _rwLegalEdges(p)){
        roads.add(eid);
        ranked.push({eid,len:longestRoadOf(p)});
        roads.delete(eid);
      }
      ranked.sort((a,b)=>b.len-a.len||a.eid-b.eid);
      for(const x of ranked){
        roads.add(x.eid); chosen.push(x.eid);
        rec();
        chosen.pop(); roads.delete(x.eid);
        if(best) return;
      }
    };
    rec();
  }
  return best;
}

function _rwTradePlanForCost(p, hand0, cost, bankUsed){
  const hand=Object.assign({},hand0), trades=[];
  const reserved=bankUsed||{};
  const need={};
  for(const r of RES5) need[r]=Math.max(0,(cost[r]||0)-(hand[r]||0));
  for(const get of RES5){
    while(need[get]>0){
      // 収穫で先に銀行から受け取る分も差し引く。旧版はここを数えず、
      // 同じ銀行在庫を収穫と交換で二重に使う実行不能プランを許していた。
      if(bankOf(get)-(reserved[get]||0)<=trades.filter(t=>t.get===get).length) return null;
      let give=null,gr=99;
      for(const r of RES5){
        if(r===get) continue;
        const rate=rateFor(p,r), reserve=cost[r]||0;
        if((hand[r]||0)-reserve>=rate && rate<gr){ give=r; gr=rate; }
      }
      if(!give) return null;
      hand[give]-=gr; hand[get]=(hand[get]||0)+1;
      trades.push({give,get,rate:gr}); need[get]--;
    }
  }
  return {hand,trades};
}
function _rwFundingVariants(p){
  const base=Object.assign({},game.hands[p]);
  const out=[{card:null,picks:[],hand:base,free:game.freeRoads||0,bankUsed:{}}];
  if(game.devPlayed || typeof canPlay!=="function") return out;
  try{
    if(canPlay("roads")) out.push({card:"roads",picks:[],hand:Object.assign({},base),free:(game.freeRoads||0)+2,bankUsed:{}});
    if(canPlay("plenty")){
      for(let i=0;i<RES5.length;i++) for(let j=i;j<RES5.length;j++){
        const a=RES5[i],b=RES5[j];
        if(bankOf(a)<1+(a===b?1:0) || bankOf(b)<1) continue;
        const h=Object.assign({},base); h[a]++; h[b]++;
        const bankUsed={[a]:1}; bankUsed[b]=(bankUsed[b]||0)+1;
        out.push({card:"plenty",picks:[a,b],hand:h,free:game.freeRoads||0,bankUsed});
      }
    }
    if(canPlay("mono")) for(const r of RES5){
      let got=0; for(const q of game.order) if(q!==p) got+=game.hands[q][r]||0;
      if(got>0){ const h=Object.assign({},base); h[r]+=got;
        out.push({card:"mono",picks:[r],hand:h,free:game.freeRoads||0,bankUsed:{}}); }
    }
  }catch(e){}
  return out;
}
function _rwAddCost(dst,src,mult){
  const m=(mult==null)?1:mult;
  for(const r of RES5) dst[r]=(dst[r]||0)+(src[r]||0)*m;
  return dst;
}
function _rwFundingPlan(p,n,extraCost,cardMode){
  let best=null;
  for(const v of _rwFundingVariants(p)){
    if(cardMode==="none" && v.card) continue;
    const paid=Math.max(0,n-v.free);
    const cost={wood:paid,brick:paid};
    if(extraCost) _rwAddCost(cost,extraCost,1);
    const tp=_rwTradePlanForCost(p,v.hand,cost,v.bankUsed);
    if(!tp) continue;
    // 勝ち手順では、少ない交換回数を最優先。並んだらカードを温存する。
    const score=tp.trades.length*10+(v.card?1:0);
    if(!best||score<best.score) best={score,card:v.card,picks:v.picks,trades:tp.trades,paid};
  }
  return best;
}
function _rwLegalSettlementChoices(p,n){
  if(n<=0) return [];
  const cands=[];
  for(const vS of Object.keys(GEO.vertex_neighbors)){
    const v=Number(vS);
    if(occupantOf(v)) continue;
    if(GEO.vertex_neighbors[v].some(x=>occupantOf(x))) continue;
    if(!GEO.edges.some(e=>(e.a===v||e.b===v)&&placements[p].roads.has(e.id))) continue;
    cands.push(v);
  }
  let answer=null;
  const rec=(start,chosen)=>{
    if(chosen.length===n){ answer=chosen.slice(); return true; }
    for(let i=start;i<cands.length;i++){
      const v=cands[i];
      if(chosen.some(x=>GEO.vertex_neighbors[x].includes(v))) continue;
      chosen.push(v); if(rec(i+1,chosen)) return true; chosen.pop();
    }
    return false;
  };
  rec(0,[]);
  return answer;
}
function _rwWinningBuildPlans(p,bonusVP,withRoadAward){
  // bonusVP は、このあと確実に入る別の賞（現在は騎士賞）を仮加算する。
  // 例: 現在5点 → 騎士賞+2 → 開拓地+1 → 道賞+2 = 10点。
  const roadVP=(withRoadAward===false)?0:2;
  const need=Math.max(0,game.vpToWin-vpOf(p)-roadVP-(bonusVP||0));
  if(need===0) return [{cities:[],settles:[],cost:{}}];
  const citySlots=Math.max(0,4-placements[p].cities.size);
  const cityTargets=[...placements[p].settlements];
  const out=[];
  for(let nc=0;nc<=Math.min(need,citySlots,cityTargets.length);nc++){
    const ns=need-nc;
    // 都市化した家のぶん開拓地コマが戻る。
    if(ns>5-(placements[p].settlements.size-nc)) continue;
    const settles=_rwLegalSettlementChoices(p,ns);
    if(ns>0&&!settles) continue;
    const cost={}; _rwAddCost(cost,COST.city,nc); _rwAddCost(cost,COST.settlement,ns);
    out.push({cities:cityTargets.slice(0,nc),settles:settles||[],cost});
  }
  // 同じ勝ちなら消費枚数が少ない手順から調べる。
  out.sort((a,b)=>RES5.reduce((s,r)=>s+(a.cost[r]||0)-(b.cost[r]||0),0));
  return out;
}
function _rwAffordableRoads(p){
  const cap=15-placements[p].roads.size;
  let n=0, funding=null;
  for(let k=1;k<=cap;k++){
    const f=_rwFundingPlan(p,k);
    if(!f) break;
    n=k; funding=f;
  }
  return {n,funding};
}
function _rwKnightWinningPlan(p,target){
  // 騎士は1ターン1枚の発展カード枠を使うため、その後の資金計画では
  // 街道建設・収穫・独占を併用しない。建物と通常道路、交換は併用できる。
  try{
    if(game.devPlayed || !canPlay("knight")) return null;
    const armyAfter=(game.army[p]||0)+1, la=game.la.holder;
    const takesArmy=game.la.holder!==p && armyAfter>=3 && (la==null||armyAfter>(game.army[la]||0));
    if(!takesArmy) return null;
    const cap=15-placements[p].roads.size;
    let n=0;
    for(let k=1;k<=cap;k++){
      if(!_rwFundingPlan(p,k,null,"none")) break;
      n=k;
    }
    if(n<=0) return null;
    const road=_rwBestExtension(p,n,target);
    if(!road||!road.edges.length) return null;
    for(const eid of road.edges) placements[p].roads.add(eid);
    const builds=_rwWinningBuildPlans(p,2);
    for(const eid of road.edges) placements[p].roads.delete(eid);
    for(const build of builds){
      const funding=_rwFundingPlan(p,road.edges.length,build.cost,"none");
      if(funding) return {road,build,funding};
    }
  }catch(e){}
  return null;
}
function _fwFindBuildPlan(p,bonusVP,cardMode,maxRoads){
  // 「現在の通常評価」ではなく、このターン中に確実に勝つ行動列を直接探す。
  // 発展カード購入のような結果が不確定な行動は候補へ入れない。
  const roads=placements[p].roads, chosen=[];
  const seen=new Set();
  let answer=null;
  const inspect=()=>{
    const builds=_rwWinningBuildPlans(p,bonusVP,false);
    for(const build of builds){
      const funding=_rwFundingPlan(p,chosen.length,build.cost,cardMode);
      if(funding){ answer={edges:chosen.slice(),build,funding}; return true; }
    }
    return false;
  };
  const rec=()=>{
    if(inspect()) return true;
    if(chosen.length>=maxRoads) return false;
    const key=chosen.slice().sort((a,b)=>a-b).join(",");
    if(seen.has(key)) return false;
    seen.add(key);
    const ranked=[];
    for(const eid of _rwLegalEdges(p)){
      roads.add(eid);
      let opens=0;
      try{ opens=_rwLegalSettlementChoices(p,1)?.length?1:0; }catch(e){}
      ranked.push({eid,opens,len:longestRoadOf(p)});
      roads.delete(eid);
    }
    ranked.sort((a,b)=>b.opens-a.opens||b.len-a.len||a.eid-b.eid);
    for(const x of ranked){
      roads.add(x.eid); chosen.push(x.eid);
      if(rec()) return true;
      chosen.pop(); roads.delete(x.eid);
    }
    return false;
  };
  rec();
  // 再帰が勝ちを見つけた時は仮置きした辺を戻してから実行側へ渡す。
  for(const eid of chosen) roads.delete(eid);
  return answer;
}
function _fwPlayFunding(p,funding){
  if(funding.card && !game.devPlayed){
    playDev(funding.card);
    if(funding.card==="plenty"){
      for(const r of funding.picks) if(game.ask) resolvePlenty(r);
    }else if(funding.card==="mono" && game.ask){
      resolveMono(funding.picks[0]);
    }
  }
  if(game.phase!=="main") return false;
  for(const t of funding.trades) if(!_tradeBank(p,t.give,t.get)) return false;
  return true;
}
function _fwExecuteBuildPlan(p,plan){
  if(!plan || !_fwPlayFunding(p,plan.funding)) return false;
  let acted=0;
  // 街道建設カードを使った場合も含め、道を先に置いて新しい建設地を開く。
  for(const eid of plan.edges){
    if(ownerOf("roads",eid)) continue;
    if(!(game.freeRoads>0) && !canPay(p,COST.road)) return acted>0;
    gameClickEdge(eid); acted++;
    if(game.phase!=="main") return true;
  }
  for(const vid of plan.build.cities){
    if(!canPay(p,COST.city)) return acted>0;
    gameClickVertex(vid); acted++;
    if(game.phase!=="main") return true;
  }
  for(const vid of plan.build.settles){
    if(!canPay(p,COST.settlement)) return acted>0;
    gameClickVertex(vid); acted++;
    if(game.phase!=="main") return true;
  }
  return acted>0;
}
function _fwKnightTakesArmy(p){
  try{
    if(game.devPlayed || !canPlay("knight") || game.la.holder===p) return false;
    const after=(game.army[p]||0)+1, h=game.la.holder;
    return after>=3 && (h==null||after>(game.army[h]||0));
  }catch(e){ return false; }
}
function _fwCouldReachByBuildings(p,bonusVP,allowResourceCard){
  const gap=Math.max(0,game.vpToWin-vpOf(p)-(bonusVP||0));
  if(gap<=0) return true;
  const cityCap=Math.min(4-(placements[p].cities?placements[p].cities.size:0),placements[p].settlements.size);
  const settleCap=Math.max(0,5-placements[p].settlements.size+cityCap);
  if(cityCap+settleCap<gap) return false;
  // 1点に最低4枚（開拓地）、都市化は5枚。交換や道路コストを無視した上界なので、
  // falseなら絶対に届かない。序盤に道路DFSを走らせないための安全な足切り。
  let cards=handTotal(p);
  if(allowResourceCard && !game.devPlayed){
    try{
      if(canPlay("plenty")) cards+=2;
      if(canPlay("mono")){
        let best=0;
        for(const r of RES5){ let n=0; for(const q of game.order) if(q!==p) n+=game.hands[q][r]||0; best=Math.max(best,n); }
        cards+=best;
      }
    }catch(e){}
  }
  return Math.floor(cards/4)>=gap;
}
function _forcedWinRule(p){
  if((_inPlayout&&!_allowForcedWinInPlayout) || game.phase!=="main") return false;
  if(!(ROAD_WIN_SEATS ? ROAD_WIN_SEATS.has(p) : ROAD_WIN)) return false;
  // 道賞を含む既存の完全探索を最初に使う。
  if(_roadWinRule(p)) return true;
  if(!(FORCED_WIN_SEATS && FORCED_WIN_SEATS.has(p))) return false;

  // 騎士賞を取った後、都市・開拓地・そこへ至る道を組み合わせれば確定勝ちになる形。
  // 盗賊で奪う資源は一切あてにせず、現在の手札だけで完遂できる場合に限る。
  if(_fwKnightTakesArmy(p) && _fwCouldReachByBuildings(p,2,false)){
    const kp=_fwFindBuildPlan(p,2,"none",4);
    if(kp){ playDev("knight"); return true; }
  }

  // 港/銀行交換、収穫、独占、街道建設、複数建設をまとめて列挙。
  // 最大4本の新設道路まで扱い、「道→開拓地」の確定勝ちも通常評価より先に実行する。
  if(!_fwCouldReachByBuildings(p,0,true)) return false;
  const plan=_fwFindBuildPlan(p,0,undefined,4);
  return plan ? _fwExecuteBuildPlan(p,plan) : false;
}
function _rwOppCanExceed(p, myNewLen){
  for(let q=1;q<=numPlayers;q++){
    if(q===p) continue;
    if(placements[q].roads.size>=15) continue;
    const h=game.hands[q];
    let k=Math.min(h.wood, h.brick);
    try{ if(!game.dev.hands[q] || game.dev.hands[q].roads>0) k+=2; }catch(e){}
    if(k<=0) continue;
    const saveRoads=new Set(placements[q].roads);
    const r=_rwBestExtension(q, Math.min(k,3), myNewLen+1);
    placements[q].roads=saveRoads;
    if(r) return true;
  }
  return false;
}
function _rwP2VPNextTurn(p){
  const canUpgrade = placements[p].settlements.size>0 && (placements[p].cities?placements[p].cities.size:0)<4;
  const canSettle  = placements[p].settlements.size + (placements[p].cities?placements[p].cities.size:0) < 7;
  if(!canUpgrade && !canSettle) return 0;
  const base=Object.assign({}, game.hands[p]);
  const pr=production(p);   // 1ダイスあたりの期待産出（出目別に分解できないので近似に使う）
  const DICE=[[2,1],[3,2],[4,3],[5,4],[6,5],[7,6],[8,5],[9,4],[10,3],[11,2],[12,1]];
  // 出目ごとの実収入を数える
  let ok=0, tot=0;
  for(const [d,w] of DICE){
    tot+=w;
    if(d===7) continue;                      // 7は産出なし
    const h=Object.assign({}, base);
    for(const hx of GEO.hexes){
      const b=board[hx.id];
      if(!b||b.number!==d||!b.resource||b.resource==="desert") continue;
      if(hx.id===game.robber) continue;
      for(const v of hexVertsG(hx.id)){
        const oc=occupantOf(v);
        if(oc&&oc.p===p) h[b.resource]+=(oc.type==="city")?2:1;
      }
    }
    // 2点ぶん（都市2 / 都市+開拓地 / 開拓地2）を賄えるか
    const pay=(hh,c,times)=>{ for(let i=0;i<times;i++){ for(const r in c){ if(hh[r]<c[r]) return false; } for(const r in c) hh[r]-=c[r]; } return true; };
    let good=false;
    if(canUpgrade){ const h2=Object.assign({},h); if((placements[p].cities?placements[p].cities.size:0)<=2 && pay(h2,COST.city,2)) good=true; }
    if(!good && canUpgrade && canSettle){ const h2=Object.assign({},h); if(pay(h2,COST.city,1)&&pay(h2,COST.settlement,1)) good=true; }
    if(!good && canSettle){ const h2=Object.assign({},h); if(pay(h2,COST.settlement,2)) good=true; }
    if(good) ok+=w;
  }
  return tot? ok/tot : 0;
}
function _roadWinRule(p){
  if(_inPlayout&&!_allowForcedWinInPlayout) return false; // 通常探索は軽量化、終局プレイアウトは実戦方策を再現
  if(!(ROAD_WIN_SEATS ? ROAD_WIN_SEATS.has(p) : ROAD_WIN)) return false;
  if(placements[p].roads.size>=15) return false;
  if(game.lr.holder===p) return false;                 // 既に保持
  const holder=game.lr.holder;
  const target = holder ? (game.lr.len+1) : 5;         // 並ぶだけでは奪えない＝厳密に上回る
  // 騎士1枚で騎士賞を確定し、その+2点と道賞+2点で10点になる経路。
  // 騎士使用後はいったん盗賊フェーズへ移るが、処理後のmainで本関数が再度走り道を完遂する。
  try{
    // 旧版は「現在6点以上で、騎士賞+道賞だけで10点」の形しか拾えなかった。
    // 建物を同じターンに挟む確定手順まで資源・交換込みで確認してから騎士を切る。
    if(_rwKnightWinningPlan(p,target)){ playDev("knight"); return true; }
  }catch(e){}
  const aff=_rwAffordableRoads(p);
  if(aff.n<=0) return false;
  const plan=_rwBestExtension(p, aff.n, target);
  if(!plan || !plan.edges.length) return false;
  // 最終道路を仮置きし、その道で新しく開く開拓地も含めて「建物＋道賞＝10点」を調べる。
  for(const eid of plan.edges) placements[p].roads.add(eid);
  const buildPlans=_rwWinningBuildPlans(p);
  for(const eid of plan.edges) placements[p].roads.delete(eid);
  let winning=null;
  for(const bp of buildPlans){
    const f=_rwFundingPlan(p,plan.edges.length,bp.cost);
    if(f){ winning={build:bp,funding:f}; break; }
  }
  const vpAfter = vpOf(p) + 2;
  let go=!!winning;
  if(!go && ROAD_NEAR_WIN && (vpAfter===8 || vpAfter===9)){ // 8/9点の強制は実測で都市を潰したため可逆化
    if(!_rwOppCanExceed(p, plan.len) && _rwP2VPNextTurn(p)>=0.25) go=true;
  }
  if(!go) return false;
  const funding=winning?winning.funding:_rwFundingPlan(p,plan.edges.length);
  if(!funding) return false;
  // 実行: 必要なら発展カード→解決→港/銀行交換→一筆書きの順に進める。
  if(funding.card && !game.devPlayed){
    try{
      playDev(funding.card);
      if(funding.card==="plenty"){
        for(const r of funding.picks) if(game.ask) resolvePlenty(r);
      }else if(funding.card==="mono" && game.ask){
        resolveMono(funding.picks[0]);
      }
    }catch(e){ return false; }
  }
  for(const t of funding.trades){ if(!_tradeBank(p,t.give,t.get)) return false; }
  // 都市は道路より先に建てられる。先に点を上げてから道賞を取れば、その道で即10点になる。
  if(winning) for(const vid of winning.build.cities){
    if(game.phase!=="main"||!canPay(p,COST.city)) return false;
    gameClickVertex(vid);
  }
  let built=0;
  for(const eid of plan.edges){
    if(ownerOf("roads",eid)) continue;
    if(!(game.freeRoads>0) && !canPay(p,COST.road)) break;
    try{ gameClickEdge(eid); built++; }catch(e){ break; }
    if(game.phase!=="main") break;                     // 勝利で終局
  }
  // 道によって初めて開いた建設地は、道賞取得後に家を建てて10点へ到達する。
  if(winning && game.phase==="main") for(const vid of winning.build.settles){
    if(!canPay(p,COST.settlement)) return built>0;
    gameClickVertex(vid);
    if(game.phase!=="main") break;
  }
  return built>0;
}

/* ===== [2026-08-18 無敵AI] 研究側 zoo.js から移植したロールアウト探索一式 =====
   人間棋譜11試合で学習した価値関数 V_human(23特徴, AUC 0.93) を葉に使い、
   各決定を M=24 の打ち切りプレイアウトで評価する。標準AIを'置換'せず'上書き'する構造
   （stdrest候補＋マージン）＝標準が明確に劣る時だけ探索手を採用する。
   研究側実測: 配置3項の上に +4pt（標準AIに +10.0pt → +14.0pt）。 ===== */
const VALUE_W_HUMAN = [-3.502760812501638, 0.29534758818479895, -0.6393882204524826, 0.057823297914609356, 0.4314983233533723, 0.1274437282814457, 0.17788169533619397, -0.04037374451142822, 0.2561029269458832, 0.5855111533194708, -0.6037131026419419, 0.20157421019135824, 0.049672136741915285, 0, -0.22646622808936198, -0.1855956520730821, -0.34234031834017925, 0, 1.9570317030340754, -0.09886541805936676, 0.15710282085281033, 0.016269328745739456, -2.7735221284258924, 2.4049505026449913];
function _valScore(feat){ let z=VALUE_W_HUMAN[0]; const n=Math.min(feat.length, VALUE_W_HUMAN.length-1);
  for(let i=0;i<n;i++) z+=VALUE_W_HUMAN[i+1]*feat[i];
  if(z>30) return 1; if(z<-30) return 0; return 1/(1+Math.exp(-z)); }
// 勝率ゲージ専用。相手モデリング7特徴を加えた人間棋譜モデル（30特徴・holdout AUC 0.9457）。
// AI本体の探索葉は検証済み23特徴のままにし、表示だけを高精度化する。
const WIN_VALUE_W_HUMAN3 = [1.0589354303744711,0.506204075570411,-0.5006489459699921,0.31144633200797583,0.41624477007394145,0.1136729036364452,0.15154003739726676,-0.05884958764097819,0.285401983229417,1.1771556562068535,-0.49978457216497385,0.07517835306553154,0.09139720609008628,0,-0.10579432718120303,-0.06458388511186453,-0.3635598375056709,0,1.3197485715621184,-0.08874957214890791,0.10281423625727398,0.025306936562719776,-3.4844641318906864,2.272411353520349,-3.823261044347526,0.01936665735650868,0.18917194931963294,-0.7634572710541324,-0.39368470173448744,-6.573977630965536,0.023631198102533967];
function _winValScore(feat){ let z=WIN_VALUE_W_HUMAN3[0],n=Math.min(feat.length,WIN_VALUE_W_HUMAN3.length-1);
  for(let i=0;i<n;i++)z+=WIN_VALUE_W_HUMAN3[i+1]*feat[i];
  if(z>30)return 1;if(z<-30)return 0;return 1/(1+Math.exp(-z)); }
const _origRandom = Math.random;
let _rngOn = false, _rngState = 12345;
let _roStats = {stdrest:0, endturn:0, city:0, tradecity:0, settle:0, tradesettle:0, road:0, dev:0, searched:0, delegated:0};
// ブラウザ実測: M=24/打ち切り30 は1手番17秒で実用外。M=8/打ち切り15 に落とす（node側で強さを検証）
let CH_ROLLOUT_MAIN=false, CH_ROLLOUT_M=8, CH_ROLLOUT_TRUNC=15, CH_ROLLOUT_MINOPT=1, CH_ROLLOUT_MARGIN=0.08, CH_ROLLOUT_CRN=1;
let ROLLOUT_SEATS=null;   // この席だけ探索する（無敵AI）
function _baseBotMain(p){ return _botMain(p); }
function _prodNumbers(pl){
  const m={};
  for(const kind of ["settlements","cities"]){ const set=placements[pl]&&placements[pl][kind]; if(!set) continue;
    const mult=kind==="cities"?2:1;
    for(const vid of set) for(const hid of (GEO.vertex_hexes[String(vid)]||[])){ const b=board[hid];
      if(b&&b.number&&b.resource&&b.resource!=="desert") m[b.number]=(m[b.number]||0)+pipOf(b.number)*mult; }
  }
  return m;
}
function _rivalNonOverlap(me,q){
  if(process.env.HA_NORIVAL) return 1;   // アブレーション: H11(出目重なり)を切る
  const mm=_prodNumbers(me), qm=_prodNumbers(q);
  let nonOv=0, tot=0;
  for(const n in qm){ tot+=qm[n]; if(!mm[n]) nonOv+=qm[n]; }
  if(tot<=0) return 1;
  return 1 + 0.5*(nonOv/tot);   // 非重複が多い相手＝真のライバル（最大1.5倍）
}
function _prodPips(p){
  const pr = production(p);
  return { tot:(pr.wood+pr.brick+pr.sheep+pr.wheat+pr.ore)*36,
           ow:(pr.ore+pr.wheat)*36, wb:(pr.wood+pr.brick)*36, sh:pr.sheep*36 };
}
function _portCount(p){
  try {
    const pv = _portVerts();                       // 港に接する頂点のSet
    let c = 0;
    for (const v of placements[p].settlements) if (pv.has(v)) c++;
    for (const v of (placements[p].cities||[])) if (pv.has(v)) c++;
    return c;
  } catch(e){ return (typeof _hasPort==="function" && _hasPort(p)) ? 1 : 0; }
}
function _nextBuildCostH9(q){
  const nc=(placements[q].cities?placements[q].cities.size:0), ns=placements[q].settlements.size;
  const cands=[];
  if(ns>0 && nc<4) cands.push(COST.city);
  if(ns+nc<7) cands.push(COST.settlement);
  cands.push(COST.dev);
  let best=cands[0], bt=Infinity;
  for(const c of cands){ const t=turnsToAfford(q,c); if(t<bt){ bt=t; best=c; } }
  return {cost:best, turns:bt};
}
function stateFeat(p){
  const pl = placements[p];
  const c = pl.cities ? pl.cities.size : 0, s = pl.settlements.size;
  const bvp = s + 2*c;
  const pp = _prodPips(p);
  const vp = vpOf(p);
  const port = _portCount(p);
  const army = (game.army && game.army[p]) || 0;
  let lr = 0; try { lr = longestRoadOf(p); } catch(e){}
  const hand = RES5.reduce((a,r)=>a+game.hands[p][r], 0);
  const dev = (game.dev && game.dev.hands && game.dev.hands[p])
              ? Object.values(game.dev.hands[p]).reduce((a,b)=>a+b,0) : 0;
  let oppVP=0, oppProd=0;
  for (let q=1;q<=numPlayers;q++){ if(q===p) continue;
    oppVP=Math.max(oppVP, vpOf(q)); oppProd=Math.max(oppProd, _prodPips(q).tot); }
  const rc = game.rollCount || 0;
  // ==== [解説由来の追加特徴] 強い人間が実際に計算している量 ====
  const prod = production(p);
  const owMin = Math.min(prod.ore||0, prod.wheat||0);                     // 鉄麦バランス（都市化力・解説が最重視）
  let myTurns=20; try{ const t=_nextBuildCostH9(p).turns; if(isFinite(t)) myTurns=Math.min(20,t); }catch(e){}  // 自分の次建設の近さ（"4ダイス単位"）
  let oppMinTurns=20, rivalNO=0;
  for(let q=1;q<=numPlayers;q++){ if(q===p) continue;
    try{ const t=_nextBuildCostH9(q).turns; if(isFinite(t)) oppMinTurns=Math.min(oppMinTurns,t); }catch(e){}   // 相手の最速建設の近さ（盗賊の的）
    try{ const rn=_rivalNonOverlap(p,q)*(_prodPips(q).tot||0); if(rn>rivalNO) rivalNO=rn; }catch(e){}           // H11 出目非重複＝真のライバル
  }
  let portSyn=0;   // 港シナジー: 自分が触れる資源港×その資源の産出（"生かせる港"だけ価値・解説）
  try{ for(const eid in ports){ const t=ports[eid]; if(t==='3:1') continue; const e=GEO.edges[+eid]; if(!e) continue;
    if([e.a,e.b].some(v=>{const oc=occupantOf(v); return oc&&oc.p===p;}) && prod[t]!=null) portSyn+=prod[t]; } }catch(e){}
  let robbedOW=0;  // 盗賊が自分の鉄/麦を止めているか（エンジン停止）
  try{ const rb=board[game.robber]; if(rb&&(rb.resource==='ore'||rb.resource==='wheat')&&hexVertsG(game.robber).some(v=>{const oc=occupantOf(v); return oc&&oc.p===p;})) robbedOW=1; }catch(e){}
  return [bvp, vp, c, s, pp.tot, pp.ow, pp.wb, pp.sh, port, army, lr, hand, dev, oppVP, oppProd, vp-oppVP, rc,
          owMin, myTurns, oppMinTurns, rivalNO, portSyn, robbedOW];
}

// 勝率表示用の30特徴。相手の鉄麦・都市ETA・騎士賞・道賞・脅威度・出目競合・建設レースを追加。
function stateFeatWin(p){
  const base=stateFeat(p).slice();
  let oppOwMin=0,oppCityTurns=20,oppArmy=0,oppLR=0,oppThreat=0,dupOverlap=0;
  let myTurns=Number(base[18]); if(!isFinite(myTurns))myTurns=20;
  try{
    const myNum=_prodNumbers(p);let myTot=0;for(const n in myNum)myTot+=myNum[n];
    let rivalNO=0;
    for(let q=1;q<=numPlayers;q++){if(q===p)continue;
      try{const pq=production(q);oppOwMin=Math.max(oppOwMin,Math.min(pq.ore||0,pq.wheat||0));}catch(e){}
      try{if(placements[q].settlements.size>0&&(placements[q].cities?placements[q].cities.size:0)<4){
        const t=turnsToAfford(q,COST.city);if(isFinite(t))oppCityTurns=Math.min(oppCityTurns,t);}}catch(e){}
      oppArmy=Math.max(oppArmy,(game.army&&game.army[q])||0);
      try{oppLR=Math.max(oppLR,longestRoadOf(q));}catch(e){}
      try{oppThreat=Math.max(oppThreat,threatOf(q));}catch(e){}
      try{const qm=_prodNumbers(q);let overlap=0,nonOverlap=0,qTot=0;
        for(const n in qm){qTot+=qm[n];if(myNum[n])overlap+=myNum[n];else nonOverlap+=qm[n];}
        if(myTot>0)dupOverlap=Math.max(dupOverlap,overlap/myTot);
        if(qTot>0)rivalNO=Math.max(rivalNO,(1+0.5*nonOverlap/qTot)*(_prodPips(q).tot||0));
      }catch(e){}
    }
    base[20]=rivalNO;
  }catch(e){}
  const oppMinTurns=Number(base[19]),race=Math.max(-10,Math.min(10,(isFinite(oppMinTurns)?oppMinTurns:20)-myTurns));
  return base.concat([oppOwMin,oppCityTurns,oppArmy,oppLR,oppThreat,dupOverlap,race]);
}

// 精密シミュレーションが完了するまで表示する学習事前分布。終局だけは勝者100%。
function estimateWinProbabilities(){
  const out={};
  if(!game) return out;
  if(game.phase==="over"){
    let w=1,b=-Infinity;
    for(const q of game.order){ const v=vpOf(q); if(v>b){b=v;w=q;} }
    for(const q of game.order) out[q]=(q===w?1:0);
    return out;
  }
  let sum=0;
  for(const q of game.order){
    let v=0.25; try{ v=_winValScore(stateFeatWin(q)); }catch(e){}
    v=Math.max(0.0001,Math.min(0.9999,v)); out[q]=v; sum+=v;
  }
  if(sum<=0){ for(const q of game.order) out[q]=1/game.order.length; }
  else for(const q of game.order) out[q]/=sum;
  // AUCは順位性能であり確率校正ではない。序盤の過信を防ぎ、進行に応じて25%からモデル値へ寄せる。
  const maxVP=Math.max(...game.order.map(q=>vpOf(q))), rc=game.rollCount||0;
  const confidence=Math.max(0.08,Math.min(0.95, Math.max(0,maxVP-2)/7*0.75 + Math.min(1,rc/120)*0.25));
  for(const q of game.order) out[q]=0.25*(1-confidence)+out[q]*confidence;
  return out;
}

// ===== 勝率ゲージ用・厳密ルールの終局プレイアウト =====
// 軽量近似simは過去検証で方策の再現性が不足したため使わない。本物のルールエンジンを
// 同期的に1局ずつ複製して回し、毎局必ず元局面へ復元する。初期配置中は学習値だけを使う。
function winFullPlayoutContext(){
  if(!game||game.phase==="setup"||game.phase==="over")return null;
  return {snapshot:snapshotState()};
}
function _wmSeededRandom(seed){let x=(seed>>>0)||1;return ()=>{x=(Math.imul(x,1664525)+1013904223)>>>0;return x/4294967296;};}
function _wmFullPlayToEnd(){
  let rolls=0,iters=0;
  try{
    while(game.phase!=="over"&&rolls<400){
      const q=cur();if(typeof _applyVariant==="function")_applyVariant(q);
      if(game.phase==="roll"){if(_shouldPlayKnight(q))playDev("knight");if(game.phase==="roll"){doRoll(null);rolls++;}}
      if(game.phase==="discard"){while(game.discardQueue.length)_botDiscard();}
      if(game.phase==="robber"){const ra=robberAdvice();gameClickHex(ra?ra.hid:GEO.hexes.find(h=>h.id!==game.robber).id);}
      if(game.phase==="steal")stealFrom(bestStealTarget(game.stealCands));
      if(game.phase==="main"){_botMain(q);_cleanupTurn(q);if(game.phase==="main")endTurnGame();}
      if(++iters>3000)break;
    }
  }catch(e){return 0;}
  if(game.phase!=="over")return 0;
  let winner=1,best=-1;for(let q=1;q<=numPlayers;q++){const v=vpOf(q);if(v>best){best=v;winner=q;}}return winner;
}
function winFullPlayoutSample(base,seed){
  if(!base)return 0;
  const saved={render,updateGamePanel,toast,glog,_recAct,snapshotTurn,random:Math.random,
    inPlayout:_inPlayout,allowForcedWin:_allowForcedWinInPlayout,seatAI:(typeof seatAI!=="undefined"?seatAI:null)};
  const flags={ETA_W,ETA_SEATS,SCARCE_W,SCARCE_SEATS,LOOK_W,LOOK_SEATS,ROAD_WIN_SEATS,ROAD_NEAR_WIN,FORCED_WIN_SEATS,DYNAMIC_ROUTE_CFG,TURN_CFG,ROLLOUT_SEATS,
    ROAD_PATH_SEATS,ROAD_PORT_W,PRIZE_THREAT_SEATS,PRIZE_EXACT_SEATS,PRIZE_THREAT_MIN_VP_CFG,PRIZE_TRADE_DEV_SEATS,
    ROBBER_RP_ARMY,PORT_SYNERGY,HP1_PORT,ROBBER_DELAY,HUMAN_SETUP};
  let winner=0;
  try{
    render=()=>{};updateGamePanel=()=>{};toast=()=>{};glog=()=>{};_recAct=()=>{};snapshotTurn=()=>{};
    Math.random=_wmSeededRandom(seed);_inPlayout=true;_allowForcedWinInPlayout=true;restoreState(base.snapshot);
    if(typeof seatAI!=="undefined")seatAI={1:"strong",2:"strong",3:"strong",4:"strong"};
    if(game&&game.dev&&Array.isArray(game.dev.deck)){
      const d=game.dev.deck;for(let i=d.length-1;i>0;i--){const j=Math.random()*(i+1)|0;[d[i],d[j]]=[d[j],d[i]];}
    }
    winner=_wmFullPlayToEnd();
  }finally{
    restoreState(base.snapshot);render=saved.render;updateGamePanel=saved.updateGamePanel;toast=saved.toast;glog=saved.glog;_recAct=saved._recAct;snapshotTurn=saved.snapshotTurn;
    Math.random=saved.random;_inPlayout=saved.inPlayout;_allowForcedWinInPlayout=saved.allowForcedWin;if(saved.seatAI)seatAI=saved.seatAI;
    ETA_W=flags.ETA_W;ETA_SEATS=flags.ETA_SEATS;SCARCE_W=flags.SCARCE_W;SCARCE_SEATS=flags.SCARCE_SEATS;LOOK_W=flags.LOOK_W;LOOK_SEATS=flags.LOOK_SEATS;
    ROAD_WIN_SEATS=flags.ROAD_WIN_SEATS;ROAD_NEAR_WIN=flags.ROAD_NEAR_WIN;FORCED_WIN_SEATS=flags.FORCED_WIN_SEATS;DYNAMIC_ROUTE_CFG=flags.DYNAMIC_ROUTE_CFG;TURN_CFG=flags.TURN_CFG;ROLLOUT_SEATS=flags.ROLLOUT_SEATS;ROAD_PATH_SEATS=flags.ROAD_PATH_SEATS;ROAD_PORT_W=flags.ROAD_PORT_W;
    PRIZE_THREAT_SEATS=flags.PRIZE_THREAT_SEATS;PRIZE_EXACT_SEATS=flags.PRIZE_EXACT_SEATS;PRIZE_THREAT_MIN_VP_CFG=flags.PRIZE_THREAT_MIN_VP_CFG;PRIZE_TRADE_DEV_SEATS=flags.PRIZE_TRADE_DEV_SEATS;
    ROBBER_RP_ARMY=flags.ROBBER_RP_ARMY;PORT_SYNERGY=flags.PORT_SYNERGY;HP1_PORT=flags.HP1_PORT;ROBBER_DELAY=flags.ROBBER_DELAY;HUMAN_SETUP=flags.HUMAN_SETUP;
  }
  return winner;
}

function _mainBuildCands(p){
  const cands=[]; const adv=computeAdvice();
  const ci=adv.find(a=>a.label.startsWith("都市化")&&a.target&&a.target.id!=null);
  if(ci && placements[p].cities.size<4){ if(canPay(p,COST.city)) cands.push({kind:'city',v:ci.target.id}); else if(_canCompleteByTrade(p,COST.city)) cands.push({kind:'tradecity',v:ci.target.id}); }
  const si=adv.find(a=>a.label.startsWith("開拓地")&&a.target&&a.target.id!=null);
  if(si && placements[p].settlements.size<5){ if(canPay(p,COST.settlement)) cands.push({kind:'settle',v:si.target.id}); else if(_canCompleteByTrade(p,COST.settlement)) cands.push({kind:'tradesettle',v:si.target.id}); }
  const ri=adv.find(a=>a.label.startsWith("道")&&a.target&&a.target.id!=null);
  if(ri && (canPay(p,COST.road)||game.freeRoads>0) && placements[p].roads.size<15) cands.push({kind:'road',e:ri.target.id});
  if(game.dev.deck.length && canPay(p,COST.dev)) cands.push({kind:'dev'});
  return cands;
}
function _applyCandVal(p, a){
  // 実行できたら true。エンジンのプリミティブ（_botMainと同じgameClick経路）を使う。
  if (a.kind === 'city')       { if (canPay(p, COST.city)) { gameClickVertex(a.v); return true; } return false; }
  if (a.kind === 'tradecity')  { _tradeToward(p, COST.city); if (canPay(p, COST.city)) { gameClickVertex(a.v); return true; } return false; }
  if (a.kind === 'settle')     { if (canPay(p, COST.settlement)) { gameClickVertex(a.v); return true; } return false; }
  if (a.kind === 'tradesettle'){ _tradeToward(p, COST.settlement); if (canPay(p, COST.settlement)) { gameClickVertex(a.v); return true; } return false; }
  if (a.kind === 'road')       { if (canPay(p, COST.road) || game.freeRoads > 0) { gameClickEdge(a.e); return true; } return false; }
  if (a.kind === 'dev')        { if (game.dev.deck.length && canPay(p, COST.dev)) { buyDev(); return true; } return false; }
  return false;
}
function _playoutTruncV(p, K){
  const _bs=USE_BACKSOLVE, _fp=(typeof FAST_PLAYOUT!=="undefined"?FAST_PLAYOUT:false);
  const _cro=CH_ROLLOUT_MAIN;
  USE_BACKSOLVE=false; FAST_PLAYOUT=true; CH_ROLLOUT_MAIN=false;
  let rolls=0, iters=0;
  try {
    while(game.phase!=="over" && rolls<K){
      const q=cur();
      if(game.phase==="roll"){ if(_shouldPlayKnight(q)) playDev("knight"); if(game.phase==="roll"){ doRoll(null); rolls++; } }
      if(game.phase==="discard"){ while(game.discardQueue.length) _botDiscard(); }
      if(game.phase==="robber"){ const ra=robberAdvice(); gameClickHex(ra?ra.hid:GEO.hexes.find(h=>h.id!==game.robber).id); }
      if(game.phase==="steal"){ stealFrom(game.stealCands[0]); }
      if(game.phase==="main"){ _botMain(q); _cleanupTurn(q); if(game.phase==="main") endTurnGame(); }
      if(game.phase==="over") break;
      if(++iters>2000) break;
    }
  } catch(e){}
  const v = (game.phase==="over") ? (cur()===p?1:0) : _valScore(stateFeat(p));
  USE_BACKSOLVE=_bs; FAST_PLAYOUT=_fp; CH_ROLLOUT_MAIN=_cro;
  return v;
}
function _playoutToEnd(){
  const _bs=USE_BACKSOLVE, _fp=(typeof FAST_PLAYOUT!=="undefined"?FAST_PLAYOUT:false);
  const _cvm=CH_VALUE_MAIN,_cmm=CH_META_MAIN,_csm=CH_SEARCH_MAIN,_crm=CH_RACE_MAIN,_cro=CH_ROLLOUT_MAIN;
  USE_BACKSOLVE=false; FAST_PLAYOUT=true;
  ROLES={1:"standard",2:"standard",3:"standard",4:"standard"};
  CH_VALUE_MAIN=false; CH_META_MAIN=false; CH_SEARCH_MAIN=false; CH_RACE_MAIN=false; CH_ROLLOUT_MAIN=false;
  let rolls=0, iters=0;
  try {
    while(game.phase!=="over" && rolls<400){
      const q=cur();
      if(game.phase==="roll"){ if(_shouldPlayKnight(q)) playDev("knight"); if(game.phase==="roll"){ doRoll(null); rolls++; } }
      if(game.phase==="discard"){ while(game.discardQueue.length) _botDiscard(); }
      if(game.phase==="robber"){ const ra=robberAdvice(); gameClickHex(ra?ra.hid:GEO.hexes.find(h=>h.id!==game.robber).id); }
      if(game.phase==="steal"){ stealFrom(game.stealCands[0]); }
      if(game.phase==="main"){ _botMain(q); _cleanupTurn(q); if(game.phase==="main") endTurnGame(); }
      if(game.phase==="over") break;
      if(++iters>3000) break;
    }
  } catch(e){}
  let winner=1,bv=-1; for(let q=1;q<=numPlayers;q++){ const v=vpOf(q); if(v>bv){bv=v;winner=q;} }
  USE_BACKSOLVE=_bs; FAST_PLAYOUT=_fp;
  CH_VALUE_MAIN=_cvm; CH_META_MAIN=_cmm; CH_SEARCH_MAIN=_csm; CH_RACE_MAIN=_crm; CH_ROLLOUT_MAIN=_cro;
  return winner;
}
function _rolloutEvalOnce(p, forced){
  if(forced==='endturn'){ if(game.phase==="main") endTurnGame(); }
  else if(forced==='stdrest'){ if(game.phase==="main") _baseBotMain(p); }   // 標準がこのターンの残りを打つ
  else if(forced){ _applyCandVal(p, forced); }                              // この手を打つ→残りは(プレイアウト内で)標準
  if(CH_ROLLOUT_TRUNC>0) return _playoutTruncV(p, CH_ROLLOUT_TRUNC);
  return _playoutToEnd()===p ? 1 : 0;
}
function _rolloutPick(p, cands){
  const _ip=_inPlayout; _inPlayout=true;
  try{ return _rolloutPickInner(p, cands); } finally { _inPlayout=_ip; }
}
function _rolloutPickInner(p, cands){
  const snap0=snapshotState();
  const seeds=[]; for(let m=0;m<CH_ROLLOUT_M;m++) seeds.push((_origRandom()*2147483647)|0);
  let best=null, bw=-1;
  for(const c of cands){
    let s=0;
    for(let m=0;m<CH_ROLLOUT_M;m++){
      restoreState(snap0);
      if(CH_ROLLOUT_CRN){ _rngState=seeds[m]; _rngOn=true; }
      s+=_rolloutEvalOnce(p,c.forced);
      _rngOn=false;
    }
    const wr=s/CH_ROLLOUT_M;
    const eff = (c.tag==='stdrest') ? wr + CH_ROLLOUT_MARGIN : wr;   // 標準委譲に下限マージン
    if(eff>bw){ bw=eff; best=c; }
  }
  restoreState(snap0);
  return best;
}
function challengerMainRollout(p){
  let guard=0;
  while(game.phase==="main" && guard++<10){
    const builds=_mainBuildCands(p);
    if(builds.length < CH_ROLLOUT_MINOPT){          // 探索する実質の選択肢が無い
      _roStats.delegated++;
      _baseBotMain(p);                              // 残りは標準に委ねる（建て残し・交換を回収）
      return;
    }
    _roStats.searched++;
    const cands=[{tag:'stdrest',forced:'stdrest'},{tag:'endturn',forced:'endturn'}];
    for(const b of builds) cands.push({tag:b.kind,forced:b});
    const best=_rolloutPick(p, cands);
    _roStats[best.tag]=(_roStats[best.tag]||0)+1;
    if(best.tag==='stdrest'){ if(game.phase==="main") _baseBotMain(p); return; }  // 残りは標準に委ねて終了
    if(best.tag==='endturn'){ return; }                                          // ここで建設をやめる
    if(!_applyCandVal(p, best.forced)) { _baseBotMain(p); return; }              // この手を打って次の手を探索
    if(game.phase!=="main") return;
  }
}

// game36で露呈した旧STEAL_PRIZEの過剰上書きを狭める。
// 相手の伏せVPは見ず、公開9点以上かつ最大脅威の賞保持者だけを対象にし、
// 道はその1本で本当に現在の最長路を上回れる場合だけ置く。
function _prizeThreatDefense(p,adv){
  const minVP=(PRIZE_THREAT_MIN_VP_CFG&&PRIZE_THREAT_MIN_VP_CFG[p]!=null)?PRIZE_THREAT_MIN_VP_CFG[p]:9;
  const holders=new Set();
  if(game.lr&&game.lr.holder&&game.lr.holder!==p&&_rpVisibleVP(game.lr.holder)>=minVP)holders.add(game.lr.holder);
  if(game.la&&game.la.holder&&game.la.holder!==p&&_rpVisibleVP(game.la.holder)>=minVP)holders.add(game.la.holder);
  if(!holders.size)return false;
  let threat={};try{threat=_rpRouteThreatVector(_rpArmyShareVector());}catch(e){}
  const opp=game.order.filter(q=>q!==p);let top=opp[0],best=-Infinity;
  for(const q of opp){const s=(threat[q]||0)+0.0001*_rpVisibleVP(q);if(s>best){best=s;top=q;}}
  if(!holders.has(top))return false;
  if(game.lr.holder===top&&placements[p].roads.size<15&&_canCompleteByTrade(p,COST.road)){
    let eid=null;
    if(PRIZE_EXACT_SEATS&&PRIZE_EXACT_SEATS.has(p)){
      let pl=null;try{pl=_rwBestExtension(p,1,game.lr.len+1);}catch(e){}
      if(pl&&pl.edges&&pl.edges.length===1)eid=pl.edges[0];
    }else{
      const ri=adv&&adv.find(x=>x.label.startsWith("道")&&x.target&&x.target.id!=null);
      if(longestRoadOf(p)>=game.lr.len-1&&ri)eid=ri.target.id;
    }
    if(eid!=null){_tradeToward(p,COST.road);if(canPay(p,COST.road)){gameClickEdge(eid);return true;}}
  }
  if(game.la.holder===top&&!game.devPlayed&&canPlay("knight")&&game.army[p]+1>game.army[top]){
    playDev("knight");return true;
  }
  return false;
}

// 全局面で交換カードを許すと悪化するため、都市あり・公開5点以上・完成建設なし・
// 道賞/騎士賞へ近い時だけ、通常候補として比較する。
function _prizeTradeDevEligible(p){
  if(!(PRIZE_TRADE_DEV_SEATS&&PRIZE_TRADE_DEV_SEATS.has(p)))return false;
  if(!game.dev.deck.length||placements[p].cities.size<1||canPay(p,COST.dev)||!_canCompleteByTrade(p,COST.dev))return false;
  if(canPay(p,COST.city)||canPay(p,COST.settlement)||_rpVisibleVP(p)<5)return false;
  let nearRoad=false,nearArmy=false;
  try{const target=game.lr.holder&&game.lr.holder!==p?game.lr.len+1:5;nearRoad=game.lr.holder!==p&&longestRoadOf(p)>=target-1;}catch(e){}
  try{const target=game.la.holder&&game.la.holder!==p?game.la.count+1:3;const held=(game.dev.hands[p]&&game.dev.hands[p].knight)||0;nearArmy=game.la.holder!==p&&(game.army[p]||0)+held>=target-2;}catch(e){}
  return nearRoad||nearArmy;
}

function _botMain(p){ // 建設フェーズ: 提案リストに従って行動（最大12手）
  // 鉄温存（ユーザーのプレイング移植）: 最初の都市がまだ無い偏った鉄配置では、
  // 鉄を都市化のためだけに残し、カード等に流さない。「上振れが来た時に鉄が手元にある」状態を保つ。
  // 自動発動: 都市0個 & 開拓地あり & 鉄の生産期待値が低い(=上振れ待ちが正解の配置)時だけON。
  // ※oreAccessは毎ターン全員分呼ぶと無駄なので、AUTO_HOARDがONかつ都市0個の時だけ計算する。
  // === WIN_RACE（ユーザー仮説の移植）: 勝利までの最速ルートを組む ===
  // フェーズ1（建物VP<6）: 都市1個を土台に、建物だけで6点を目指す。この間カードは引かない。
  // フェーズ2（建物VP>=6）: 残り点を最速ルート（建物/道賞/騎士賞/カード）で取り切る。
  const _winRace = (typeof WIN_RACE!=="undefined" && WIN_RACE);
  const _wrPhase1 = _winRace && buildingVpOf(p) < 6;
  const _hoardOre = (typeof HOARD_ORE!=="undefined" && HOARD_ORE)
                    || (typeof AUTO_HOARD!=="undefined" && AUTO_HOARD
                        && placements[p].cities.size===0 && placements[p].settlements.size>0
                        && typeof oreAccess==="function" && oreAccess(p) < ORE_HOARD_THRESH)
                    // CITY_FOCUS: 都市化の母体があり上限未満なら、鉄をカード等に流さず都市化に温存
                    || (typeof CITY_FOCUS!=="undefined" && CITY_FOCUS
                        && placements[p].settlements.size>0 && placements[p].cities.size<4
                        && !canPay(p,COST.city));
  for(let k=0;k<12;k++){
    if(game.phase!=="main") return;
    // [game28/29コメント由来] ターン開始時と毎アクション後に、確定10点の全手順を再探索する。
    // 道賞だけでなく、複数交換・複数建設・道→家・収穫/独占/街道建設・騎士賞との複合を含む。
    // 発展カード購入のような不確定手は除き、確実な勝ちだけを通常評価より先に取り切る。
    try{
      if(_forcedWinRule(p)){
        if(game.phase!=="main") return;
        continue;
      }
    }catch(e){}
    // === CITY_FOCUS（P1の実戦データから移植）===
    // 優勝したP1は「鉄を溜めて即都市化」「余剰麦を鉄に変換して即都市化」を徹底していた。
    // 都市がまだ上限未満なら、都市化を最優先し、足りなければ余剰資源を鉄麦へ変換してから建てる。
    if(((typeof CITY_FOCUS!=="undefined" && CITY_FOCUS) || _wrPhase1)
       && placements[p].settlements.size>0 && placements[p].cities.size<4){
      const ci=computeAdvice().find(a=>a.label.startsWith("都市化")&&a.target&&a.target.id!=null);
      if(ci){
        if(canPay(p,COST.city)){ gameClickVertex(ci.target.id); continue; }
        // 余剰を鉄・麦へ変換して都市化を目指す（P1のターン45の動き）。ただし最初の1都市を最優先。
        if(placements[p].cities.size===0 && _canCompleteByTrade(p,COST.city)){
          _tradeToward(p,COST.city);
          if(canPay(p,COST.city)){ gameClickVertex(ci.target.id); continue; }
        }
      }
    }
    // 最初の都市化を最速で狙う（ユーザーのプレイング移植）:
    // 鉄の弱い偏った配置では、期待値より「その数字が出た時に即・最初の都市化」が勝負を決める。
    // 都市がまだ0個なら、余剰資源を交換してでも最初の1都市を最優先で建てる。
    const _firstCityRush = (typeof FIRST_CITY_RUSH!=="undefined" && FIRST_CITY_RUSH) || _hoardOre;
    if(_firstCityRush
       && placements[p].cities.size===0 && placements[p].settlements.size>0){
      const ci=computeAdvice().find(a=>a.label.startsWith("都市化")&&a.target&&a.target.id!=null);
      if(ci){
        if(canPay(p,COST.city)){ gameClickVertex(ci.target.id); continue; }
        // 足りなければ、余剰資源を総動員して都市化を目指す（普段より積極的に交換）
        if(_canCompleteByTrade(p,COST.city)){
          _tradeToward(p,COST.city);
          if(canPay(p,COST.city)){ gameClickVertex(ci.target.id); continue; }
        }
      }
    }
    // 手持ちの発展カードを状況で使う
    if(!game.devPlayed){
      // 収穫(plenty): 建設まであと2枚以内の資源を取って即建設につなげる
      if(canPlay("plenty")){
        let want=[];
        // 都市化にあと少し→鉄麦
        if(placements[p].settlements.size>0 && placements[p].cities.size<4){
          const wNeed=Math.max(0,2-game.hands[p].wheat), oNeed=Math.max(0,3-game.hands[p].ore);
          if(wNeed+oNeed<=2 && wNeed+oNeed>0){ for(let i=0;i<oNeed;i++) want.push("ore"); for(let i=0;i<wNeed;i++) want.push("wheat"); }
        }
        // 開拓地/道にあと少し→不足の建材（木土羊麦のうち足りない2つ）
        if(want.length===0){
          const short=[];
          for(const [r,need] of [["wood",1],["brick",1],["sheep",1],["wheat",1]]) if(game.hands[p][r]<need) short.push(r);
          for(let i=0;i<2 && i<short.length;i++) want.push(short[i]);
          while(want.length<2 && want.length>0) want.push(want[0]);   // 1種しか無ければ2枚同種
        }
        if(want.length>0){
          playDev("plenty");
          for(let i=0;i<2&&game.ask;i++) resolvePlenty(want[i]||want[0]||"ore");
        }
      }
      // 独占(mono): 自分が都市化/建設に必要な鉄・麦を狙い、相手の保有合計が多いほど有効
      if(!game.devPlayed && canPlay("mono")){
        // 自分に一番効く資源＝都市化に足りない鉄or麦を優先。相手の保有量で価値を測る。
        const needOre = placements[p].cities.size<4 && placements[p].settlements.size>0;
        let best=null,bn=0;
        for(const r of RES5){
          let n=0; for(const q of game.order){ if(q!==p) n+=game.hands[q][r]; }
          // 鉄麦は都市化に直結するので重み付け
          const w=(r==="ore"||r==="wheat")?MONO_OW_WEIGHT:1.0;
          if(n*w>bn){ bn=n*w; best=r; }
        }
        // 3枚以上取れて、かつ鉄麦なら発動。建材でも4枚以上なら発動。
        const raw=(()=>{let n=0;for(const q of game.order){if(q!==p)n+=game.hands[q][best];}return n;})();
        const ow=(best==="ore"||best==="wheat");
        if((ow && raw>=3) || raw>=4){ playDev("mono"); resolveMono(best); }
      }
      // 最強AIは、街道建設を「木土不足だから」ではなく、現在の10点ルートが
      // 道賞または家への接続を支持する時だけ使う。通常AIは従来挙動を維持。
      const _lrNeed=(game.lr.holder&&game.lr.holder!==p)?game.lr.len+1:5;
      const _lrClose = game.lr.holder!==p && longestRoadOf(p)>=_lrNeed-2;   // 道賞まであと2本以内
      if(!game.devPlayed && canPlay("roads")){
        const dr=_dynamicRoadCardIntent(p);
        if(dr?dr.use:(game.hands[p].wood+game.hands[p].brick<2||(vpOf(p)>=8&&_lrClose)))playDev("roads");
      }
    }
    const adv=computeAdvice();
    // ===== ワンチャン狙いv3: 明確な最下位なら、カード購入を積極化（VPカードで一発逆転狙い） =====
    if(typeof GAMBIT3!=="undefined" && GAMBIT3 && AGGRO_TRADE){
      const vps=[1,2,3,4].map(q=>vpOf(q));
      const myVp=vps[p-1];
      const maxOther=Math.max(...vps.filter((v,i)=>i+1!==p));
      const isDesperate3 = myVp<=Math.min(...vps) && maxOther-myVp>=3;
      if(isDesperate3 && !game.devPlayed && game.dev.deck.length && canPay(p,COST.dev)){
        if(!_hoardOre && !_wrPhase1){ buyDev(); continue; }
      }
    }
    // ===== 家を能動的に一定数維持する（production diversity狙い。1番手は+1で拡張の出遅れを補う） =====
    const _sFloor=settleFloorFor(p);
    if(_sFloor>0 && AGGRO_TRADE && placements[p].settlements.size<_sFloor
       && placements[p].settlements.size<5 && vpOf(p)<9){
      const si0=adv.find(x=>x.label.startsWith("開拓地")&&x.target&&x.target.id!=null);
      if(si0 && _canCompleteByTrade(p,COST.settlement)){
        _tradeToward(p,COST.settlement);
        if(canPay(p,COST.settlement)){ gameClickVertex(si0.target.id); continue; }
      }
    }
    // ===== ワンチャン狙い: 明確な最下位なら、港を活かして強引に鉄麦へ寄せる（安全策より逆転優先） =====
    if(typeof GAMBIT!=="undefined" && GAMBIT && AGGRO_TRADE){
      const vps=[1,2,3,4].map(q=>vpOf(q));
      const myVp=vps[p-1];
      const maxOther=Math.max(...vps.filter((v,i)=>i+1!==p));
      const isDesperate = myVp<=Math.min(...vps) && maxOther-myVp>=3;
      if(isDesperate && placements[p].settlements.size>0 && placements[p].cities.size<4){
        // 港があるかに関わらず、余剰資源を早め（閾値を下げて）に鉄麦へ寄せる
        const wNeed=Math.max(0,2-game.hands[p].wheat), oNeed=Math.max(0,3-game.hands[p].ore);
        if(wNeed+oNeed>0 && wNeed+oNeed<=4){   // 通常よりゆるい基準で先制的に交換を試みる
          _tradeToward(p, COST.city);
          if(canPay(p,COST.city)){
            const ciG=computeAdvice().find(x=>x.label.includes("都市化")&&x.target&&x.target.id!=null);
            if(ciG){ gameClickVertex(ciG.target.id); continue; }
          }
        }
      }
    }
    // ===== 妨害: 最大脅威の賞保持者だけを、賞へ直結する手で止める =====
    if(typeof STEAL_PRIZE!=="undefined" && STEAL_PRIZE && AGGRO_TRADE){
      if(PRIZE_THREAT_SEATS&&PRIZE_THREAT_SEATS.has(p)){
        if(_prizeThreatDefense(p,adv))continue;
      }else{
      let stole=false;
      for(const q of game.order){
        if(q===p) continue;
        if(stole) break;
        if(vpOf(q)<DANGER_VP) continue;   // 危険とみなすVP閾値（ユーザー調整: 8）
        // 道賞を持っているなら、自分が追いつける（1本伸ばせば上回る）なら奪う
        if(game.lr.holder===q){
          const myLen=longestRoadOf(p);
          if(myLen>=game.lr.len-1 && placements[p].roads.size<15){
            const ri2=adv.find(x=>x.label.startsWith("道")&&x.target&&x.target.id!=null);
            if(ri2 && _canCompleteByTrade(p,COST.road)){
              _tradeToward(p,COST.road);
              if(canPay(p,COST.road)){ gameClickEdge(ri2.target.id); stole=true; }
            }
          }
        }
        // 騎士賞を持っているなら、自分が1枚出せば逆転できるなら出す
        if(!stole && game.la.holder===q && !game.devPlayed && canPlay("knight") && game.army[p]+1>game.army[q]){
          playDev("knight"); stole=true;
        }
      }
      if(stole) continue;
      }
    }
    let a=adv.find(x=>x.can);
    // 開拓地の資源と合法な建設地が揃っているのに、先に道やカードへ木土羊麦を使って
    // 「今建つ家」を自分で消してはいけない。都市化（交換して即都市化を含む）が
    // 現在の最善手なら都市を優先するが、それ以外の行動より完成済みの開拓地を先に回収する。
    // 道賞の即勝ちはこの直前の _roadWinRule が先に処理するので妨げない。
    const _readySettle=adv.find(x=>x.can && x.label.startsWith("開拓地")&&x.target&&x.target.id!=null);
    if(_readySettle && (!a || (!a.label.includes("都市化") && !a.label.startsWith("開拓地")))) a=_readySettle;
    if(!a || a.label.startsWith("ターン終了")){
      // ===== 終盤の即勝ちルート =====
      if(AGGRO_TRADE && vpOf(p)>=8){
        // 道賞まであと1本なら道を建てて+2（勝ち筋）
        const myLen=longestRoadOf(p);
        const need=(game.lr.holder&&game.lr.holder!==p)?game.lr.len+1:5;
        if(game.lr.holder!==p && myLen>=need-1 && placements[p].roads.size<15 && _canCompleteByTrade(p,COST.road)){
          const ri=adv.find(x=>x.label.startsWith("道")&&x.target&&x.target.id!=null);
          if(ri){ _tradeToward(p,COST.road); if(canPay(p,COST.road)){ gameClickEdge(ri.target.id); continue; } }
        }
        // 9点ならVPカード釣り（1枚で勝ち）
        if(vpOf(p)>=9 && game.dev.deck.some(c=>c==="vp") && _canCompleteByTrade(p,COST.dev)){
          _tradeToward(p,COST.dev);
          if(!_hoardOre && !_wrPhase1 && canPay(p,COST.dev)){ buyDev(); continue; }
        }
      }
      // ===== 積極ビルド: 交換すれば今すぐ建てられるなら建てる（資源を寝かせない） =====
      if(AGGRO_TRADE){
        // 都市化（2点・産出2倍。4:1込みでも最優先で完成させる）
        if(placements[p].settlements.size>0 && placements[p].cities.size<4 && _canCompleteByTrade(p,COST.city)){
          const ci=adv.find(x=>x.label.startsWith("都市化")&&x.target&&x.target.id!=null);
          if(ci){ _tradeToward(p,COST.city); if(canPay(p,COST.city)){ gameClickVertex(ci.target.id); continue; } }
        }
        // 開拓地（1点＋母体）
        const si=adv.find(x=>x.label.startsWith("開拓地")&&x.target&&x.target.id!=null);
        if(si && placements[p].settlements.size<5 && _canCompleteByTrade(p,COST.settlement)){
          _tradeToward(p,COST.settlement);
          if(canPay(p,COST.settlement)){ gameClickVertex(si.target.id); continue; }
        }
        // 手札が溢れそうで建設先が無い→道で拡張先を開く（バーストで捨てるより投資）
        // ただし BURST_ROAD_SMART: 「すぐ建設地が開く」道だけに限定する。
        // 自分で「温存推奨・都市化を遅らせる」とラベルした道まで建てるのは、
        // バースト回避が目的化した本末転倒（実測: この種が全バースト回避道の35.7%を占めていた）。
        if(!BURST_ROAD_OFF && !CONSERVE_ROADS && handTotal(p)>=5 && !si && placements[p].settlements.size<5){
          const ri=adv.find(x=>x.label.startsWith("道")&&x.target&&x.target.id!=null);
          const roadIsUseful = ri && ri.label.includes("すぐ建設地が開く");
          const allow = BURST_ROAD_SMART ? roadIsUseful : !!ri;
          if(allow && _canCompleteByTrade(p,COST.road)){ _tradeToward(p,COST.road);
            if(typeof BURST_ROAD_LOG!=="undefined" && BURST_ROAD_LOG) BURST_ROAD_LOG.count++;
            if(canPay(p,COST.road)){ gameClickEdge(ri.target.id); continue; } }
        }
      }
      // ===== 行き止まり脱出（拡張モード） =====
      // 都市化の母体(家)が無い/都市上限で、勝ちの残り手段が「新しい家」しかないのに
      // 木土が出ない場合、鉄麦をため込んでも詰む。鉄麦→木土羊麦へ逆変換して拡張する。
      const noUpgrade = placements[p].settlements.size===0 || placements[p].cities.size>=4;
      if(noUpgrade && vpOf(p)<10 && placements[p].settlements.size<5){
        // 建てられる頂点があるか（道の接続先）
        const B2=computeBest(undefined, p);
        let target=null;
        for(const vidS in B2.scores){ const vid=Number(vidS);
          if(GEO.edges.some(e=>(e.a===vid||e.b===vid)&&placements[p].roads.has(e.id))){ 
            if(!target||B2.scores[vid].score>B2.scores[target].score) target=vid; } }
        if(target!=null){
          if(_tradeToward(p, COST.settlement)){ gameClickVertex(target); continue; }
        } else {
          // 接続先が無い→道を1本伸ばして開拓の口を作る
          let bestE=null,bestSc=-1;
          for(const e of GEO.edges){
            if(ownerOf("roads",e.id)) continue;
            const conn=[e.a,e.b].some(v=>{const oc=occupantOf(v); if(oc&&oc.p===p)return true; if(oc)return false;
              return GEO.edges.some(e2=>e2.id!==e.id&&(e2.a===v||e2.b===v)&&placements[p].roads.has(e2.id));});
            if(!conn) continue;
            for(const v of [e.a,e.b]){ if(B2.scores[v]&&B2.scores[v].score>bestSc){bestSc=B2.scores[v].score;bestE=e.id;} }
          }
          if(bestE!=null && _tradeToward(p, COST.road)){ gameClickEdge(bestE); continue; }
        }
      }
      // 終了前に余りを鉄麦へ（※拡張モード中は温存するので上でcontinue済み。麦鉄どちらが足りないかで振り分ける）
      for(const r of ["sheep","wood","brick"]){
        while(game.hands[p][r]>=rateFor(p,r)+DUMP_MARGIN){
          const need=game.hands[p].wheat<2?"wheat":"ore";
          if(!_tradeBank(p,r,need)) break;
        }
      }
      // 能動的な余剰変換（ユーザーのプレイングを移植）: 都市化のために、余った鉄麦の一方を
      // もう一方へ計画的に変換する。実データで「麦22枚・鉄4枚」のような極端な偏りが放置され、
      // 都市が建たない問題を潰す。都市化予約(麦2鉄3)を確保した上で、余剰を不足側へ回す。
      if(typeof ACTIVE_CONVERT!=="undefined" && ACTIVE_CONVERT
         && placements[p].settlements.size>0 && placements[p].cities.size<4){
        let guard=0;
        while(guard++<6){
          const h=game.hands[p];
          const rate=r=>rateFor(p,r);
          // 都市化に必要なのは 麦2・鉄3。どちらがボトルネックか。
          const wheatNeed=Math.max(0,2-h.wheat), oreNeed=Math.max(0,3-h.ore);
          let did=false;
          // 鉄が足りず麦が交換分以上に余っている → 麦を鉄へ
          if(oreNeed>0 && h.wheat >= 2 + rate("wheat")){
            if(_tradeBank(p,"wheat","ore")) did=true;
          }
          // 麦が足りず鉄が交換分以上に余っている → 鉄を麦へ（鉄過多の配置向け）
          else if(wheatNeed>0 && h.ore >= 3 + rate("ore")){
            if(_tradeBank(p,"ore","wheat")) did=true;
          }
          if(!did) break;
        }
      }
      // バースト回避1: 溢れそうならカードを買って圧縮。ただし都市化に必要な鉄麦は死守する。
      if(AGGRO_TRADE && handTotal(p)>_dbtOf(p) && game.dev.deck.length
         && !(_holdPOf(p)>0 && _pCityByNextTurn(p)>=_holdPOf(p))){   // 都市が建つ見込みが高いならステイ
        const hasBase = placements[p].settlements.size>0 && placements[p].cities.size<4;
        const wReserve = hasBase?2:0, oReserve = hasBase?3:0;
        const canBuyNoRaid = (game.hands[p].wheat-wReserve>=COST.dev.wheat)
                            && (game.hands[p].ore-oReserve>=COST.dev.ore)
                            && (game.hands[p].sheep>=COST.dev.sheep);
        if(!_hoardOre && !_wrPhase1 && (typeof PROTECT_CITY_RESERVE!=="undefined" && PROTECT_CITY_RESERVE ? canBuyNoRaid : canPay(p,COST.dev))) buyDev();
      }
      // バースト回避2: それでも8枚以上なら、次の目標(都市)へ圧縮して7枚以下を目指す
      // ただし SMART_BURST: 「あと少しで建物になる手札」は、バーストを覚悟してでも温存する
      if(AGGRO_TRADE){
        let g2=0;
        while(handTotal(p)>_cmpOf(p) && g2++<COMPRESS_ITERS){
          if(_holdPOf(p)>0 && _pCityByNextTurn(p)>=_holdPOf(p)) break;   // 都市が建つ見込みが高いならステイ
          if(typeof SMART_BURST!=="undefined" && SMART_BURST && _worthHoldingThroughBurst(p)) break;
          let best=null;
          for(const r of RES5){ const reserve=(COST.city[r]||0); const spare=game.hands[p][r]-reserve;
            if(spare>=rateFor(p,r)){ if(!best||rateFor(p,r)<rateFor(p,best)) best=r; } }
          if(!best) break;
          if(typeof COMPRESS_LOG!=="undefined" && COMPRESS_LOG){
            const nCity=Math.max(0,2-game.hands[p].wheat)+Math.max(0,3-game.hands[p].ore);
            const nSet=Math.max(0,1-game.hands[p].wood)+Math.max(0,1-game.hands[p].brick)+Math.max(0,1-game.hands[p].sheep)+Math.max(0,1-game.hands[p].wheat);
            COMPRESS_LOG.events++;
            COMPRESS_LOG.burned += rateFor(p,best)-1;
            if(Math.min(nCity,nSet)<=2) COMPRESS_LOG.nearBuild++;
          }
          const need=game.hands[p].ore<3?"ore":(game.hands[p].wheat<2?"wheat":"ore");
          if(!_tradeBank(p,best,need)) break;
        }
      }
      return;
    }
    if(a.label.startsWith("都市化")) gameClickVertex(a.target.id);
    else if(a.label.startsWith("余り資源を交換して今すぐ都市化")){ if(_tryTradeForCity(p)&&a.target) gameClickVertex(a.target.id); else return; }
    else if(a.label.startsWith("余り資源を交換して今すぐ開拓地")){ if(_tryTradeForCost(p,COST.settlement)&&a.target) gameClickVertex(a.target.id); else return; }
    else if(a.label.startsWith("開拓地")) gameClickVertex(a.target.id);
    else if(a.label.startsWith("道")) gameClickEdge(a.target.id);
    else if(a.label.startsWith("交換して発展カード")){
      _tradeToward(p,COST.dev);
      if(!_hoardOre&&!_wrPhase1&&canPay(p,COST.dev))buyDev();else return;
    }
    else if(a.label.startsWith("発展カード")){ if(!_hoardOre && !_wrPhase1) buyDev(); }
    else if(a.label.includes("に交換")){ const _nr=a._needRes||"ore"; for(const r of ["sheep","wood","brick"]){ if(game.hands[p][r]>=rateFor(p,r)) { _tradeBank(p,r,_nr); break; } } }
    else return;
    if(game.phase!=="main") return; // 勝利や騎士で遷移したら抜ける
  }
  // 交換や連続建設で12アクション上限に達した場合も、完成済みの家を持ち越さない。
  if(game.phase==="main" && placements[p].settlements.size<5 && canPay(p,COST.settlement)){
    const si=computeAdvice().find(x=>x.can&&x.label.startsWith("開拓地")&&x.target&&x.target.id!=null);
    if(si) gameClickVertex(si.target.id);
  }
}
function _cleanupTurn(p){ // カードの置き残し・選択残しを処理してターン終了可能にする
  let g=0;
  while(game.freeRoads>0 && g++<4){
    const e=GEO.edges.find(e=>!ownerOf("roads",e.id) && [e.a,e.b].some(v=>{const oc=occupantOf(v); if(oc&&oc.p===p)return true; if(oc)return false; return GEO.edges.some(e2=>e2.id!==e.id&&(e2.a===v||e2.b===v)&&placements[p].roads.has(e2.id));}));
    if(!e) break;
    gameClickEdge(e.id);
  }
  game.freeRoads=0;
  if(game.ask){
    if(game.ask.type==="plenty"){
      let gg=0;
      while(game.ask && gg++<3){ const r=bankOf("ore")>0?"ore":RES5.find(x=>bankOf(x)>0); if(!r){game.ask=null;break;} resolvePlenty(r); }
    } else resolveMono("ore");
  }
}
// ===================== AIと対戦（選んだ席順があなた、残りがAI） =====================
let aiBusy=false;
let AI_SPEED=1;   // AIの1手あたりの待ち時間の倍率（0=待ちなし）
function isAI(p){ return game && game.ai && game.ai.has(p); }
// 1アクションだけ進めて、画面を更新し、必要なら少し待って次へ。人間の番になったら止まる。
// 一括自己対戦では逆算(重い)をオフにして高速化。対戦・最善手表示ではオン。
let USE_BACKSOLVE=true;

// 残りダイス期待値モード（この手を打つと残り試合でどれだけ資源が増えるかで評価）
let USE_EV=false;
// --- パネル描画 ---
function updateGamePanel(){
  if(!game) return;
  const st=document.getElementById("gameStatus");
  const p=cur();
  const pn=`<b style="color:${PCOLORS[p-1]}">P${p}</b>`;
  let phase="";
  if(game.phase==="setup"){ const su=game.setup; const sp=su.queue[su.step];
    phase=`初期配置 ${su.step+1}/${su.queue.length}：<b style="color:${PCOLORS[sp-1]}">P${sp}</b> が${su.phase==="settle"?"開拓地":"道"}を置く`; }
  else if(game.phase==="roll") phase=`${pn} の番：サイコロを振る（騎士も使えます）`;
  else if(game.phase==="discard"){ const d=game.discardQueue[0]; phase=`出目7！ <b style="color:${PCOLORS[d.p-1]}">P${d.p}</b> はあと${d.need}枚捨てる（下の手札をクリック）`; }
  else if(game.phase==="robber"){
    const ra=robberAdvice();
    phase=`${pn}：盗賊を動かすタイルをクリック`;
    if(ra) phase+=`<br><span class="small">おすすめ: トップ P${ra.top} の ${RES_JP[ra.res]}${ra.num}（★印）を止める。自分が巻き込まれても相手の損が大きければ自止めOK</span>`;
  }
  else if(game.phase==="steal") phase=`${pn}：奪う相手 → `+game.stealCands.map(c=>`<button class="btn" style="padding:4px 10px" onclick="stealFrom(${c})">P${c}</button>`).join(" ");
  else if(game.phase==="main") phase=`${pn} の番（出目${game.dice}）：建設・交易・カード → ターン終了`;
  else if(game.phase==="over") phase=`🏆 対局終了`;
  st.innerHTML=phase + (game.lr.holder?`　<span class="small">最長交易路:P${game.lr.holder}(${game.lr.len})</span>`:"")
                     + (game.la.holder?`　<span class="small">最大騎士力:P${game.la.holder}(${game.la.count})</span>`:"");
  const ask=document.getElementById("gameAsk");
  if(game.ask){
    const fn = game.ask.type==="plenty" ? "resolvePlenty" : "resolveMono";
    const label = game.ask.type==="plenty" ? `もらう資源（あと${game.ask.picks}）` : "独占する資源";
    ask.innerHTML = `<span class="small">${label}: </span>`+RES5.map(r=>`<button class="btn" style="padding:4px 10px" onclick="${fn}('${r}')">${RES_JP[r]}</button>`).join(" ");
  } else ask.innerHTML="";
  // 最善手の提案（mainフェーズのみ）＋逆算プラン
  const ab=document.getElementById("adviceBox");
  if(game.phase==="main"){
    const advList=computeAdvice();
    // 上位5件を表示。ただし「いま実際に建つ手」(都市化・開拓地・交換して今すぐ)は
    // 順位に関係なく必ず表示する（上位3件で切られて消えるのを防ぐ）。
    const _isBuild = a => a.can && (a.label.startsWith("都市化") || a.label.startsWith("開拓地")
                                    || a.label.startsWith("余り資源を交換して今すぐ"));
    const adv=[];
    for(const a of advList){ if(adv.length<5) adv.push(a); }
    for(const a of advList){ if(_isBuild(a) && !adv.includes(a)) adv.push(a); }
    const pl=advList._plan;
    const planLine = pl
      ? `<div style="margin-bottom:5px"><b>🎯 目標プラン:</b> ${pl.label}${pl.oreShort?' <span style="color:var(--brick)">（鉄不足→木土寄せ）</span>':''}</div>`
      : '';
    ab.innerHTML = '<div style="border:1px solid var(--line);border-radius:8px;padding:8px 10px">'
      + planLine
      + '<b>💡 次の一手の候補</b> <span class="hint" style="display:inline">（10点への最短プランから逆算）</span><br>'
      + adv.map((a,i)=>{
          const mark = a.can ? "" : `<span style="opacity:.55">（資源不足: ${a.cost}）</span>`;
          return `<div style="margin-top:4px;${a.can?'':'opacity:.6'}">${i+1}. ${a.label} ${mark}</div>`;
        }).join("")
      + '</div>';
  } else ab.innerHTML="";
  const ht=document.getElementById("handsTable");
  let html='<table style="width:100%; border-collapse:collapse">';
  html+='<tr><th></th>'+RES5.map(r=>`<th style="padding:2px 4px">${RES_JP[r]}</th>`).join("")+'<th>計</th><th>手札発展</th><th>使用済</th><th>VP</th></tr>';
  for(const q of game.order){
    const cells=RES5.map(r=>`<td style="text-align:center;padding:3px 4px;cursor:pointer" data-p="${q}" data-r="${r}" class="handCell">${game.hands[q][r]}</td>`).join("");
    const devN=Object.values(game.dev.hands[q]).reduce((a,b)=>a+b,0);
    // 使用済み発展カード（全プレイヤー見える）: 騎士はarmy、その他はplayed
    const pl=game.dev.played[q]||{};
    const usedParts=[];
    if(game.army[q]>0) usedParts.push(`騎士${game.army[q]}`);
    if(pl.roads>0) usedParts.push(`街道${pl.roads}`);
    if(pl.plenty>0) usedParts.push(`収穫${pl.plenty}`);
    if(pl.mono>0) usedParts.push(`独占${pl.mono}`);
    const usedStr=usedParts.length?usedParts.join("・"):"−";
    const mark=(q===p&&game.phase!=="setup") ? "▶" : "";
    html+=`<tr style="border-top:1px solid var(--line); ${q===p?'background:rgba(230,189,74,.08)':''}">
      <td style="padding:3px 4px"><b style="color:${PCOLORS[q-1]}">${mark}P${q}</b></td>${cells}
      <td style="text-align:center">${handTotal(q)}</td>
      <td style="text-align:center">${devN}</td>
      <td style="text-align:center; font-size:11px">${usedStr}</td>
      <td style="text-align:center"><b>${vpOf(q)}</b></td></tr>`;
  }
  html+='</table>';
  const mine=game.dev.hands[p];
  const devDetail=Object.entries(mine).filter(([,n])=>n>0).map(([c,n])=>`${DEV_JP[c]}×${n}`).join("・");
  html+=`<div class="hint" style="margin-top:6px">あなた(P${p})の手札の発展カード: ${devDetail||"なし"}　残り山札:${game.dev.deck.length}</div>`;
  ht.innerHTML=html;
  ht.querySelectorAll(".handCell").forEach(td=>{
    const q=Number(td.dataset.p), r=td.dataset.r;
    td.onclick=()=>{
      if(game.phase==="discard"){
        const d=game.discardQueue[0];
        if(q!==d.p){ toast(`いまは P${d.p} が捨てる番`); return; }
        if(game.hands[q][r]<=0) return;
        game.hands[q][r]--; d.need--;
        if(d.need<=0){ game.discardQueue.shift();
          if(!game.discardQueue.length){ game.phase="robber"; toast("盗賊を動かすタイルをクリック"); } }
        updateGamePanel(); aiMaybeGo(); return;
      }
      if(document.getElementById("handEdit").checked){ if(bankOf(r)>0){ game.hands[q][r]++; updateGamePanel(); } }
    };
    td.oncontextmenu=(ev)=>{ ev.preventDefault();
      if(document.getElementById("handEdit").checked && game.hands[q][r]>0){ game.hands[q][r]--; updateGamePanel(); } };
  });
  document.getElementById("rollBtn").disabled = game.phase!=="roll";
  document.getElementById("rollFixBtn").disabled = game.phase!=="roll";
  document.getElementById("buyDev").disabled = game.phase!=="main";
  document.getElementById("playKnight").disabled = !(game.phase==="main"||game.phase==="roll") || !canPlay("knight");
  document.getElementById("playRoads").disabled = game.phase!=="main" || !canPlay("roads");
  document.getElementById("playPlenty").disabled = game.phase!=="main" || !canPlay("plenty");
  document.getElementById("playMono").disabled = game.phase!=="main" || !canPlay("mono");
  document.getElementById("tradeBtn").disabled = game.phase!=="main";
  document.getElementById("endTurn").disabled = (game.phase!=="main");
}

