  for(const eid of placements[p].roads){ const e=GEO.edges[eid]; if(e){ myV.add(e.a); myV.add(e.b); } }
  if(extraEdge!=null){ const e=GEO.edges[extraEdge]; if(e){ myV.add(e.a); myV.add(e.b); } }
