function _tlProb(p, need, T, hand2, extraV){
  const tok=game._msTok||(game._msTok=Math.random().toString(36).slice(2));
  const hh=hand2||game.hands[p];
  const k="tl_"+tok+"_"+p+"_"+(game.rollCount||0)+"_"+JSON.stringify(need)+"_"+hh.wood+"_"+hh.brick+"_"+hh.sheep+"_"+hh.wheat+"_"+hh.ore+"_"+(extraV==null?"":extraV)+"_"+T;
  if(Object.keys(_msCache).length>400) _msCache={};
  let v=_msCache[k];
  if(v==null){ v=_raceProbFor(p,[need],T,hand2,extraV); _msCache[k]=v; }
  return v;
}
// 行動→未来脅威度の採点。都市化/開拓地/道/カード/温存を同じ通貨（脅威度）で比較する。
function _vPips(v){
  let pip=0, ow=0, wb=0;
  for(const hid of GEO.vertex_hexes[String(v)]||[]){ const b=board[hid]; if(b&&b.resource!=="desert"&&b.number){
    const pv=pipOf(b.number); pip+=pv;
    if(b.resource==="ore"||b.resource==="wheat") ow+=pv;
    if(b.resource==="wood"||b.resource==="brick") wb+=pv; } }
  return {pip,ow,wb};
}
function _tlGovernor(p, list){
  if(!game || game.phase==="setup") return;
  const core=[]; let passItem=null;
  for(const a of list){
    if(a.label.startsWith("ターン終了")) passItem=a;
    else if(a.label.startsWith("都市化（")) core.push({a,kind:"city"});
    else if(a.label.startsWith("開拓地")) core.push({a,kind:"settle"});
    else if(a.label.startsWith("道を伸ばす")) core.push({a,kind:"road"});
    else if(a.label.startsWith("発展カード")) core.push({a,kind:"dev"});
  }
  if(!core.some(c=>c.a.can)) return;
  const h=game.hands[p];
  const learned=(typeof TL_LEARNED!=="undefined" && TL_LEARNED);
  const setPips=[...placements[p].settlements].map(v=>({v, ..._vPips(v)})).sort((x,y)=>y.pip-x.pip);
  const reach=_tlReachable(p,null);
  const cityCap=placements[p].cities.size<4, setCap=placements[p].settlements.size<5;
  // 建物1個ぶんの脅威度増分（モードで式が変わる）
  function gCity(sp){ if(!sp) return 0;
    return learned
      ? VAL_W.vp + VAL_W.cities - VAL_W.settlements + VAL_W.prodPip*sp.pip + VAL_W.ow*sp.ow + VAL_W.wb*sp.wb
      : 1.5 + 0.1*sp.pip; }
  function gSettle(pip, ow, wb){
    return learned
      ? VAL_W.vp + VAL_W.settlements + VAL_W.prodPip*pip + VAL_W.ow*(ow||0) + VAL_W.wb*(wb||0) - VAL_W.reach
      : 1.0 + 0.1*pip; }
  function futureTerm(hand2, extraV, usedVid, addedEdge){
    let term=0;
    const remain=setPips.filter(sp=>sp.v!==usedVid);
    if(cityCap && remain.length>0){
      const pc=_tlProb(p,{wheat:2,ore:3},TL_HORIZON,hand2,extraV);
      if(pc!=null) term += pc*gCity(remain[0]);
    }
    if(setCap){
      const r2 = addedEdge!=null ? _tlReachable(p,addedEdge) : reach;
      if(r2.count>0){
        const ps=_tlProb(p,{wood:1,brick:1,sheep:1,wheat:1},TL_HORIZON,hand2,extraV);
        if(ps!=null) term += ps*gSettle(r2.bestPip, r2.bestPip*0.4, r2.bestPip*0.4);
      }
    }
    return term;
  }
  const Vpass=futureTerm(null,null,null,null);
  for(const c of core){
    if(!c.a.can) continue;
    let cost=null, d0=0, extraV=null, usedVid=null, addedEdge=null;
    if(c.kind==="city"){ cost=COST.city; const vid=c.a.target&&c.a.target.id; extraV=vid; usedVid=vid;
      const sp=setPips.find(x=>x.v===vid); d0=gCity(sp||{pip:0,ow:0,wb:0}); }
    else if(c.kind==="settle"){ cost=COST.settlement; const vid=c.a.target&&c.a.target.id; extraV=vid;
      const vv=_vPips(vid); d0=gSettle(vv.pip, vv.ow, vv.wb); }
    else if(c.kind==="road"){ cost=COST.road; addedEdge=(c.a.target&&c.a.target.id!=null)?c.a.target.id:null;
      if(learned){ const r2=addedEdge!=null?_tlReachable(p,addedEdge):reach;
        d0=VAL_W.roads + VAL_W.reach*(r2.count-reach.count) + VAL_W.reachPip*(r2.bestPip-reach.bestPip); }
      else d0=0; }
    else if(c.kind==="dev"){ cost=COST.dev; d0=learned?VAL_W.dev:0.6; }
    if(!cost) continue;
    const after={wood:h.wood-(cost.wood||0), brick:h.brick-(cost.brick||0), sheep:h.sheep-(cost.sheep||0), wheat:h.wheat-(cost.wheat||0), ore:h.ore-(cost.ore||0)};
    if(after.wood<0||after.brick<0||after.sheep<0||after.wheat<0||after.ore<0) continue;
    const Va=d0+futureTerm(after,extraV,usedVid,addedEdge);
    c.a.score = 0.5 + TL_SCALE*(Va - Vpass);
  }
  if(passItem) passItem.score=0.5;
}
function computeAdvice(){
  const p=cur(); const list=[];
  const hasCity=(placements[p].cities&&placements[p].cities.size>0);

  // === 思考2: 鉄に満足に触れていない → 麦を下げ、木土を上げる（家路線に寄せる） ===
  const oreShort = oreAccess(p) < 0.18;
  const RF = oreShort
    ? {ore:1.9, wheat:1.1, wood:1.4, brick:1.4, sheep:0.85}   // 鉄不足時: 麦↓ 木土↑
    : BEST_W.resFactor;
  // 高速プレイアウト: 同一ターン内でcomputeBestの結果を使い回す（本編行動の頂点評価は毎手ほぼ不変）
  let B;
  if(typeof FAST_PLAYOUT!=="undefined" && FAST_PLAYOUT && game && game._bestCache && game._bestCacheKey===p+"_"+oreShort){
    B=game._bestCache;
  }else{
    B=computeBest(RF, p);
    if(typeof FAST_PLAYOUT!=="undefined" && FAST_PLAYOUT && game){ game._bestCache=B; game._bestCacheKey=p+"_"+oreShort; }
  }

  // === 逆算: いま目指すべき最短プランを決める（重いので一括自己対戦ではスキップ可） ===
  const plan = (typeof USE_BACKSOLVE==="undefined" || USE_BACKSOLVE) ? backSolve(p) : null;
  const goal = plan ? plan.plan : null;
  const planLabel = goal ? planName(goal) : "";
  const dynSupport=plan&&plan.dynamic&&plan.dynamic.support;
  const citySupport=dynSupport?dynSupport.city:(goal&&goal.C>(placements[p].cities?placements[p].cities.size:0)?1:0);
  const settleSupport=dynSupport?dynSupport.settle:(goal&&goal.C+goal.S>placements[p].settlements.size+(placements[p].cities?placements[p].cities.size:0)?1:0);
  const vpSupport=dynSupport?dynSupport.vp:(goal&&goal.V>game.dev.hands[p].vp?1:0);
  const armySupport=dynSupport?dynSupport.LA:(goal&&goal.LA&&game.la.holder!==p?1:0);
  const roadSupport=dynSupport?dynSupport.LR:(goal&&goal.LR&&game.lr.holder!==p?1:0);
  const wantsCities = goal ? (dynSupport?citySupport>=.25:citySupport>0) : true;
  const wantsSettles = goal ? (dynSupport?settleSupport>=.25:settleSupport>0) : true;
  // ワンチャン狙いv2: 明確な最下位なら、都市化より開拓地(資源効率が良い)を優先して量で追いつく
  let _isDesperate2=false;
  if(typeof GAMBIT2!=="undefined" && GAMBIT2){
    const vps=[1,2,3,4].map(q=>vpOf(q));
    const myVp=vps[p-1];
    const maxOther=Math.max(...vps.filter((v,i)=>i+1!==p));
    _isDesperate2 = myVp<=Math.min(...vps) && maxOther-myVp>=3;
  }
  const wantsVP = goal ? (dynSupport?vpSupport>=.25:vpSupport>0) : false;
  const wantsArmy = goal ? (dynSupport?armySupport>=.25:armySupport>0) : false;
  const wantsRoad = goal ? (dynSupport?roadSupport>=.25:roadSupport>0) : false;

  // === 思考1: できるだけ早く大きな資源上昇 ===
  const exp0=production(p); const prodNow=Object.values(exp0).reduce((a,b)=>a+b,0);

  // --- 都市化（本命。産出2倍・鉄麦戦略の核。プランが都市を欲すれば更に加点） ---
  let bc=null;
  for(const vid of placements[p].settlements){
    let pip=0, ow=0;
    for(const hid of GEO.vertex_hexes[String(vid)]){ const b=board[hid]; if(b&&b.number){ const pv=pipOf(b.number); pip+=pv; if(b.resource==="ore"||b.resource==="wheat") ow+=pv; } }
    const v=pip+ow*0.6;
    if(!bc||v>bc.v) bc={vid,v};
  }
  if(bc){
    let cityScore = ((typeof USE_EV!=="undefined"&&USE_EV)
      ? actionValue("city", p, {vid:bc.vid}) + (dynSupport?3*citySupport:(wantsCities?3:0))
      : bc.v*1.5+8+(dynSupport?3*citySupport:(wantsCities?3:0))) * (_isDesperate2?0.6:1) * W_CITY;
    // 鉄希少センサー（ユーザーの判断を移植・修正版）:
    // 鉄が希少な盤面では都市化をやや後押し（貴重な鉄拠点に集中）。
    // ただし都市化は「鉄が豊富でも、まず鉄拠点は都市化する」ので、豊富時も下げない。
    if(typeof ORE_SENSE!=="undefined" && ORE_SENSE){ cityScore *= (1 + ORE_SENSE_W * boardOreScarcity() * 0.5); }
    list.push({score:cityScore, can:(canPay(p,COST.city)&&placements[p].cities.size<4), target:{type:"vertex",id:bc.vid},
      label:`都市化（産出2倍・最優先）`, cost:"小麦2+鉱石3"});
  }

  // --- 交換で今すぐ都市化 ---
  if(bc && !canPay(p,COST.city) && _canCompleteByTrade(p,COST.city)){
    list.push({score:bc.v*1.4+7, can:(placements[p].cities.size<4), target:{type:"vertex",id:bc.vid},
      label:"余り資源を交換して今すぐ都市化（1:2の不利でも可）", cost:""});
  }

  // --- 開拓地（プランが家を欲すれば加点。鉄不足なら家路線が本命化） ---
  // 港ボーナス: 道で港1マス以内に届いている場所なら、家の候補として優先する
  // （PORT_RUSHの中盤積極追跡とは別物。既に伸ばした道を無駄にしないための接続）
  const _pv = (()=>{ const s=new Set(); for(const eid in ports){ const e=GEO.edges[+eid]; s.add(e.a); s.add(e.b); } return s; })();
  let bs=null;
  for(const vidS in B.scores){ const vid=Number(vidS);
    const touch=GEO.edges.some(e=>(e.a===vid||e.b===vid)&&placements[p].roads.has(e.id));
    if(!touch) continue;
    const s2=B.scores[vid].score + (_pv.has(vid)?5:0);   // 港確保ボーナス（無料の道投資を活かす程度）
    if(!bs||s2>bs.score) bs={vid,score:s2};
  }
  if(bs){
    let settleScore = ((typeof USE_EV!=="undefined"&&USE_EV)
      ? actionValue("settle", p, {vid:bs.vid}) + (oreShort?2.5:(dynSupport?2.5*settleSupport:(wantsSettles?2.5:0)))
      : bs.score*0.9+2+(oreShort?2.5:(dynSupport?2.5*settleSupport:(wantsSettles?2.5:0)))) * (_isDesperate2?1.5:1) * W_SETTLE;
    // 鉄希少センサー: 鉄が豊富(希少度低)な盤面では、都市化した上でさらに拡張を後押しする。
    // （ユーザー指摘: 鉄が豊富でもまず鉄拠点は都市化し、その後で拡張に回る）
    if(typeof ORE_SENSE!=="undefined" && ORE_SENSE){ settleScore *= (1 + ORE_SENSE_W * (1 - boardOreScarcity()) * 0.5); }
    list.push({score:settleScore, can:(canPay(p,COST.settlement)&&placements[p].settlements.size<5), target:{type:"vertex",id:bs.vid},
      label:"開拓地を建てる（産出の母体を増やす）", cost:"木+レンガ+羊+小麦"});
  }
  // --- 交換で今すぐ開拓地（都市化と同じ発想。今まで抜けていた） ---
  if(bs && !canPay(p,COST.settlement) && placements[p].settlements.size<5 && _canCompleteByTrade(p,COST.settlement)){
    list.push({score:bs.score*0.9*1.4+6, can:true, target:{type:"vertex",id:bs.vid},
      label:"余り資源を交換して今すぐ開拓地（1:2の不利でも可）", cost:""});
  }

  // --- 道（思考3: むやみに伸ばさない。プランで道賞を狙う時か、すぐ家が開く時だけ） ---
  // 既に「道でつながっていて家が建てられる空き頂点」の集合。これがあるなら道は不要。
  const reachNow=new Set();
  for(const vidS in B.scores){ const vid=Number(vidS);
    if(GEO.edges.some(e=>(e.a===vid||e.b===vid)&&placements[p].roads.has(e.id))) reachNow.add(vid);
  }
  let br=null;
  const _openQualityBar = B.mn + (B.mx-B.mn)*0.5;   // 上位半分ラインより下の候補地は「低品質」
  for(const e of GEO.edges){
    if(ownerOf("roads",e.id)) continue;
    const conn=[e.a,e.b].some(v=>{const oc=occupantOf(v); if(oc&&oc.p===p)return true; if(oc)return false;
      return GEO.edges.some(e2=>e2.id!==e.id&&(e2.a===v||e2.b===v)&&placements[p].roads.has(e2.id));});
    if(!conn) continue;
    // 既に家の目標数(floor)を満たしているなら、"質の低い"候補地を開けるだけの道は評価しない（質の高い候補地は残す）
    const _floorMet = placements[p].settlements.size>=settleFloorFor(p) && !wantsSettles;
    let sc=0, opens=false;
    // 2手先（隣の隣）の建設地を道の価値に含めてよいのは、ユーザーのルール:
    // 「木と土が潤沢で、かつ2手先に伸ばした先が強い時」だけ。それ以外は無駄道になりやすい。
    const _woodBrickRich = (game.hands[p].wood + game.hands[p].brick) >= (typeof TWO_HOP_WB!=="undefined"?TWO_HOP_WB:4);
    const _allowTwoHop = !(typeof STRICT_ROAD!=="undefined" && STRICT_ROAD) || _woodBrickRich;
    const _twoHopBar = (typeof TWO_HOP_BAR!=="undefined"?TWO_HOP_BAR:0);
    for(const v of [e.a,e.b]){
      // opens = この道で「新たに」到達できる建設候補（既に到達済みの頂点はカウントしない）
      const _lowQuality = SUPPRESS_SPEC_ROAD && _floorMet && B.scores[v] && B.scores[v].score<_openQualityBar;
      if(!_lowQuality && B.scores[v] && !reachNow.has(v)){ sc=Math.max(sc,B.scores[v].score); opens=true; }
      if(_pv && _pv.has(v) && B.scores[v]){ sc+=3; }   // 道の先が港（達人流）
      // 2手先の評価: STRICT_ROAD時は「木土潤沢＆2手先が強い(閾値超え)」の両方が必要
      if(!_lowQuality && _allowTwoHop) for(const n of GEO.vertex_neighbors[v]) if(B.scores[n] && !reachNow.has(n)){
        if(!(typeof STRICT_ROAD!=="undefined" && STRICT_ROAD) || B.scores[n].score >= _twoHopBar){
          sc=Math.max(sc,B.scores[n].score*0.6);
        }
      }
    }
    if(opens) sc+=2;
    if(!br||sc>br.score) br={eid:e.id,score:sc,opens};
  }
  // [2026-08-19] 対象席では「目的地までの道のり」で選び直す（目的地に港を含む）
  if(ROAD_PATH_SEATS && ROAD_PATH_SEATS.has(p)){
    const rp=_roadPathTarget(p, B);
    if(rp) br={eid:rp.eid, score:rp.eff, opens:(rp.dist===1)};
  }
  // 道賞支持が十分高く、街道建設1枚で届く範囲なら「建地へ向かう道」と別軸で
  // 一筆書きの先頭を選ぶ。無料1本目の後も再計算されるため、2本目まで連動する。
  const dynCfg=DYNAMIC_ROUTE_CFG&&DYNAMIC_ROUTE_CFG[p];
  if(dynSupport&&roadSupport>=((dynCfg&&dynCfg.roadTargetMin)||.28)&&game.lr.holder!==p){
    const target=game.lr.holder?(game.lr.len+1):5,gap=Math.max(1,target-longestRoadOf(p));
    let lp=plan&&plan.dynamic&&plan.dynamic.races&&plan.dynamic.races.LR&&plan.dynamic.races.LR.mine&&plan.dynamic.races.LR.mine.extension;
    if(!lp&&gap<=2)try{lp=_rwBestExtension(p,2,target);}catch(e){}
    if(lp&&lp.edges&&lp.edges.length){const old=br;br={eid:lp.edges[0],score:(old?old.score:0)+6*roadSupport,
      opens:old&&old.eid===lp.edges[0]?old.opens:false,purpose:"dynamic-longest-road"};}
  }
  if(br){
    let roadScore;
    if(typeof USE_EV!=="undefined"&&USE_EV){
      let openVid=null, openBest=-1;
      const e=GEO.edges[br.eid];
      for(const v of [e.a,e.b]){ for(const n of GEO.vertex_neighbors[v]){ if(B.scores[n] && !reachNow.has(n) && B.scores[n].score>openBest){ openBest=B.scores[n].score; openVid=n; } } }
      roadScore = actionValue("road", p, {opensVid: br.opens?openVid:null, forLongestRoad: wantsRoad}) + (dynSupport?2.5*roadSupport:(wantsRoad?2.5:0));
    }else{
      roadScore = (br.score*0.35 + (br.opens?1.5:0) + (dynSupport?2.5*roadSupport:(wantsRoad?2.5:0))) * W_ROAD;
    }
    // 既に建設可能な空き頂点があるのに道を引くのは無駄（道賞プランを除く）→ 大幅減点
    if(reachNow.size>0 && !wantsRoad) roadScore -= 6;
    // ユーザー調整: 「開拓地が即開く道」でも「道賞プラン」でもない道は、資源が余っていても建てず温存する
    if(CONSERVE_ROADS && !br.opens && !wantsRoad) roadScore = -50;
    // ユーザー調整2: 序盤は「初期配置の道＋1本(その1本で建て地が相当良くなる場合)」以外、道賞狙いでも道を伸ばすと-評価
    if(CONSERVE_ROADS){
      const _bvp = placements[p].settlements.size + 2*(placements[p].cities?placements[p].cities.size:0);
      if(_bvp < EARLY_ROAD_BVP){
        const _span = Math.max(0.001, B.mx - B.mn);
        const _bigImprove = br.opens && ((br.score - B.mn)/_span >= EARLY_ROAD_QUALITY);   // その1本で相当良い建て地が開く
        const _firstExtraRoad = placements[p].roads.size <= 2;                              // 初期配置の2本＋この1本まで
        if(!(_bigImprove && _firstExtraRoad)) roadScore = -50;                              // 例外以外は序盤の道は-評価
      }
    }
    list.push({score:roadScore, can:((canPay(p,COST.road)||game.freeRoads>0)&&placements[p].roads.size<15), target:{type:"edge",id:br.eid},
      label: br.opens ? "道を伸ばす（すぐ建設地が開く）" : (wantsRoad?"道を伸ばす（道賞プラン）":"道を伸ばす（※温存推奨・都市化を遅らせる）"), cost:"木+レンガ"});
  }

  // --- 発展カード（初都市まで引かない。プランがVP/騎士賞を欲する or 山札濃縮で解禁） ---
  if(game.dev.deck.length){
    let devScore, devNote="";
    if(typeof USE_EV!=="undefined"&&USE_EV){
      // EVモード: カードの価値は「残りダイスが少ないほど相対的に高い」で自然に決まる
      devScore = actionValue("dev", p, {});
      // ただし初都市前に引くと産出エンジンが立たない→序盤かつ都市なしは抑制
      if(!hasCity && oreWheatPips(p)>2) { devScore*=0.15; devNote="（初都市までは控える）"; }
      else if(wantsVP||wantsArmy) devNote=wantsArmy?"（騎士賞プラン）":"（VPカードプラン）";
    }else{
      if(!hasCity){
        if(oreWheatPips(p)<=2){ devScore=5.5; devNote="（鉄麦が絶望的なので例外的に）"; }
        else { devScore=0.3; devNote="（初都市までは引かない）"; }
      }else{
        devScore=3;   // 建設優先（カードは資源が余る時だけ）
        const d=game.dev.deck;
        const good=d.filter(c=>c==="vp"||c==="mono").length/d.length;
        if(good>=0.35){ devScore=6; devNote="（山札に当たり濃縮）"; }
        if(wantsVP||wantsArmy){ devScore=Math.max(devScore,7); devNote=wantsArmy?"（騎士賞プラン）":"（VPカードプラン）"; }
        // カードエンジン: 都市が育った後は、鉄麦羊の余りをカードに変えて騎士賞・VPを取りに行く
        if(_ce(p) && placements[p].cities.size>=CARD_ENGINE_CITIES){
          devScore=Math.max(devScore, CARD_ENGINE_SCORE);
          devNote="（カードエンジン: 騎士賞・VP狙い）";
        }
      }
    }
    list.push({score:devScore, can:canPay(p,COST.dev), target:null, label:"発展カードを買う"+devNote, cost:"羊+小麦+鉱石"});
    if(_prizeTradeDevEligible(p)){
      list.push({score:devScore, can:true, target:null,
        label:"交換して発展カードを買う（賞レース）"+devNote, cost:"交換＋羊+小麦+鉱石"});
    }
  }

  // --- 余り資源を鉄麦に（バースト対策・鉄不足なら特に） ---
  const surplus=["sheep","wood","brick"].filter(r=>game.hands[p][r]>=rateFor(p,r));
  if(surplus.length && !canPay(p,COST.city)){
    // 鉄と麦のどちらが本当に不足しているかを見て、そちらへ交換する（常に鉄へ、は誤り）
    const needRes = game.hands[p].wheat<2 ? "wheat" : "ore";
    list.push({score:2.5, can:true, target:null,
      label:`余りの${surplus.map(r=>RES_JP[r]).join("・")}を${RES_JP[needRes]}に交換して終了（バースト対策）`, cost:"", _needRes:needRes});
  }

  // --- 思考3: 資源温存。今できる建設が「プランに沿わない小さな手」しかないなら、貯めて待つ ---
  list.push({score:0.5, can:true, target:null, label:"ターン終了（次の大きな一手へ資源を温存）", cost:""});

  if(typeof MILESTONE!=="undefined" && MILESTONE){ try{ _msGovernor(p, list); }catch(e){} }
  if(typeof THREAT_LOOKAHEAD!=="undefined" && THREAT_LOOKAHEAD){ try{ _tlGovernor(p, list); }catch(e){} }
  list.sort((a,b)=> (b.can===a.can ? b.score-a.score : (b.can?1:0)-(a.can?1:0)));
  // 逆算プランを先頭メタ情報として付ける（表示用）
  list._plan = goal ? {label:planLabel, turns: plan.turns, oreShort,
    portfolio:plan.portfolio||null,support:dynSupport||null} : null;
  return list;
}
// プラン名の文字列化
function planName(g){
  const parts=[];
  if(g.C) parts.push(`都市${g.C}`);
  if(g.S) parts.push(`家${g.S}`);
  if(g.V) parts.push(`VP${g.V}`);
  if(g.LR) parts.push("道賞");
  if(g.LA) parts.push("騎士賞");
  return parts.join("+");
}

// 盗賊のおすすめ: トップ(自分以外の最高VP)の鉄・麦タイルで最もpipが高い場所
// ===================== 逆算エンジン（10点への最短プラン） =====================
// プレイヤーpの「1ターンあたりの資源産出期待値」を資源別に返す。
// 家=pip/36枚, 都市=2倍。盗賊で止まっているタイルは除外。
function production(p){
  const exp={wood:0,brick:0,sheep:0,wheat:0,ore:0};
  const all=[["settlements",1],["cities",2]];
  for(const [kind,mult] of all){
    const set=placements[p][kind]; if(!set) continue;
    for(const vid of set){
      for(const hid of GEO.vertex_hexes[String(vid)]){
        const b=board[hid];
        if(!b||!b.number||!b.resource||b.resource==="desert") continue;
        if(hid===game.robber) continue;
        exp[b.resource]+= (pipOf(b.number)/36)*mult;   // pip/36 = 1ダイスでその数字が出る確率×36分の…（pip=出やすさ）
      }
    }
  }
  return exp;
}
// 鉄に「満足に触れているか」= 鉄の産出期待がしきい値以上か
function oreAccess(p){ return production(p).ore; }
// 盤面の鉄希少度（ユーザーの判断を移植）:
// 良い鉄(pip4以上)の総pipが少ないほど「鉄が希少」= 集中(都市全振り)が正解の盤面。
// 実データ8局から: 鉄の良pip合計 < 9 で人間は集中、>= 9 で拡張する傾向。
let _oreScarcityCache=null, _oreScarcityBoard=null;
function boardOreScarcity(){
  // 盤面が変わっていなければキャッシュ
  if(_oreScarcityCache!==null && _oreScarcityBoard===board) return _oreScarcityCache;
  let goodOrePip=0, totalOrePip=0;
  for(const hid in board){
    const b=board[hid];
    if(b && b.resource==="ore" && b.number){
      const pv=pipOf(b.number);
      totalOrePip+=pv;
      if(pv>=4) goodOrePip+=pv;   // 良い鉄(6か8か、それに近い数字)
    }
  }
  // scarcity: 0(豊富)〜1(希少)。良い鉄pipが少ないほど1に近い。
  // 経験境界: goodOrePip 9で中間。0→scarcity1, 14+→scarcity0
  const scarcity = Math.max(0, Math.min(1, (12 - goodOrePip) / 12));
  _oreScarcityCache=scarcity; _oreScarcityBoard=board;
  return scarcity;
}

// ===================== 残りダイス期待値エンジン =====================
// 試合はおよそ70ダイスで決着する、という前提。残りダイス数を返す。
const GAME_DICE=70;
function remainingDice(){
  const used=(game&&game.diceCount)||0;
  return Math.max(6, GAME_DICE-used);   // 70超過後も建物は少しは価値あり→最低6ダイス相当
}
// ある頂点に「開拓地」を建てたときの、1ダイスあたり資源増分（種類を問わず合計pip/36）
function settleGainPerDie(vid){
  let g=0;
  for(const hid of GEO.vertex_hexes[String(vid)]){
    const b=board[hid]; if(!b||!b.number||!b.resource||b.resource==="desert") continue;
    if(hid===game.robber) continue;
    const w = EV_PARAMS.empirical ? (EMPIRICAL_W[b.resource]||1)/1.15 : 1;  // 消費量重み(平均≒1に正規化)
    g+=(pipOf(b.number)/36)*w;
  }
  return g;
}
// ある頂点を「都市化」したときの、1ダイスあたり資源増分（=元の産出がもう1回ぶん増える）
function cityGainPerDie(vid){ return settleGainPerDie(vid); }  // 2倍化=+1倍ぶん

// 資源を「勝ちへの近さ」に橋渡しする係数。
// 産出資源1枚の価値の目安。建物は資源を生むが、最終的に欲しいのは勝利点。
// ここでは「資源N枚 ≒ 建設1回分に効く」程度の素朴な換算にして、実験で調整する。
let EV_PARAMS={ resToValue:1.0, cityBonus:6, settleBonus:3, roadFactor:0.4, cardPoint:8, cardRemainDiscount:0.5, knightWeight:0.6 };
const RES_TO_VALUE=1.0;

// 各行動の「価値」= 残り試合への貢献。resへ焼き込む前の生の期待値。
// 建物: 生涯産出（1ダイス増分 × 残りダイス × 資源価値）
// カード/賞: 勝利点への近さを資源価値に換算
function actionValue(kind, p, opt){
  const R=remainingDice();
  if(kind==="city"){
    // 都市化: その頂点の産出が2倍→増分×残りダイス
    return cityGainPerDie(opt.vid)*R*EV_PARAMS.resToValue + EV_PARAMS.cityBonus;  // +6は「1手で確実に得る」ボーナス（都市は即2点効果薄いが産出は確実）
  }
  if(kind==="settle"){
    // 開拓地: 生涯産出 + 母体が増える将来価値（都市化の種）
    return settleGainPerDie(opt.vid)*R*EV_PARAMS.resToValue + EV_PARAMS.settleBonus;
  }
  if(kind==="road"){
    // 道: それ自体は産出ゼロ。すぐ良い開拓地が開くならその生涯産出の一部を先取り価値に。
    const open=opt.opensVid;
    const future = open!=null ? settleGainPerDie(open)*R*EV_PARAMS.resToValue*EV_PARAMS.roadFactor : 0;
    return future + (opt.forLongestRoad? 4:0);  // 道賞絡みなら加点
  }
  if(kind==="dev"){
    // カード: 残りダイスが多いほど建物優先＝カード価値は相対的に低い。
    // 終盤(残り少)は建物の生涯産出が小さいのでカードの相対価値が上がる。
    // VP期待(山札のVP比率で1点)＋騎士(騎士賞への寄与)を、残りダイスで割り引いた資源換算。
    const deck=game.dev.deck.length||25;
    const vpRatio=(game.dev.deck.filter(c=>c==="vp").length)/(deck||1) || (5/25);
    const knightRatio=(game.dev.deck.filter(c=>c==="knight").length)/(deck||1) || (14/25);
    // 1点=建物1軒ぶんの生涯産出くらい、と置いて、残りダイスが短いほどカード有利
    const pointValue = EV_PARAMS.cardPoint * (1 - Math.min(1, R/GAME_DICE)*EV_PARAMS.cardRemainDiscount);  // 残り多いと価値半減まで
    const vpEV = vpRatio*pointValue;                 // 直接1点
    const knightEV = knightRatio*pointValue*EV_PARAMS.knightWeight;      // 騎士賞への寄与（割引）
    return vpEV+knightEV;
  }
  return 0;
}

// 必要資源セット costObj を、現在の手札 hand と 産出 exp から「あと何ターンで貯まるか」概算。
// 交換(4:1など)も加味: 余る資源で不足を補える分は短縮。ざっくり期待ターン。
function turnsToAfford(p, costObj, handOverride){
  const hand=handOverride||Object.assign({},game.hands[p]);
  const exp=production(p);
  // 不足量
  let worst=0;
  const deficits={};
  for(const [r,need] of Object.entries(costObj)){
    const short=Math.max(0, need-(hand[r]||0));
    if(short<=0) continue;
    deficits[r]=short;
    const rate=exp[r]>0.001 ? exp[r] : 0.02;   // 産出ゼロ資源は交換頼み(遅い)
    worst=Math.max(worst, short/rate);
  }
  if(Object.keys(deficits).length===0) return 0;  // もう買える
  // 交換で補える見込み: 余剰資源の産出を不足に回すと少し速くなる（簡易割引）
  const surplusExp=Object.entries(exp).filter(([r])=>!(r in costObj)||hand[r]>=costObj[r]).reduce((s,[,v])=>s+v,0);
  const disc=Math.min(0.5, surplusExp*0.15);
  return worst*(1-disc);
}

// 10点の勝ち筋（63通り）を build 時に生成
const WIN_PLANS=(()=>{
  const plans=[];
  // VPカードは全25枚中5枚しかなく、3枚以上を当てにするのは確率的に非現実的。戦略上はVP≤2に限定。
  for(let LR=0;LR<=1;LR++) for(let LA=0;LA<=1;LA++) for(let V=0;V<=2;V++)
    for(let C=0;C<=4;C++) for(let S=0;S<=5;S++){
      if(S+2*C+V+2*LR+2*LA===10 && S+C>=2) plans.push({C,S,V,LR,LA});
    }
  return plans;
})();

// 1プラン分の期待ターン数を見積もる
function backSolveOne(p, plan){
  const cur_c=placements[p].cities?placements[p].cities.size:0;
  const cur_s=placements[p].settlements.size;
  const cur_v=game.dev.hands[p].vp;
  const cur_army=game.army[p];
  const cur_lr=(game.lr.holder===p), cur_la=(game.la.holder===p);
  const deck=game.dev.deck.length||25;
  const vpRatioInDeck=(game.dev.deck.filter(c=>c==="vp").length)/(deck||1) || (5/25);

  const needCities=Math.max(0, plan.C-cur_c);
  // 建物総数の差＝新規に建てる開拓地の数（都市化は建て替えなので建物総数は増えない）
  const buildingsNow=cur_s+cur_c;
  const buildingsGoal=plan.S+plan.C;
  const newBuildings=Math.max(0, buildingsGoal-buildingsNow);

  let t=0;
  for(let i=0;i<needCities;i++) t+=turnsToAfford(p,{wheat:2,ore:3});
  for(let i=0;i<newBuildings;i++){ t+=turnsToAfford(p,{wood:1,brick:1,sheep:1,wheat:1})+turnsToAfford(p,{wood:1,brick:1})*0.7; }
  const needVP=Math.max(0, plan.V-cur_v);
  if(needVP>0){ const buys=needVP/Math.max(0.08,vpRatioInDeck); t+=buys*turnsToAfford(p,{sheep:1,wheat:1,ore:1}); }
  if(plan.LA && !cur_la){ const target=Math.max(3,(game.la.count||0)+1); const need=Math.max(0,target-cur_army);
    t+=need*turnsToAfford(p,{sheep:1,wheat:1,ore:1})*1.1; }
  if(plan.LR && !cur_lr){ const cur_len=(game.lr.holder===p?game.lr.len:0); const need=Math.max(0,5-cur_len);
    t+=need*turnsToAfford(p,{wood:1,brick:1})*0.8; }
  return t;
}

function _dynamicDevCredit(observer,q,kind){
  if(q===observer){
    const h=game.dev&&game.dev.hands&&game.dev.hands[q];return h?(h[kind]||0):0;
  }
  const n=_rpHeldDevCount(q);
  if(kind==="knight")return n*(14/25);
  if(kind==="roads")return n*(2/25);
  if(kind==="vp")return n*(5/25);
  return 0;
}
function _dynamicAwardRaceEta(observer,q,kind){
  const hand=game.hands[q];
  if(kind==="LR"){
    if(game.lr.holder===q)return {eta:0,need:0,paid:0,extension:null};
    const target=game.lr.holder?(game.lr.len+1):5,gap=Math.max(1,target-longestRoadOf(q));
    let need=gap,extension=null;
    // 街道建設1枚で届く範囲だけ一筆書きを完全探索。遠方は1本道ごとに再計画する。
    if(gap<=2)try{extension=_rwBestExtension(q,2,target);if(extension)need=extension.edges.length;}catch(e){}
    const placedFree=(q===observer)?Math.max(0,game.freeRoads||0):0;
    const free=Math.min(need,placedFree+2*_dynamicDevCredit(observer,q,"roads"));
    const paid=Math.max(0,need-free),unit=turnsToAfford(q,COST.road,hand);
    return {eta:Math.min(128,paid*unit*0.8),need,paid,free,extension};
  }
  if(game.la.holder===q)return {eta:0,need:0,buy:0};
  const target=game.la.holder?(game.la.count+1):3,need=Math.max(0,target-(game.army[q]||0));
  const held=Math.min(need,_dynamicDevCredit(observer,q,"knight")),buy=Math.max(0,need-held);
  return {eta:Math.min(128,buy*turnsToAfford(q,COST.dev,hand)*1.1+Math.max(0,need-1)*4),need,buy,held};
}
function _dynamicRaceThreat(q){
  let prod=0;try{prod=Object.values(production(q)).reduce((a,b)=>a+b,0);}catch(e){}
  const expectedVP=_rpVisibleVP(q)+_rpHeldDevCount(q)*(5/25);
  return 0.65+Math.max(0,Math.min(1,(expectedVP-4)/5))+0.25*Math.max(0,Math.min(1,prod/1.8));
}
function _dynamicRaceSnapshot(p,kind){
  const mine=_dynamicAwardRaceEta(p,p,kind);let rival={q:null,eta:Infinity,threat:0};
  for(const q of game.order){if(q===p)continue;const z=_dynamicAwardRaceEta(p,q,kind),th=_dynamicRaceThreat(q);
    if(z.eta<rival.eta-1e-9||(Math.abs(z.eta-rival.eta)<1e-9&&th>rival.threat))rival={q,eta:z.eta,threat:th,detail:z};}
  return {kind,mine,rival,holder:kind==="LR"?game.lr.holder:game.la.holder};
}
function _dynamicLegacyAwardCost(p,kind){
  if(kind==="LA"){
    if(game.la.holder===p)return 0;
    const target=Math.max(3,(game.la.count||0)+1),need=Math.max(0,target-(game.army[p]||0));
    return need*turnsToAfford(p,COST.dev)*1.1;
  }
  if(game.lr.holder===p)return 0;
  return 5*turnsToAfford(p,COST.road)*0.8;
}
function _dynamicPlanSupports(rows){
  const out={city:0,settle:0,vp:0,LR:0,LA:0,both:0};
  for(const r of rows){const g=r.plan,w=r.weight||0,c=placements[r.p].cities?placements[r.p].cities.size:0,b=c+placements[r.p].settlements.size;
    if(g.C>c)out.city+=w;if(g.C+g.S>b)out.settle+=w;if(g.V>((game.dev.hands[r.p]&&game.dev.hands[r.p].vp)||0))out.vp+=w;
    if(g.LR&&game.lr.holder!==r.p)out.LR+=w;if(g.LA&&game.la.holder!==r.p)out.LA+=w;if(g.LR&&g.LA)out.both+=w;}
  return out;
}
function _dynamicBackSolveKey(p){
  const ps=[];for(const q of game.order){const pl=placements[q],h=game.hands[q]||{},d=game.dev.hands[q]||{};
    ps.push([q,[...pl.settlements].sort((a,b)=>a-b),[...(pl.cities||[])].sort((a,b)=>a-b),[...pl.roads].sort((a,b)=>a-b),
      RES5.map(r=>h[r]||0),q===p?[d.knight||0,d.vp||0,d.roads||0,d.plenty||0,d.mono||0]:[_rpHeldDevCount(q)],game.army[q]||0]);}
  return JSON.stringify([p,game.idx,game.phase,game.devPlayed?1:0,game.freeRoads||0,game.robber,game.lr.holder,game.lr.len,game.la.holder,game.la.count,ps]);
}
// 全プランから最短を選ぶ
function backSolve(p){
  const cur_c=placements[p].cities?placements[p].cities.size:0;
  const cfg=DYNAMIC_ROUTE_CFG&&DYNAMIC_ROUTE_CFG[p];
  let cacheKey=null;if(cfg){cacheKey=_dynamicBackSolveKey(p);const c=DYNAMIC_ROUTE_CACHE.get(game);if(c&&c.has(cacheKey))return c.get(cacheKey);}
  const lr=cfg?_dynamicRaceSnapshot(p,"LR"):null,la=cfg?_dynamicRaceSnapshot(p,"LA"):null,rows=[];
  let best=null;
  for(const plan of WIN_PLANS){
    if(plan.C<cur_c) continue;   // 都市は減らない
    const raw=backSolveOne(p,plan);let t=raw,adjust=0;
    if(cfg){
      const applyRace=(kind,race)=>{if(!plan[kind])return;t-=_dynamicLegacyAwardCost(p,kind);t+=race.mine.eta;
        const rival=race.rival;if(!rival||rival.q==null||!isFinite(rival.eta))return;
        if(race.holder===p)adjust+=(cfg.holdW==null ? .35 : cfg.holdW)*Math.max(0,Math.min(24,t-rival.eta))*rival.threat;
        else{const gap=race.mine.eta-rival.eta;if(gap>0)adjust+=(cfg.contestW==null ? .75 : cfg.contestW)*Math.min(24,gap)*rival.threat;
          else adjust-=(cfg.denyW==null ? .18 : cfg.denyW)*Math.min(12,-gap)*rival.threat;}};
      applyRace("LR",lr);applyRace("LA",la);t+=Math.max(-12,Math.min(48,adjust));
    }
    const row={p,plan,turns:t,rawTurns:raw,adjust};rows.push(row);if(!best||t<best.turns)best=row;
  }
  if(cfg&&best){
    const top=rows.sort((a,b)=>a.turns-b.turns).slice(0,Math.max(1,Math.min(8,cfg.topK||5))),beta=cfg.beta==null ? .22 : cfg.beta,min=top[0].turns;
    let z=0;for(const r of top){r.weight=Math.exp(-beta*Math.max(0,r.turns-min));z+=r.weight;}for(const r of top)r.weight/=z||1;
    best={plan:top[0].plan,turns:top[0].turns,rawTurns:top[0].rawTurns,
      portfolio:top.map(r=>({plan:r.plan,turns:r.turns,rawTurns:r.rawTurns,adjust:r.adjust,weight:r.weight})),
      dynamic:{support:_dynamicPlanSupports(top),races:{LR:lr,LA:la}}};
    let c=DYNAMIC_ROUTE_CACHE.get(game);if(!c){c=new Map();DYNAMIC_ROUTE_CACHE.set(game,c);}if(c.size>96)c.clear();c.set(cacheKey,best);
  }
  return best;
}
function _dynamicHasSettleSpot(p){
  for(const vs in GEO.vertex_neighbors){const v=Number(vs);if(occupantOf(v))continue;if((GEO.vertex_neighbors[vs]||[]).some(x=>occupantOf(x)))continue;
    if(GEO.edges.some(e=>(e.a===v||e.b===v)&&placements[p].roads.has(e.id)))return true;}
  return false;
}
function _dynamicRoadCardIntent(p){
  const cfg=DYNAMIC_ROUTE_CFG&&DYNAMIC_ROUTE_CFG[p];if(!cfg)return null;
  let solved=null;try{solved=backSolve(p);}catch(e){return {use:false};}
  const sup=solved&&solved.dynamic&&solved.dynamic.support;if(!sup)return {use:false};
  const min=cfg.cardRoadMin==null ? .28 : cfg.cardRoadMin,target=game.lr.holder?(game.lr.len+1):5,gap=Math.max(1,target-longestRoadOf(p));
  const race=solved.dynamic.races&&solved.dynamic.races.LR;let ext=race&&race.mine&&race.mine.extension;if(!ext&&gap<=2)try{ext=_rwBestExtension(p,2,target);}catch(e){}
  const rivalEta=race&&race.rival?race.rival.eta:Infinity,viable=!race||!isFinite(rivalEta)||race.mine.eta<=rivalEta+(cfg.cardRaceSlack==null?4:cfg.cardRaceSlack);
  let use=!!(sup.LR>=min&&viable&&((gap<=2&&ext&&ext.edges.length<=2)||(gap>=3&&gap<=4)));
  if(!use&&sup.settle>=Math.max(.45,min)&&!_dynamicHasSettleSpot(p))use=true;
  return {use,solved,extension:ext};
}

// 鉄麦羊の継続産出から、1ダイスあたり何枚の発展カードを買えるかを推定する。
// 余剰資源は所有港の2:1/3:1（無ければ4:1）で不足資源へ変換できるものとして計算。
function devProductionRate(q){
  const prod=production(q), need=["sheep","wheat","ore"];
  let lo=0, hi=Math.max(0.001, RES5.reduce((s,r)=>s+prod[r],0));
  for(let i=0;i<28;i++){
    const x=(lo+hi)/2;
    let deficit=0, convertible=0;
    for(const r of need) deficit+=Math.max(0,x-(prod[r]||0));
    for(const r of RES5) convertible+=Math.max(0,(prod[r]||0)-x*(need.includes(r)?1:0))/rateFor(q,r);
    if(convertible+1e-12>=deficit) lo=x; else hi=x;
  }
  return lo;
}

// 全員の「使用済み騎士＋今後の騎士供給力」を相対化し、騎士賞の2点を見込み点として分配。
// 戦力 = 使用済み騎士 + 18ダイス分のカード購入力×騎士率(14/25)。確率の総和=1、見込み点の総和=2。
function largestArmyOutlook(){
  const raw={}, devRate={}; let sum=0;
  for(const q of game.order){
    devRate[q]=devProductionRate(q);
    const used=(game.army&&game.army[q])||0;
    raw[q]=Math.max(0.05, used + LA_RACE_ROLLS*devRate[q]*(14/25));
    sum+=raw[q];
  }
  const chance={}, expectedPoints={};
  for(const q of game.order){ chance[q]=raw[q]/sum; expectedPoints[q]=2*chance[q]; }
  return {chance,expectedPoints,raw,devRate};
}

// 脅威度: 「表面VPが高い相手」ではなく「本当に勝ちに近い相手」を測る。
// 実データ分析の発見: 人間の強者はカードを大量に買い(VPを隠し)、騎士で盗賊を捌くため、
// 表面VPだけ見ているAIからは脅威に見えず、放置される（実測: AIが人間を狙ったのは26%＝ランダム以下）。
// ここでは「対戦相手から実際に見える情報」だけを使う（手札の中身は覗かない＝カンニングしない）。
function threatOf(q, laOutlook){
  let t = vpOf(q) * THREAT_W.vp;
  // 生産力: 建物が接するタイルのpip合計（都市は2倍）
  let pip=0;
  for(const hx of GEO.hexes){
    const b=board[hx.id];
    if(!b||!b.number||!b.resource||b.resource==="desert") continue;
    if(hx.id===game.robber) continue;
    for(const v of hexVertsG(hx.id)){
      const oc=occupantOf(v);
      if(oc&&oc.p===q) pip += pipOf(b.number) * (oc.type==="city"?2:1);
    }
  }
  t += pip * THREAT_W.pip;
  // 騎士賞の見込み2点。単純な使用騎士数ではなく、全員の騎士数・鉄麦羊・港変換力の相対値。
  const la=laOutlook||largestArmyOutlook();
  t += la.expectedPoints[q] * THREAT_W.knight;
  return t;
}
// 盗む相手が複数いる時は、脅威度(threatOf)の高い方を選ぶ。
// 脅威度はVP・生産力・騎士賞見込み点から毎ターン動的に計算されるので、
// 試合開始〜終盤で狙う相手が状況に応じて変わる（従来は常にstealCands[0]で固定だった）。
function bestStealTarget(cands){
  if(!cands || !cands.length) return null;
  if(cands.length===1) return cands[0];
  let best=cands[0], bt=-Infinity, la=null;
  try{ la=largestArmyOutlook(); }catch(e){}
  for(const q of cands){ let tv; try{ tv=threatOf(q,la); }catch(e){ tv=vpOf(q); } if(tv>bt){ bt=tv; best=q; } }
  return best;
}
// あるタイルに、指定プレイヤーの「都市」が接しているか
function _hexHasCityOf(hid, p){
  return hexVertsG(hid).some(v=>{ const oc=occupantOf(v); return oc&&oc.p===p&&oc.type==="city"; });
}
// あるタイルに、指定プレイヤーの建物（都市or開拓地）が接しているか
function _hexHasBuildingOf(hid, p){
  return hexVertsG(hid).some(v=>{ const oc=occupantOf(v); return oc&&oc.p===p; });
}
// プレイヤーpが2:1港（特定資源港）で押さえている資源の集合
function _portResourcesOf(p){
  const s=new Set();
  const own=[...placements[p].settlements, ...(placements[p].cities||[])];
  const ownSet=new Set(own);
  for(const eid in ports){
    const type=ports[eid];
    if(type==="3:1"||!type) continue;   // 汎用港は資源特定でないので対象外
    const e=GEO.edges[+eid];
    if(ownSet.has(e.a)||ownSet.has(e.b)) s.add(type);
  }
  return s;
}
// SMART_ROBBER: ユーザーの盗賊ロジック（優先順位つき）
//  1) 相手の「強い鉄(pip>=3)の都市」。ただし最序盤(まだ誰も都市を持たない)は開拓地も対象
//  2) 無ければ相手の「麦」
//  3) 無ければ相手が「2:1港で押さえている資源」
// いずれも自分の産出タイルは避ける（避けられない時だけ次善策=fallback）
function robberAdviceSmart(top){
  // 最序盤か: 盤面にまだ都市が1つも無い（初期配置直後～序盤）
  let anyCity=false;
  for(let p=1;p<=numPlayers;p++){ if(placements[p]&&placements[p].cities&&placements[p].cities.size>0){ anyCity=true; break; } }
  const earlyGame=!anyCity;
  const STRONG_ORE=3;   // pip3以上を「強い鉄」とみなす（ユーザー指定）
  const portRes=_portResourcesOf(top);   // topが港で押さえてる資源

  // 優先度を返す: 大きいほど狙いたい。0はそもそも対象外。
  function priorityOf(hid,b){
    const pip=pipOf(b.number);
    // 1) 強い鉄の都市（最序盤は開拓地も可）
    if(b.resource==="ore" && pip>=STRONG_ORE){
      if(_hexHasCityOf(hid,top)) return 300+pip;
      if(earlyGame && _hexHasBuildingOf(hid,top)) return 250+pip;   // 最序盤は開拓地でも狙う
    }
    // 2) 麦（topの建物が接していれば対象。pipで差をつける）
    if(b.resource==="wheat") return 200+pip;
    // 3) topが2:1港で押さえている資源
    if(portRes.has(b.resource)) return 100+pip;
    return 0;
  }
  let best=null, fallback=null;
  for(const hx of GEO.hexes){
    if(hx.id===game.robber) continue;
    const b=board[hx.id]; if(!b||!b.number||!b.resource||b.resource==="desert") continue;
    if(!_hexHasBuildingOf(hx.id,top)) continue;   // topの建物が接していないタイルは対象外
    const pr=priorityOf(hx.id,b);
    if(pr<=0) continue;
    const ownsMe=_hexHasBuildingOf(hx.id,cur());
    const cand={hid:hx.id, sc:pr, top, res:b.resource, num:b.number};
    if(ownsMe){ if(!fallback||pr>fallback.sc) fallback=cand; continue; }
    if(!best||pr>best.sc) best=cand;
  }
  return best || fallback;   // 自分を止めない狙い先が無ければ次善策
}
// [遅延盗賊 H9/H10] 相手の「直近の次の建設」を最も遅らせる置き方。人間棋譜の一致率で検証済み
//  （強い人間の実手一致 36% vs 従来0%）かつ自己対戦で無害（49.5%/600局）。既定ON。
//  各候補ヘクスへ盗賊を仮置きし、相手の次建設のturnsToAfford増分（遅延）を、
//  「今すぐ建ちそう」なほど重く(imminence)・脅威の高い相手ほど重く(threatW)加点。自分を止める分は減点。
let ROBBER_DELAY=true;
// [2026-08-24] 10万試合で採用した最強AI専用盗賊。
// 先に「10点へ最も近い相手」を決め、騎士賞見込み込みでその相手の行動確率を最大限落とす。
// app.js が最強AI/無敵AIの手番だけ true にする。falseなら従来の遅延盗賊へ完全非回帰。
let ROBBER_RP_ARMY=false;
function _nextBuildCostRD(q){
  const nc=(placements[q].cities?placements[q].cities.size:0), ns=placements[q].settlements.size;
  const cands=[];
  if(ns>0 && nc<4) cands.push(COST.city);
  if(ns+nc<7) cands.push(COST.settlement);
  cands.push(COST.dev);
  let best=cands[0], bt=Infinity;
  for(const c of cands){ const t=turnsToAfford(q,c); if(t<bt){ bt=t; best=c; } }
  return {cost:best, turns:bt};
}
function robberAdviceDelay(me){
  const saved=game.robber;
  const opp=game.order.filter(q=>q!==me);
  const cost={}, base={};
  let baseLA=null; try{ baseLA=largestArmyOutlook(); }catch(e){}
  const maxTh=Math.max(1, ...opp.map(q=>{ try{return threatOf(q,baseLA);}catch(e){return 1;} }));
  for(const q of opp){ const nb=_nextBuildCostRD(q); cost[q]=nb.cost; base[q]=nb.turns; }
  const myNb=_nextBuildCostRD(me), myBase=myNb.turns;
  let best=null, fallback=null;
  for(const hx of GEO.hexes){
    if(hx.id===saved) continue;
    const b=board[hx.id]; if(!b||!b.number||!b.resource||b.resource==="desert") continue;
    game.robber=hx.id;
    let candidateLA=null; try{ candidateLA=largestArmyOutlook(); }catch(e){}
    let score=0, hitsOpp=false, hitsMe=false;
    for(const q of opp){
      if(!_hexHasBuildingOf(hx.id,q)) continue;
      hitsOpp=true;
      const delta=Math.max(0, turnsToAfford(q,cost[q]) - base[q]);
      const imminence=1/(1+base[q]);                 // 早い建設ほど重い
      const threatW=0.5+0.5*(threatOf(q,candidateLA)/maxTh); // 脅威の高い相手ほど重い
      score += delta*imminence*threatW;
    }
    if(_hexHasBuildingOf(hx.id,me)){
      hitsMe=true;
      score -= Math.max(0, turnsToAfford(me,myNb.cost) - myBase)*1.2;   // 自分の首を絞めない
    }
    const cand={hid:hx.id, sc:score, top:null, res:b.resource, num:b.number};
    if(!hitsOpp){ continue; }
    if(hitsMe){ if(!fallback||score>fallback.sc) fallback=cand; }
    else { if(!best||score>best.sc) best=cand; }
  }
  game.robber=saved;
  const pick = best || fallback;
  if(pick){   // 奪う相手は同タイル上の最脅威者
    let tp=null, tv=-Infinity;
    for(const q of opp){ if(_hexHasBuildingOf(pick.hid,q)){ let t; try{t=threatOf(q,baseLA);}catch(e){t=vpOf(q);} if(t>tv){ tv=t; tp=q; } } }
    pick.top=tp;
  }
  return pick;
}

// 相手から見える伏せカード枚数。カードの種類は使わない。
function _rpHeldDevCount(q){
  try{ const h=game.dev.hands[q]; return h?Object.values(h).reduce((a,b)=>a+b,0):0; }
  catch(e){ return 0; }
}
function _rpVisibleVP(q){
  let v=placements[q].settlements.size+2*(placements[q].cities?placements[q].cities.size:0);
  if(game.lr.holder===q)v+=2;
  if(game.la.holder===q)v+=2;
  return v;
}

// 都市・家・カードを別行動として評価する。同じ1ターン遅延でも価値を同一にしない。
function _rpBuildOptions(q){
  const out=[];
  if(placements[q].settlements.size&&placements[q].cities.size<4){
    let bestPip=0;
    for(const v of placements[q].settlements){
      let pp=0;
      for(const hid of (GEO.vertex_hexes[String(v)]||[])){ const b=board[hid]; if(b&&b.number)pp+=pipOf(b.number); }
      bestPip=Math.max(bestPip,pp);
    }
    const first=placements[q].cities.size===0;
    out.push({kind:"city",cost:COST.city,impact:(first?2.4:1.35)+bestPip/5});
  }
  if(placements[q].settlements.size<5){
    let bp=0,hasSpot=false;
    try{
      for(const vx of GEO.vertices){ const v=vx.id;
        if(occupantOf(v)||(GEO.vertex_neighbors[String(v)]||[]).some(n=>occupantOf(n)))continue;
        if(!GEO.edges.some(e=>(e.a===v||e.b===v)&&placements[q].roads.has(e.id)))continue;
        hasSpot=true;
        let pp=0;for(const hid of (GEO.vertex_hexes[String(v)]||[])){const b=board[hid];if(b&&b.number)pp+=pipOf(b.number);}
        bp=Math.max(bp,pp);
      }
    }catch(e){}
    if(hasSpot)out.push({kind:"settle",cost:COST.settlement,impact:1.1+bp/6});
  }
  if(game.dev&&game.dev.deck&&game.dev.deck.length){
    const armyGap=Math.max(0,3-(game.army[q]||0));
    out.push({kind:"dev",cost:COST.dev,impact:0.65+(armyGap<=2?0.35:0)});
  }
  return out;
}

// 使用済み騎士＋伏せ札期待＋鉄麦羊/港の12投カード供給力を相対化する。
function _rpArmyShareVector(){
  const raw={},target=game.la.holder?game.la.count+1:3,kd=14/25;let z=0;
  for(const q of game.order){
    const used=(game.army&&game.army[q])||0,held=_rpHeldDevCount(q);
    let pr={wood:0,brick:0,sheep:0,wheat:0,ore:0};try{pr=production(q);}catch(e){}
    const base=Math.min(pr.sheep||0,pr.wheat||0,pr.ore||0);
    let credit=0;for(const r of RES5)credit+=Math.max(0,(pr[r]||0)-base)/Math.max(2,rateFor(q,r));
    const cardRate=base+credit/3;
    const future=Math.min(2.0,12*cardRate)*kd;
    const strength=used+held*kd+future;
    let x=Math.exp(1.15*(strength-target));
    if(game.la.holder===q)x*=1.35;
    raw[q]=x;z+=x;
  }
  const out={};for(const q of game.order)out[q]=(raw[q]||0)/(z||1);return out;
}

// 10点までの公開近似ETAを主軸に、騎士賞見込みと生産力で対象者を決める。
function _rpRouteThreatVector(army){
  const out={};
  for(const q of game.order){
    let eta=80;
    const hand=game.dev&&game.dev.hands&&game.dev.hands[q];
    const oldVp=hand?hand.vp:0;
    try{ if(hand)hand.vp=0;const b=backSolve(q);if(b&&isFinite(b.turns))eta=b.turns; }
    catch(e){}
    finally{ if(hand)hand.vp=oldVp; }
    let pip=0;try{pip=Object.values(production(q)).reduce((a,b)=>a+b,0)*36;}catch(e){}
    const expectedVP=_rpVisibleVP(q)+2*(army[q]||0)+_rpHeldDevCount(q)*(5/25);
    out[q]=Math.exp(-Math.min(120,eta)/24)*(1+0.10*expectedVP)+0.0015*pip;
  }
  return out;
}

// 同じ産出分布から、8/12投以内に都市・家・カードが成立する確率を同時に求める。
function _rpActionProbs(q,actions,horizons){
  if(!actions.length)return null;
  const RESA=["wood","brick","sheep","wheat","ore"],rates={};for(const r of RESA)rates[r]=rateFor(q,r);
  const hand=game.hands[q]||{},capSets=(typeof MS_CAPSETS!=="undefined"?MS_CAPSETS:1);
  const caps=RESA.map(r=>Math.max(0,...actions.map(a=>(a.cost[r]||0)))+(rates[r]||4)*capSets);
  const sizes=caps.map(c=>c+1),N=sizes.reduce((a,b)=>a*b,1);if(N>200000)return null;
  const stride=new Array(5);stride[4]=1;for(let i=3;i>=0;i--)stride[i]=stride[i+1]*sizes[i+1];
  const feas=actions.map(()=>new Uint8Array(N)),cnt=[0,0,0,0,0];
  for(let i=0;i<N;i++){
    let rem=i;for(let a=0;a<5;a++){cnt[a]=(rem/stride[a])|0;rem-=cnt[a]*stride[a];}
    for(let k=0;k<actions.length;k++){
      const nd=actions[k].cost;let def=0,tr=0;
      for(let a=0;a<5;a++){const need=nd[RESA[a]]||0,c=cnt[a];if(c<need)def+=need-c;else tr+=((c-need)/(rates[RESA[a]]||4))|0;}
      if(tr>=def)feas[k][i]=1;
    }
  }
  const start=RESA.map((r,a)=>Math.min(hand[r]||0,caps[a]));
  const s0=start.reduce((z,c,a)=>z+c*stride[a],0),prod=_prodTableFor(q);
  const PIPN={2:1,3:2,4:3,5:4,6:5,8:5,9:4,10:3,11:2,12:1},outs=[];let pProd=0;
  for(const d in prod){const g=prod[d];if(!g)continue;const gv=RESA.map(r=>g[r]||0);if(!gv.some(x=>x>0))continue;
    const pr=(PIPN[d]||0)/36;if(pr<=0)continue;pProd+=pr;const map=new Int32Array(N);
    for(let i=0;i<N;i++){let rem=i,j=0;for(let a=0;a<5;a++){let c=(rem/stride[a])|0;rem-=c*stride[a];c=Math.min(caps[a],c+gv[a]);j+=c*stride[a];}map[i]=j;}
    outs.push({pr,map});
  }
  const want=new Set(horizons),out={};let P=new Float64Array(N);P[s0]=1;const pNo=Math.max(0,1-pProd);
  for(let t=1;t<=Math.max(...horizons);t++){
    const Q=new Float64Array(N);
    for(const o of outs){for(let i=0;i<N;i++){const v=P[i];if(v)Q[o.map[i]]+=o.pr*v;}}
    if(pNo)for(let i=0;i<N;i++)if(P[i])Q[i]+=pNo*P[i];P=Q;
    if(want.has(t))out[t]=feas.map(f=>{let s=0;for(let i=0;i<N;i++)if(f[i])s+=P[i];return Math.min(1,s);});
  }
  return out;
}

function _rpDamage(q,opts,before,after,army){
  if(!before||!after)return 0;
  let total=0;
  for(let k=0;k<opts.length;k++){
    const drop8=Math.max(0,(before[8][k]||0)-(after[8][k]||0));
    const drop12=Math.max(0,(before[12][k]||0)-(after[12][k]||0));
    let impact=opts[k].impact;
    // 検証済みrpArmyと同じく、カード価値は騎士賞確率に応じて0.25〜2.25へ置換する。
    if(opts[k].kind==="dev")impact=0.25+2*(army[q]||0);
    total+=(0.5*drop8+0.5*drop12)*impact;
  }
  return total;
}

function robberAdviceRpArmy(me){
  const saved=game.robber,opp=game.order.filter(q=>q!==me),horizons=[8,12];
  const army=_rpArmyShareVector(),route=_rpRouteThreatVector(army),opts={},before={},raw={};let maxU=1;
  for(const q of game.order){opts[q]=_rpBuildOptions(q);before[q]=_rpActionProbs(q,opts[q],horizons);}
  for(const q of opp){raw[q]=Math.max(0.001,route[q]||0)+(army[q]||0);maxU=Math.max(maxU,raw[q]);}
  const focus=opp.slice().sort((a,b)=>(raw[b]||0)-(raw[a]||0))[0];
  const urgency=0.25+0.75*(raw[focus]||0)/maxU;
  let best=null,fallback=null;
  for(const hx of GEO.hexes){
    if(hx.id===saved)continue;
    const b=board[hx.id];if(!b||!b.number||!b.resource||b.resource==="desert")continue;
    if(!_hexHasBuildingOf(hx.id,focus))continue;
    const hitsMe=_hexHasBuildingOf(hx.id,me);game.robber=hx.id;
    let score=_rpDamage(focus,opts[focus],before[focus],_rpActionProbs(focus,opts[focus],horizons),army)*urgency;
    if(hitsMe)score-=1.2*_rpDamage(me,opts[me],before[me],_rpActionProbs(me,opts[me],horizons),army);
    if(b.number===2||b.number===12)score*=0.05;
    const c={hid:hx.id,sc:score,top:focus,res:b.resource,num:b.number};
    if(hitsMe){if(!fallback||score>fallback.sc)fallback=c;}else if(!best||score>best.sc)best=c;
  }
  game.robber=saved;
  return best||fallback;
}
function robberAdvice(){
  if(typeof ROBBER_RP_ARMY!=="undefined"&&ROBBER_RP_ARMY){try{const _r=robberAdviceRpArmy(cur());if(_r)return _r;}catch(e){console.warn("rpArmy robber fallback",e);}}
  if(typeof ROBBER_DELAY!=="undefined" && ROBBER_DELAY){ try{ const _r=robberAdviceDelay(cur()); if(_r) return _r; }catch(e){} }
  let top=null;
  // vs AI対戦中か（game.aiがあり、人間席が1つ以上ある）を判定
  const _vsHuman = (typeof ROBBER_TARGET_HUMAN!=="undefined" && ROBBER_TARGET_HUMAN
                    && game && game.ai && game.order.some(q=>!game.ai.has(q)));
  const _threatAdj=(q,t)=>{
    // vs AI時: 相手が人間なら脅威度を少し上乗せして、拮抗時に人間を優先して狙う
    if(_vsHuman && !game.ai.has(q)) return t*(1+ROBBER_HUMAN_BONUS);
    return t;
  };
  if(typeof USE_THREAT!=="undefined" && USE_THREAT){
    let la=null; try{ la=largestArmyOutlook(); }catch(e){}
    let bestT=-Infinity;
    for(const q of game.order){ if(q===cur()) continue;
      const t=_threatAdj(q, threatOf(q,la)); if(t>bestT){ bestT=t; top=q; } }
  }else{
    // 表面VP方式でも、人間は少し優先（VP同点なら人間を狙う）
    let bestV=-Infinity;
    for(const q of game.order){ if(q===cur()) continue;
      const v=_threatAdj(q, vpOf(q)); if(v>bestV){ bestV=v; top=q; } }
  }
  if(top==null) return null;
  // SMART_ROBBER（ユーザーの優先順位ロジック）
  if(typeof SMART_ROBBER!=="undefined" && SMART_ROBBER){
    const r=robberAdviceSmart(top);
    if(r) return r;
    // 狙い先ゼロなら従来ロジックにフォールバック（下へ流れる）
  }
  // トップの鉄麦を狙うが、自分の生産タイルは塞がない（自分の首を絞めない）
  let best=null, fallback=null;
  for(const hx of GEO.hexes){
    if(hx.id===game.robber) continue;
    const b=board[hx.id]; if(!b||!b.number||!b.resource||b.resource==="desert") continue;
    const ownsTop=hexVertsG(hx.id).some(v=>{const oc=occupantOf(v); return oc&&oc.p===top;});
    if(!ownsTop) continue;
    const ownsMe=hexVertsG(hx.id).some(v=>{const oc=occupantOf(v); return oc&&oc.p===cur();});
    const ow=(b.resource==="ore"||b.resource==="wheat");
    let sc=pipOf(b.number)*(ow?2:1);
    if(ownsMe){ if(!fallback||sc>fallback.sc) fallback={hid:hx.id, sc, top, res:b.resource, num:b.number}; continue; }
    if(!best||sc>best.sc) best={hid:hx.id, sc, top, res:b.resource, num:b.number};
  }
  return best || fallback;   // 自分を止めない場所が無ければ従来通り
}
function render(){
  computeTransform();
  SVG.setAttribute("viewBox",`0 0 ${TF.w} ${TF.h}`);
  SVG.innerHTML="";
  const _placePreview=(typeof placementPreview==="function")?placementPreview():null;

  // ヘクス面 + トークン
  for(const h of GEO.hexes){
    const info = board[h.id];
    const pts = hexCornersPx(h).map(p=>p.join(",")).join(" ");
    const poly = el("polygon",{points:pts, class:"hexface",
      fill: info.resource ? RES_COLOR[info.resource] : "#2b3138", style:"cursor:pointer",
      role:"button",tabindex:0,"aria-label":`タイル ${h.id}`});
    poly.addEventListener("click",()=>clickHex(h.id));
    poly.addEventListener("keydown",ev=>{if(ev.key==="Enter"||ev.key===" "){ev.preventDefault();clickHex(h.id);}});
    SVG.appendChild(poly);
    const cx=TX(h.cx), cy=TY(h.cy);
    if(!info.resource){
      const q=el("text",{x:cx,y:cy,"text-anchor":"middle","dominant-baseline":"central","font-size":18,fill:"#7a828d","pointer-events":"none"}); q.textContent="?"; SVG.appendChild(q);
    }
    if(info.number){
      const pips=PIP[info.number], hot=(info.number===6||info.number===8);
      SVG.appendChild(el("circle",{cx,cy,r:15,class:"token","pointer-events":"none"}));
      const t=el("text",{x:cx,y:cy-3,class:"tokennum"+(hot?" hot":""),"font-size":"14","pointer-events":"none"}); t.textContent=info.number; SVG.appendChild(t);
      const dotW=4;
      for(let i=0;i<pips;i++){
        const dx = cx - (pips-1)*dotW/2 + i*dotW;
        SVG.appendChild(el("circle",{cx:dx, cy:cy+9, r:1.1, class:"pipdot"+(hot?" hot":""),"pointer-events":"none"}));
      }
    }
  }
  // 選択中タイルの強調
  if(selectedHex!=null){
    const pts=hexCornersPx(GEO.hexes[selectedHex]).map(p=>p.join(",")).join(" ");
    SVG.appendChild(el("polygon",{points:pts,fill:"none",stroke:"var(--gold)","stroke-width":3,"pointer-events":"none"}));
  }

  // 辺（街道）
  for(const e of GEO.edges){
    const a=GEO.vertices[e.a], b=GEO.vertices[e.b];
    const x1=TX(a.x),y1=TY(a.y),x2=TX(b.x),y2=TY(b.y);
    const _rp=curReplay();
    const owner = _rp ? _rp.road[e.id] : ownerOf("roads",e.id);
    if(owner){
      SVG.appendChild(el("line",{x1,y1,x2,y2,class:"edgeink",stroke:PCOLORS[owner-1]}));
    }
    const hit=el("line",{x1,y1,x2,y2,class:"edge",role:"button",tabindex:0,"aria-label":`道 ${e.id}`});
    hit.addEventListener("click",()=>clickEdge(e.id));
    hit.addEventListener("keydown",ev=>{if(ev.key==="Enter"||ev.key===" "){ev.preventDefault();clickEdge(e.id);}});
    SVG.appendChild(hit);
    if(_placePreview&&_placePreview.type==="edge"&&_placePreview.id===e.id){
      SVG.appendChild(el("line",{x1,y1,x2,y2,class:"placement-preview-line",stroke:PCOLORS[_placePreview.seat-1],"pointer-events":"none"}));
    }
  }

  // 最善配置ハイライト（シミュ中は開拓地フェーズのみ）
  if(showBest && (!sim || sim.phase==="settle")){
    const useMCTS = (SCORE_METHOD==="mcts");
    const _bs = (typeof game!=="undefined" && game && game.setup) ? game.setup.queue[game.setup.step] : null;
    const B=computeBestStrong(_bs);
    let mctsReady=false;
    if(useMCTS){
      const key=_mctsAdvKey();
      if(mctsAdv.key===key && mctsAdv.stats){ mctsReady=true; }
      else { triggerMCTSAdvice(); }
    }
    if(mctsReady){
      // ===== MCTS結果で描画（プレイアウト勝率をそのまま強さとして表示） =====
      const stats=mctsAdv.stats;
      const wr=stats.map(s=>s.wins/s.games);
      const mn2=Math.min(...wr), mx2=Math.max(...wr), span2=Math.max(0.001, mx2-mn2);
      for(const s of stats){
        const v=GEO.vertices[s.vid]; const cx=TX(v.x),cy=TY(v.y);
        const t=((s.wins/s.games)-mn2)/span2;
        const hue=270, sat=Math.round(45+45*t), lit=Math.round(50+8*t);   // MCTSは紫系にして区別
        const r=8+7*t;
        SVG.appendChild(el("circle",{cx,cy,r:r.toFixed(1),
          fill:`hsl(${hue} ${sat}% ${lit}%)`, "fill-opacity":(0.35+0.4*t).toFixed(2),
          stroke:"#ffffff","stroke-width":1,"stroke-opacity":(0.25+0.5*t).toFixed(2),"pointer-events":"none"}));
      }
      stats.slice(0,3).forEach((s,i)=>{
        const v=GEO.vertices[s.vid]; const cx=TX(v.x),cy=TY(v.y);
        SVG.appendChild(el("circle",{cx,cy,r:15, fill:"none", stroke:"#ffffff","stroke-width":2.5, "pointer-events":"none"}));
        const rr=bestRoadFrom(s.vid);
        if(rr.length){
          const fv=GEO.vertices[rr[0].fv];
          const fx=TX(fv.x), fy=TY(fv.y);
          const dx=fx-cx, dy=fy-cy, L=Math.hypot(dx,dy)||1;
          const ex=cx+dx/L*26, ey=cy+dy/L*26;
          SVG.appendChild(el("line",{x1:cx+dx/L*15,y1:cy+dy/L*15,x2:ex,y2:ey,stroke:"#ffffff","stroke-width":3,"stroke-linecap":"round","pointer-events":"none"}));
          const px=-dy/L, py=dx/L;
          SVG.appendChild(el("polygon",{points:`${ex+dx/L*7},${ey+dy/L*7} ${ex+px*4.5},${ey+py*4.5} ${ex-px*4.5},${ey-py*4.5}`,fill:"#ffffff","pointer-events":"none"}));
        }
        SVG.appendChild(el("circle",{cx:cx+11,cy:cy-11,r:8, fill:"#111418", stroke:"#ffffff","stroke-width":1.5,"pointer-events":"none"}));
        const badge=el("text",{x:cx+11,y:cy-11, "text-anchor":"middle","dominant-baseline":"central","font-size":11,"font-weight":800, fill:"#ffffff","pointer-events":"none"});
        badge.textContent=(i+1); SVG.appendChild(badge);
      });
    }
    if(useMCTS && mctsAdv.computing){
      // 計算中インジケータ（盤の中心に表示）
      const t2=el("text",{x:0,y:0,"text-anchor":"middle","dominant-baseline":"central","font-size":16,"font-weight":800,fill:"#ffffff","pointer-events":"none"});
      t2.textContent="🧠 MCTS計算中…（約1秒）"; SVG.appendChild(t2);
    }
    if(!mctsReady){
    const span=Math.max(0.001, B.mx-B.mn);
    for(const vid of B.ranked){
      const v=GEO.vertices[vid]; const cx=TX(v.x),cy=TY(v.y);
      const t=(B.scores[vid].score-B.mn)/span;      // 0(弱)〜1(強)
      // 弱い＝小さめの青灰、強い＝大きめの明るい緑。白フチで輪郭をはっきり
      const hue=150, sat=Math.round(35+45*t), lit=Math.round(48+8*t);
      const r=8+7*t;
      SVG.appendChild(el("circle",{cx,cy,r:r.toFixed(1),
        fill:`hsl(${hue} ${sat}% ${lit}%)`, "fill-opacity":(0.35+0.4*t).toFixed(2),
        stroke:"#ffffff","stroke-width":1,"stroke-opacity":(0.25+0.5*t).toFixed(2),"pointer-events":"none"}));
    }
    B.ranked.slice(0,3).forEach((vid,i)=>{
      const v=GEO.vertices[vid]; const cx=TX(v.x),cy=TY(v.y);
      SVG.appendChild(el("circle",{cx,cy,r:15, fill:"none", stroke:"#ffffff","stroke-width":2.5, "pointer-events":"none"}));
      // おすすめの街道の向き（白い矢印）
      const rr=bestRoadFrom(vid);
      if(rr.length){
        const fv=GEO.vertices[rr[0].fv];
        const fx=TX(fv.x), fy=TY(fv.y);
        const dx=fx-cx, dy=fy-cy, L=Math.hypot(dx,dy)||1;
        const ex=cx+dx/L*26, ey=cy+dy/L*26;
        SVG.appendChild(el("line",{x1:cx+dx/L*15,y1:cy+dy/L*15,x2:ex,y2:ey,stroke:"#ffffff","stroke-width":3,"stroke-linecap":"round","pointer-events":"none"}));
        const px=-dy/L, py=dx/L;
        SVG.appendChild(el("polygon",{points:`${ex+dx/L*7},${ey+dy/L*7} ${ex+px*4.5},${ey+py*4.5} ${ex-px*4.5},${ey-py*4.5}`,fill:"#ffffff","pointer-events":"none"}));
      }
      SVG.appendChild(el("circle",{cx:cx+11,cy:cy-11,r:8, fill:"#111418", stroke:"#ffffff","stroke-width":1.5,"pointer-events":"none"}));
      const badge=el("text",{x:cx+11,y:cy-11, "text-anchor":"middle","dominant-baseline":"central","font-size":11,"font-weight":800, fill:"#ffffff","pointer-events":"none"});
      badge.textContent=(i+1); SVG.appendChild(badge);
    });
    }
  }
  // 道フェーズ（シミュ／対局の初期配置）: 置ける道を提示し、最善の向きを強調
  const roadFrom = (sim && sim.phase==="road") ? sim.lastSettle
                 : (game && game.phase==="setup" && game.setup && game.setup.phase==="road") ? game.setup.lastSettle
                 : null;
  if(roadFrom!=null){
    const ranked=bestRoadFrom(roadFrom);
    const bestEid=ranked.length?ranked[0].eid:null;
    for(const e of GEO.edges){
      if((e.a!==roadFrom&&e.b!==roadFrom) || ownerOf("roads",e.id)) continue;
      const a=GEO.vertices[e.a],b=GEO.vertices[e.b];
      const isBest=(e.id===bestEid);
      SVG.appendChild(el("line",{x1:TX(a.x),y1:TY(a.y),x2:TX(b.x),y2:TY(b.y),
        stroke:isBest?"#ffffff":"var(--gold)","stroke-width":isBest?7:4,"stroke-linecap":"round",
        opacity:isBest?.9:.45,"pointer-events":"none"}));
      if(isBest){
        const mx=(TX(a.x)+TX(b.x))/2, my=(TY(a.y)+TY(b.y))/2;
        SVG.appendChild(el("circle",{cx:mx,cy:my,r:8,fill:"#111418",stroke:"#ffffff","stroke-width":1.5,"pointer-events":"none"}));
        const t=el("text",{x:mx,y:my,"text-anchor":"middle","dominant-baseline":"central","font-size":11,"font-weight":800,fill:"#ffffff","pointer-events":"none"});
        t.textContent="1"; SVG.appendChild(t);
      }
    }
  }

  // 頂点（開拓地・都市）
  for(const v of GEO.vertices){
    const cx=TX(v.x),cy=TY(v.y);
    const _rp2=curReplay();
    const owner = _rp2 ? _rp2.sett[v.id] : ownerOf("settlements",v.id);
    let cityOwner = _rp2 ? _rp2.city[v.id] : null;
    if(!_rp2){ for(let p=1;p<=numPlayers;p++){ const pl=placements[p]; if(pl&&pl.cities&&pl.cities.has(v.id)){ cityOwner=p; break; } } }
    if(cityOwner){
      // 都市: 上向きの三角形（開拓地の菱形とはっきり別形・金の縁）
      const s=12;
      SVG.appendChild(el("polygon",{points:`${cx},${cy-s} ${cx-s},${cy+s*0.85} ${cx+s},${cy+s*0.85}`,
        class:"settle", fill:PCOLORS[cityOwner-1], stroke:"#e6bd4a","stroke-width":2, "stroke-linejoin":"round"}));
    } else if(owner){
      // 開拓地: 小さめの菱形
      SVG.appendChild(el("rect",{x:cx-6,y:cy-6,width:12,height:12,rx:2,class:"settle",
        fill:PCOLORS[owner-1], stroke:"#0d0f13", "stroke-width":1.5,
        transform:`rotate(45 ${cx} ${cy})`}));
    }
    SVG.appendChild(el("circle",{cx,cy,r:5,class:"vtx","pointer-events":"none"}));
    const hitv=el("circle",{cx,cy,r:13,fill:"transparent",style:"cursor:pointer",role:"button",tabindex:0,"aria-label":`頂点 ${v.id}`});
    hitv.addEventListener("click",()=>clickVertex(v.id));
    hitv.addEventListener("keydown",ev=>{if(ev.key==="Enter"||ev.key===" "){ev.preventDefault();clickVertex(v.id);}});
    hitv.addEventListener("mouseenter",()=>showVtxPip(v.id));
    hitv.addEventListener("mouseleave",hideVtxPip);
    SVG.appendChild(hitv);
  }

  if(_placePreview&&_placePreview.type==="vertex"){
    const v=GEO.vertices[_placePreview.id],cx=TX(v.x),cy=TY(v.y),col=PCOLORS[_placePreview.seat-1];
    if(_placePreview.kind==="city") SVG.appendChild(el("polygon",{points:`${cx},${cy-15} ${cx-15},${cy+13} ${cx+15},${cy+13}`,class:"placement-preview-piece",fill:col,"pointer-events":"none"}));
    else SVG.appendChild(el("rect",{x:cx-9,y:cy-9,width:18,height:18,rx:2,class:"placement-preview-piece",fill:col,transform:`rotate(45 ${cx} ${cy})`,"pointer-events":"none"}));
    const label=el("text",{x:cx,y:cy-24,class:"placement-preview-label","text-anchor":"middle","pointer-events":"none"});label.textContent="もう一度で確定";SVG.appendChild(label);
  }

  // 盗賊フェーズ: おすすめの止め先に★
  if(game && game.phase==="robber"){
    const ra=robberAdvice();
    if(ra){ const hx=GEO.hexes[ra.hid];
      SVG.appendChild(el("circle",{cx:TX(hx.cx),cy:TY(hx.cy),r:20,fill:"none",stroke:"#ffd75e","stroke-width":3,"stroke-dasharray":"5 4","pointer-events":"none"}));
      const s=el("text",{x:TX(hx.cx),y:TY(hx.cy)-28,"text-anchor":"middle","font-size":14,"font-weight":800,fill:"#ffd75e","pointer-events":"none"});
      s.textContent="★おすすめ"; SVG.appendChild(s);
    }
  }
  // 対局mainフェーズ: 最善手のターゲットを盤面に★でマーク
  if(game && game.phase==="main"){
    const adv=computeAdvice().filter(a=>a.can && a.target);
    if(adv.length){
      const t=adv[0].target;
      let mx,my;
      if(t.type==="vertex"){ const v=GEO.vertices[t.id]; mx=TX(v.x); my=TY(v.y); }
      else { const e=GEO.edges[t.id]; const a=GEO.vertices[e.a],b=GEO.vertices[e.b]; mx=(TX(a.x)+TX(b.x))/2; my=(TY(a.y)+TY(b.y))/2; }
      SVG.appendChild(el("circle",{cx:mx,cy:my,r:17,fill:"none",stroke:"#ffd75e","stroke-width":3,"stroke-dasharray":"5 4","pointer-events":"none"}));
      const s=el("text",{x:mx,y:my-24,"text-anchor":"middle","font-size":14,"font-weight":800,fill:"#ffd75e","pointer-events":"none"});
      s.textContent="★おすすめ"; SVG.appendChild(s);
    }
  }
  // 盗賊は必ず1体だけ描画する。リプレイ中は最終局面の game.robber ではなく現在コマを優先。
  const _rpR=curReplay();
  const _robberHex = (_rpR && _rpR.robber!=null) ? _rpR.robber
                   : (game && game.robber!=null ? game.robber : null);
  if(_robberHex!=null){
    const h=GEO.hexes[_robberHex];
    if(h) SVG.appendChild(el("circle",{cx:TX(h.cx),cy:TY(h.cy),r:10,fill:"#111418",stroke:"#e6bd4a","stroke-width":2,opacity:.95,"pointer-events":"none","data-piece":"robber"}));
  }

  // 港ツールのとき、置ける海岸線をうっすら表示
  if(tool==="port"){
    for(const e of GEO.edges){
      if(!BOUNDARY.has(e.id) || ports[e.id]) continue;
      const a=GEO.vertices[e.a], b=GEO.vertices[e.b];
      SVG.appendChild(el("line",{x1:TX(a.x),y1:TY(a.y),x2:TX(b.x),y2:TY(b.y),
        stroke:"var(--gold)","stroke-width":2,"stroke-dasharray":"3 3",opacity:.35,"pointer-events":"none"}));
    }
  }

  // 港マーカー(海岸線の外側に描く)
  for(const eid in ports){
    const type=ports[eid], e=GEO.edges[eid];
    const a=GEO.vertices[e.a], b=GEO.vertices[e.b];
    const mx=(a.x+b.x)/2, my=(a.y+b.y)/2, len=Math.hypot(mx,my)||1, off=0.34;
    const px=TX(mx+mx/len*off), py=TY(my+my/len*off);
    const col = type==="3:1" ? "#c9a94a" : RES_COLOR[type];
    SVG.appendChild(el("line",{x1:px,y1:py,x2:TX(a.x),y2:TY(a.y),stroke:col,"stroke-width":1.5,opacity:.55,"pointer-events":"none"}));
    SVG.appendChild(el("line",{x1:px,y1:py,x2:TX(b.x),y2:TY(b.y),stroke:col,"stroke-width":1.5,opacity:.55,"pointer-events":"none"}));
    SVG.appendChild(el("circle",{cx:px,cy:py,r:11,fill:col,stroke:"#0d0f13","stroke-width":1.5,"pointer-events":"none"}));
    const t=el("text",{x:px,y:py,"text-anchor":"middle","dominant-baseline":"central",
      "font-size": type==="3:1"?8:11, "font-weight":700, fill:"#20242b","pointer-events":"none"});
    t.textContent=PORT_MARK[type]; SVG.appendChild(t);
  }
  updateStats();
}

// --- ルール判定 ----------------------------------------------------------
function vertexPip(vid){ return GEO.vertex_hexes[vid].reduce((s,h)=> s + (board[h].number?PIP[board[h].number]:0), 0); }
function vertexResources(vid){ return [...new Set(GEO.vertex_hexes[vid].map(h=>board[h].resource).filter(r=>r&&r!=="desert"))]; }

function clickVertex(vid){
  if(game){ if(typeof gamePlacementTap==="function"&&gamePlacementTap("vertex",vid))return; gameClickVertex(vid); aiMaybeGo(); return; }
  if(sim){
    if(sim.phase!=="settle"){ toast("いまは道を置く番です（金色の候補）"); return; }
    if(ownerOf("settlements",vid)){ toast("そこは使用中です"); return; }
    for(const n of GEO.vertex_neighbors[vid]) if(ownerOf("settlements",n)){ toast("隣に開拓地があるため置けません"); return; }
    placements[sim.active].settlements.add(vid);
    sim.history.push({type:"settle",id:vid,p:sim.active});
    simSync(); render(); updateSimStatus(); return;
  }
  if(tool==="port"){ toast("いまは港ツールです（配置に切り替えてください）"); return; }
  const owner=ownerOf("settlements",vid);
  if(owner===active){ placements[active].settlements.delete(vid);
    if(composerOn){ const i=composerOrder.findIndex(o=>o.vid===vid&&o.p===active); if(i>=0) composerOrder.splice(i,1); }
    render(); if(composerOn && typeof updateComposerBar==="function") updateComposerBar(); return; }
  if(owner){ toast(`頂点 ${vid} はP${owner}が使用中`); return; }
  // 距離ルール：隣接頂点に誰かの開拓地があると置けない
  for(const n of GEO.vertex_neighbors[vid]) if(ownerOf("settlements",n)){ toast("隣に開拓地があるため置けません"); return; }
  placements[active].settlements.add(vid);
  if(composerOn) composerOrder.push({p:active, vid});
  render(); if(composerOn && typeof updateComposerBar==="function") updateComposerBar();
}

function endSim(){ sim=null; const sb=document.getElementById("simBox"); if(sb) sb.style.display="none"; }

// 履歴から「今どのフェーズ・誰の番・直前の開拓地」を復元
function simSync(){
  if(!sim) return;
  const settles=sim.history.filter(x=>x.type==="settle").length;
  const roads=sim.history.filter(x=>x.type==="road").length;
  sim.step=roads;                                   // 完了したターン数
  if(settles>roads){                                // 開拓地は置いたが道が未
    sim.phase="road"; sim.active=sim.order[sim.step];
    sim.lastSettle=[...sim.history].reverse().find(x=>x.type==="settle").id;
  } else if(sim.step<sim.order.length){             // 次のターンの開拓地から
    sim.phase="settle"; sim.active=sim.order[sim.step]; sim.lastSettle=null;
  } else { sim.phase="done"; sim.active=null; sim.lastSettle=null; }
  active=sim.active||active;
}

function updateSimStatus(){
  if(!sim) return;
  const box=document.getElementById("simStatus");
  if(sim.phase==="done"){ box.innerHTML="配置完了！ 残りの最善候補を色で表示中。"; return; }
  const p=sim.active, round = sim.step < sim.order.length/2 ? "1巡目" : "2巡目", turn=sim.step+1;
  if(sim.phase==="settle"){
    box.innerHTML=`<b style="color:${PCOLORS[p-1]}">P${p}</b>（${round} ${turn}/${sim.order.length}）：<b>開拓地</b>を置いてください<br><span class="small">色が濃い頂点ほど良い候補。①が現時点の最善です。</span>`;
  } else {
    box.innerHTML=`<b style="color:${PCOLORS[p-1]}">P${p}</b>（${round} ${turn}/${sim.order.length}）：<b>道</b>を置いてください<br><span class="small">金色の線が置ける道です。</span>`;
  }
}

function clickEdge(eid){
  if(game){ if(typeof gamePlacementTap==="function"&&gamePlacementTap("edge",eid))return; gameClickEdge(eid); aiMaybeGo(); return; }
  if(sim){
    if(sim.phase!=="road"){ toast("先に開拓地を置いてください"); return; }
    if(ownerOf("roads",eid)){ toast("その道は使用中です"); return; }
    const e=GEO.edges[eid];
    if(e.a!==sim.lastSettle && e.b!==sim.lastSettle){ toast("直前に置いた開拓地に接する道を選んでください"); return; }
    placements[sim.active].roads.add(eid);
    sim.history.push({type:"road",id:eid,p:sim.active});
    simSync(); render(); updateSimStatus(); return;
  }
  if(tool==="port"){ return clickPort(eid); }
  const owner=ownerOf("roads",eid);
  if(owner===active){ placements[active].roads.delete(eid); render(); return; }
  if(owner){ toast(`辺 ${eid} はP${owner}が使用中`); return; }
  const e=GEO.edges[eid];
  const mine=placements[active];
  const touchesSettle = mine.settlements.has(e.a)||mine.settlements.has(e.b);
  const touchesRoad = [...mine.roads].some(rid=>{ const r=GEO.edges[rid]; return [r.a,r.b].includes(e.a)||[r.a,r.b].includes(e.b); });
  if(!touchesSettle && !touchesRoad){ toast("自分の開拓地か街道に接していません"); return; }
  mine.roads.add(eid);
  render();
}

// --- タイル編集 ----------------------------------------------------------
function clickHex(id){
  if(game){ gameClickHex(id); aiMaybeGo(); return; }
  selectedHex = (selectedHex===id) ? null : id;
  render(); updateTilePicker();
}
function setResource(r){
  if(selectedHex==null){ toast("先にタイルを選んでください"); return; }
  board[selectedHex].resource = r;
  if(r==="desert") board[selectedHex].number = null;
  render(); updateTilePicker();
}
function setNumber(n){
  if(selectedHex==null){ toast("先にタイルを選んでください"); return; }
  if(board[selectedHex].resource==="desert"){ toast("砂漠には数字を置けません"); return; }
  board[selectedHex].number = (board[selectedHex].number===n) ? null : n;  // 同じ数字で解除
  render(); updateTilePicker();
}
function blankBoard(){
  board = {};
  for(const h of GEO.hexes) board[h.id] = {resource:null, number:null};
  ports = {};
  selectedHex = null;
}
function buildTilePicker(){
  const rp=document.getElementById("resPicker"); rp.innerHTML="";
  for(const r of RES_LIST){
    const b=document.createElement("button"); b.className="swatch"; b.dataset.res=r;
    b.innerHTML=`<span class="sw" style="background:${RES_COLOR[r]}"></span>${RES_JP[r]}`;
    b.onclick=()=>setResource(r);
    rp.appendChild(b);
  }
  const np=document.getElementById("numPicker"); np.innerHTML="";
  for(const n of NUM_LIST){
    const b=document.createElement("button");
    b.className="numbtn"+((n===6||n===8)?" hot":""); b.dataset.num=n;
    b.textContent=n; b.onclick=()=>setNumber(n);
    np.appendChild(b);
  }
  updateTilePicker();
}
function updateTilePicker(){
  const info = selectedHex==null ? null : board[selectedHex];
  document.getElementById("selHex").textContent = selectedHex==null
    ? "盤面のタイルをクリックして選ぶ"
    : `選択中: タイル #${selectedHex}（${info.resource?RES_JP[info.resource]:"未設定"}${info.number?" / "+info.number:""}）`;
  document.querySelectorAll("#resPicker .swatch").forEach(b=>
    b.classList.toggle("on", !!info && b.dataset.res===info.resource));
  document.querySelectorAll("#numPicker .numbtn").forEach(b=>{
    const isDesert = !!info && info.resource==="desert";
    b.disabled = (selectedHex==null) || isDesert;
    b.classList.toggle("on", !!info && Number(b.dataset.num)===info.number);
  });
  const cnt={}; RES_LIST.forEach(r=>cnt[r]=0);
  for(const h of GEO.hexes){ const r=board[h.id].resource; if(r) cnt[r]++; }
  document.getElementById("tileTally").textContent =
    "配置済 " + RES_LIST.map(r=>`${RES_JP[r]}${cnt[r]}/${RES_COUNTS[r]}`).join("  ");
}

// --- 港 ------------------------------------------------------------------
function clickPort(eid){
  if(!BOUNDARY.has(eid)){ toast("港は外周(海岸線)の辺だけに置けます"); return; }
  if(ports[eid]===activePort){ delete ports[eid]; render(); return; }
  ports[eid]=activePort; render();
}
// 境界辺どうしの隣接（頂点を共有する海岸線の辺）
// 港は公式固定盤面の9つの入り江に置き、「どの入り江がどの資源港か」だけを変える。
function randomPorts(){ officialPorts(); }
function buildPortPicker(){
  const box=document.getElementById("portPicker"); box.innerHTML="";
  for(const t of PORT_LIST){
    const b=document.createElement("button"); b.className="swatch"+(t===activePort?" on":""); b.dataset.port=t;
    const col=t==="3:1"?"#c9a94a":RES_COLOR[t];
    b.innerHTML=`<span class="sw" style="background:${col}"></span>${PORT_LABEL[t]}`;
    b.onclick=()=>{
      activePort=t; tool="port";
      document.querySelectorAll("#tool button").forEach(x=>x.classList.toggle("on",x.dataset.tool==="port"));
      buildPortPicker(); render();
    };
    box.appendChild(b);
  }
}

// --- 頂点pipプレビュー ---------------------------------------------------
function showVtxPip(vid){
  const cx=TX(GEO.vertices[vid].x), cy=TY(GEO.vertices[vid].y);
  const g=el("g",{id:"vpip"});
  const w=44;
  g.appendChild(el("rect",{x:cx-w/2,y:cy-30,width:w,height:18,rx:5,fill:"#0f1216",stroke:"var(--gold)","stroke-width":1}));
  const t=el("text",{x:cx,y:cy-21,"font-size":11,"text-anchor":"middle","dominant-baseline":"central",fill:"var(--gold)","font-family":"Space Grotesk"});
  t.textContent="pip "+vertexPip(vid);
  g.appendChild(t);
  SVG.appendChild(g);
}
function hideVtxPip(){ const g=document.getElementById("vpip"); if(g) g.remove(); }

// --- パネル更新 ----------------------------------------------------------
function updateStats(){
  const box=document.getElementById("stats"); box.innerHTML="";
  for(let p=1;p<=numPlayers;p++){
    const settles=[...placements[p].settlements];
    const pip=settles.reduce((s,v)=>s+vertexPip(v),0);
    const resSet=new Set(); settles.forEach(v=>vertexResources(v).forEach(r=>resSet.add(r)));
    const resTxt=[...resSet].map(r=>RES_JP[r]).join("・")||"—";
    const sset=new Set(settles); const portSet=new Set();
    for(const eid in ports){ const e=GEO.edges[eid]; if(sset.has(e.a)||sset.has(e.b)) portSet.add(ports[eid]); }
    const portTxt=portSet.size?`<br>港:${[...portSet].map(t=>PORT_MARK[t]).join(" ")}`:"";
    const row=document.createElement("div"); row.className="stat";
    row.innerHTML=`<span class="name"><span class="dot" style="background:${PCOLORS[p-1]}"></span>P${p}</span>
      <span class="res">${settles.length}軒 / ${placements[p].roads.size}道<br>${resTxt}${portTxt}</span>
      <span class="pip">${pip}</span>`;
    box.appendChild(row);
  }
}

function buildPlayers(){
  const box=document.getElementById("players"); box.innerHTML="";
  for(let p=1;p<=numPlayers;p++){
    const b=document.createElement("button");
    b.className="pbtn"+(p===active?" on":""); b.style.setProperty("--dot",PCOLORS[p-1]);
    b.innerHTML=`<span class="dot" style="background:${PCOLORS[p-1]}"></span><small>P${p}</small>`;
    b.onclick=()=>{ active=p; buildPlayers(); };
    box.appendChild(b);
  }
}
// --- 入出力 --------------------------------------------------------------
function toJSON(){
  return {
    board:{ hexes: GEO.hexes.map(h=>({id:h.id,q:h.q,r:h.r,resource:board[h.id].resource,number:board[h.id].number})) },
    ports: Object.entries(ports).map(([e,t])=>({edge:Number(e),type:t})),
    // 棋譜は「再生中かどうか」に関係なく、データがあれば必ず書き出す
    // （旧: replay.active が false だと棋譜が欠落してエクスポートされる不具合）
    replay: (replay && replay.turns && replay.turns.length) ? replay.turns
          : ((typeof game!=="undefined" && game && game.turns && game.turns.length) ? game.turns : undefined),
    placements: Object.fromEntries(
      Array.from({length:numPlayers},(_,i)=>i+1).map(p=>[p,{
        settlements:[...placements[p].settlements].sort((a,b)=>a-b),
        cities: placements[p].cities ? [...placements[p].cities].sort((a,b)=>a-b) : [],
        roads:[...placements[p].roads].sort((a,b)=>a-b)
      }])),
    winner,                                           // 本当の勝者
    label: (bestPlayer!==null ? bestPlayer : winner), // 学習ラベル（最善とみなす人。既定は勝者）
    source: dataSource                                // 出どころ（実戦=colonist / 自己対戦=selfplay / 手入力=manual）
  };
}
// --- トースト ------------------------------------------------------------
let toastTimer;
function toast(msg){
  const t=document.getElementById("toast"); t.textContent=msg; t.classList.add("show");
  clearTimeout(toastTimer); toastTimer=setTimeout(()=>t.classList.remove("show"),1800);
}

// ===== 棋譜（リプレイ）ビューア: 新レイアウト用に温存 =====
let replay = null; // {turns, idx, active}
function curReplay(){ return (replay && replay.active) ? replay.turns[replay.idx] : null; }
function showReplayTurn(){
  if(!replay) return;
  const t=replay.turns[replay.idx];
  document.getElementById("rvTitle").textContent=t.title;
  document.getElementById("rvCount").textContent=`${replay.idx+1} / ${replay.turns.length} コマ`;
  const hb=document.getElementById("rvHands");
  if(hb){
    if(t.hands && Object.keys(t.hands).length){
      const RJ=["wood","brick","sheep","wheat","ore"];
      let s='<table style="width:100%; border-collapse:collapse; font-size:12px">';
      s+='<tr><th style="text-align:left">席</th>'+RJ.map(r=>`<th style="padding:2px 3px">${RES_JP[r]}</th>`).join("")
         +'<th style="padding:2px 3px">計</th><th style="padding:2px 3px">カード</th><th style="padding:2px 3px">VP</th></tr>';
      for(const p of Object.keys(t.hands)){
        const hh=t.hands[p]; const res=hh.res||{};
        const tot=RJ.reduce((a,r)=>a+(res[r]||0),0);
        const isTurn = String(t.player)===String(p);
        s+=`<tr style="${isTurn?'background:rgba(255,255,255,.05)':''}">`
          +`<td style="padding:2px 3px"><span style="color:${PCOLORS[p-1]};font-weight:700">P${p}</span></td>`
          +RJ.map(r=>`<td style="text-align:center;padding:2px 3px">${res[r]||0}</td>`).join("")
          +`<td style="text-align:center;padding:2px 3px;font-weight:600">${tot}</td>`
          +`<td style="text-align:center;padding:2px 3px">${hh.dev||0}</td>`
          +`<td style="text-align:center;padding:2px 3px">${hh.vp!=null?hh.vp:"-"}</td></tr>`;
      }
      hb.innerHTML=s+'</table>';
    } else {
      hb.innerHTML='<div style="font-size:12px;color:var(--faint)">（この棋譜には手札の記録がありません）</div>';
    }
  }
  document.getElementById("rvEvents").innerHTML=(t.events.length?t.events:["（イベントなし）"]).map(x=>`<div>${x}</div>`).join("");
  render();
}
function exitReplay(){ if(replay) replay.active=false; var _rb=document.getElementById("replayBar"); if(_rb) _rb.style.display="none"; }

// ===== 起動: 新レイアウト用に最小化（エディタUIビルダー・serverUrl・render は呼ばない） =====
